window.HB_TR["1-samuel"]["ks"]=["1.\\tاَتھ اوس اَفرائیم پہاڑُک اَکھ شخٕص تہٕ تٔمؠ سُند ناو اوس الکنہ، یُس یِروہَم سُند نیٚچُو، یُس توہو سُند نیچو اوس، یُس اَفراتھِس سٍتـ̡ نیچو اوس۔\n2. تہٕ أمِس آسہٕ زٕ زنانہٕ۔ أکِس سُند ناو اوس حناہ تہٕ بییِس پنینہ سُند ناو: تہٕ پنینہ اوس شُرۍ، مگر ہناہ اوس نہٕ کانہہ شُر۔\n3. تہٕ یہِ شخٕص اوس سالانہٕ سالانہٕ پَنٕنہِ شہرٕ نیبر نیران شِلوہس مَنٛز لشکرن ہٕندِس رب سٕندِ خٲطرٕ عبادت کرنہٕ تہٕ قربان کرنہٕ خٲطرٕ۔ تہٕ ایلی سٕندۍ زٕ نیچوۍ، ہوفنی تہٕ فینہاس، خداوند سٕندِ پادٕرۍ، ٲسۍ تتہِ۔ {سالانہٕ: ہیب۔ ؤری پتہٕ ؤری}\n4. تہٕ ییلہ الکنہ ہٕندِس وقتس سٍتـ̡ پیش کٔر، تٔمۍ دِژ پنٕنۍ زنانہٕ تہٕ تٔمۍ سٕندِس سارِنٕے نیٚچوِس تہٕ تٔمۍ سٕنزِ کورِ ہٕندِس حِصہٕ۔\n5. مگر ہناہس دیت تٔمۍ اکھ قٲبل حصہٕ۔ تکیازِ تس اوس حناہس محبت کران: مگر خداوند اوس تٔمۍ سُند رحم بند کورمُت۔ {قٲبل: یا، ڈبل}\n6.\\tتہٕ تٔمۍ سٕندِس مُخٲلفن تہِ دِژ أمِس دَگ دِنہٕ، تکیازِ خداوند اوس تٔمِس کُن بند کورمُت۔ {اشتعال دِنہٕ: ہیب۔ شرارت}\n7.\\tتہٕ یِتھٕ پٲٹھـ̡ اوس أمِس ؤری پتہٕ ؤری یێلہِ یێلہِ سُہ خداوند سٕندِس گرس تام وٲتِتھ، تێلہِ کٔر أمِس اشتعال۔ تَمہِ کِنۍ روو سُہ تہٕ کھیوٚن نہٕ۔ {ییلہ...: یا، تمہ وقتہ پیٹھہ ییلہ سۅ بیترِ: ہیب۔ تٔمۍ سٕنٛدِ ہیوٚر گَژھنہٕ نِش}\n8.\\tاَمہ پتہٕ ووٚن الکانہ تٔمِس خانٛدار، حنا، ژیہ کیازِ چُھکھ روُن؟ تہٕ ژیہ کیازِ چھکھ نہٕ؟ تہٕ تُہند دِل کیازِ چُھ غم؟ {کیا بہٕ چُھس نہٕ ژےٚ خٲطرٕ دہن نیچویو کھوتہٕ بہتر؟\n9.\\tتہ ووٚتھ ہنا شِلوہس منز کھٮ۪نہٕ پتہٕ تہٕ شرابہٕ کھٮ۪نہٕ پتہٕ۔ وۅنۍ اوس ایلی پادٕرۍ خداوند سٕندِس مندرس نِش أکِس نشستس پیٹھ بِہتھ۔\n10.\\tتہٕ سۅ ٲس روحہٕ سٕنزِ تلخی سٍتـ̡ تہٕ کٔرٕن خداوند سٕندِس دُعا سٍتـ̡ دُعا تہٕ رووُن دَرٕ۔ {منز...: ہیب۔ روحُک تلخ}\n11.\\tتہٕ تٔمۍ کٔر اکھ عہد تہٕ وونُن، اے خداوند، اگر ژٕ پٔزۍ پٲٹھـ̡ پننہِ دٲیرِ ہٕندِس مصیبت وُچھِتھ تہٕ مے یاد تھاوُن، تہٕ پنٕنۍ نوکرِ مٔشِد کٔرِتھ تہٕ پَنٕنـ̡ دٲیرٕ دِیُن، تێلہِ دِیہٕ بہٕ سُہ سارِنٕے دۅہہٕ خداوند سٕندِس سٍتـ̡ دِنہٕ، تہٕ تٔمِس کَلس پیٹھ گژھہِ نہٕ کانہہ ریزر۔ {اکھ انسان...: ہیب۔ مردن ہند بیج}\n12.\\tتہٕ سپُد یہِ سپدُن، یێلہِ سُہ خداوند سٕندِس برونہہ کُن دُعا کران چُھ، تہٕ ایلی ین کٔر تٔمِس ٲسِس نِشانہٕ۔ {جٲری...: ہیب۔ دعا کرنہٕ خٲطرٕ گٔیہٕ ضرب کرنہٕ}\n13. وۅنۍ ہنا، تٔمۍ کٔر پننِس دلس منز کتھ کرنہٕ۔ صرف اوس تسند وٹھ ہلکان مگر آواز بوز نہ، لہذا اوس ایلی باسیومت زِ سۅ چھیہ شراب۔\n14.\\tتہٕ ایلی ین ووٚن أمِس زِ ژیہ کٲتِس کالس چُھہ شراب؟ پَنُن شَراب ترٛٲوِو پانَس نِش۔\n15. تہٕ ہناہ دیت جواب تہٕ وونُن، نہ، میانہِ آقا، بہٕ چُھس غمگسار روحٕچ زنانہٕ: بہٕ چُھس نہٕ شراب چِھمُت تہٕ نہ چُھس شراب، بلکہ چُھس خداوند سٕندِ برونہہ کُن پنُن روح تروومُت۔ {اکھ غم...: ہیب۔ ہارڈ آف اسپرٹ}\n16.\\tپننہِ دٲیرِ ہٕنزِ کورِ ہٕندِس سٍتـ̡ گٔنزراوٕن، تکیازِ میانہِ شکایژ تہٕ غمٕچ کثرت سٍتـ̡ چھے مے وُنیُک تام کتھ کٔرمٕژ۔ {شکایت: یا، مراقبہ}\n17.\\tاَمہِ پَتہٕ دِیُت ایلی یَن جواب تہٕ وونُن، امن سان گژھُن، تہٕ اسرٲیلُک خدایہ دِژ تُہٕنز عرضی یۄس ژے أمِس منگمٕژ چھےٚ۔\n18.\\tتہٕ ووٚن تٔمۍ سٕنزِ دٲیرِ چانہِ ہٕندِس نظرس مَنٛز رحمت۔ چنانچہ زنانہِ گٔیہِ پننہِ وتہِ تہ کھیوٚن کھیوٚن، تہٕ تٔمۍ سُند بُتھ اوس نہٕ وۅنۍ غم۔\n19.\\tتہٕ تِم ووٚتھِ صُبحے سُلہِ تہٕ کٔرٕکھ خداوند سٕندِس برونہہ کُن عبادت تہٕ واپس گٔیہِ تہٕ آیہ پننِس مکانس منز رامہ کُن: تہٕ الکانہ اوس پننہِ زنانہِ ہناہ زانان۔ تہٕ خداوند اوس سُہ یاد۔\n20. اَمہِ مۄکھٕ سپُد یێلہِ ہناہ سٕندِ حاملہٕ گژھنہٕ پتہٕ وق آو زِ أمِس زیٚو اکھ نیٚچُو، تہٕ وونُن أمِس سموئیل ناو، {وَنُن}، کیازِ مے چُھس أمِس خداوند سٕندِ سٍتـ̡ پرژھمُت۔ {ییلہ...: ہیب۔ دۅہن ہٕندِس انقلابس منز} {سیموئیل: یعنی، خدایہ سٕندِ سٍتـ̡ پرژھنہٕ آمُت}\n21.\\tتہٕ انسان الکانہ تہٕ تٔمۍ سُند سورُے گرٕ گۆو خداوند سٕندِ خٲطرٕ سالانہٕ قربانی تہٕ تٔمۍ سُند عہد پیش کرنہٕ خٲطرٕ۔\n22. مگر ہنا ووت نہٕ تھوٚد۔ تکیازِ تٔمۍ ووٚن پننِس خاندارس زِ {بہٕ گژھہٕ نہٕ توٚت تام ہیوٚر کھسنہٕ} یوٚت تام نہٕ شُر دۄد دِنہٕ، تہٕ {پتہٕ} بہٕ أنِتھ سُہ یُس خداوند برونہہ کُن ظٲہر سپدِ، تہٕ اَتہِ روزِ ہمیشہٕ خٲطرٕ۔\n23.\\tتہٕ ایلکانہ تٔمۍ سٕندِس خاوندس ووٚن أمِس یُس تہٕ ژیہ رژھ کر۔ یوٚت تام نہ ژیہ أمس دوٚد دِنہٕ آسہِ۔ صرف خداوند چُھ پنُن کلام قایم کران۔ چنانچہ زنانہِ روزُن تہ دِژن نیچوس یوٚت تام نہ تس دوٚد دِتھ۔\n24.\\tتہٕ ییلہ أمِس دۄد دِژ، سُہ نِیہِ پانس سٍتـ̡ تریہ بیل، تہٕ اکھ ایفا آٹہٕ تہٕ شرابٕچ اکھ بوتلہٕ ہٮ۪تھ، تہٕ أنِن سُہ شیلوہس مَنٛز خداوند سٕندِس گَرَس مَنٛز۔\n25.\\tتہٕ تِمو مٲرِتھ اکھ دانٛد تہٕ أنِن شُر ایلی نِش۔\n26.\\tتہٕ تٔمۍ ووٚن، اے میانہِ آقا، یێلہِ چُھہ تُہند روح زندٕ، میانہِ آقا، بہٕ چُھس سۄ زنانہٕ یۄس یێتہِ ژے سٍتـ̡ کھڑا ٲس، خداوند سٕندِ دُعا کران ٲس۔\n27. أمِس شُرۍ سٕندِ خٲطرٕ کٔر میہ دُعا۔ تہٕ خداوند دِژ میہ میٲنۍ عرضی یۄس میہ أمِس نِش پرژھمٕژ چھےٚ:\n28. تێمہِ کِنۍ تہِ چُھس مے سُہ خداوند سٕندِس دِنہٕ آمُت۔ یوتام سُہ زندٕ روزِ، سُہ گژھہِ خداوند سٕندِ خٲطرٕ دِنہٕ۔ تہٕ سُہ اوس تتہِ خداوند سٕنز پوٗزا کران۔ {أمِس دِیُت: یا دِیُت أمِس واپس، یُس مےٚ عرضی ہٕندِ ذٔریعہٕ حٲصِل کورمُت چھُ} {سُہ کرِ...: یا یُس میہ عرضی ذریعہ حٲصل کورمُت چُھ، سُہ ییہٕ واپس کرنہٕ}","1. تہٕ ہناہ کٔر دُعا تہٕ وونُن، میون دِل چُھ خداوند سٕندِس سٍتـ̡ شاد سپدان، میٲنۍ سینگ چُھ خداوند سٕندِس سٍتـ̡ تھزراونہٕ آمُت: میٲنۍ ٲس چُھہ میانین دُشمنن پیٹھ بٔڑِتھ ۔ تکیازِ بہٕ چُھس چانہِ نجات سٍتـ̡ خوش گژھان۔\n2. {خداوند سٕندِس پٲٹھـ̡ چُھہ نہٕ کانہہ تہِ پاک: کیازِ {چُھہ} چُھہ نہٕ سٲنـ̡ خدایہِ ہِش کانہہ کُنہِ تہِ کُنہِ تہِ کُنہ\n3. زیادٕ فخرٕ سان کتھ کرو نہٕ۔ تکبر گژھہِ نہٕ پننہِ ٲسہِ منزٕ نیرُن: کیازِ خداوند چُھ علمُک خدا، تہٕ تٔمۍ سٕندِ سٍتـ̡ چُھہ اعمال تولنہٕ یوان۔ {تکبر: ہیب۔ ہارڈ}\n4.\\tطاقتور نفرن ہٕنزِ کمان چھِ پھُٹمٕژ، تہٕ یِم ٹھوکر کھٲلِتھ چھِ، تِم چھِ طاقتہٕ سٍتـ̡ گٔنڈِتھ۔\n5. {یِم بٔرِتھ} ٲسۍ پانس روٹی خٲطرٕ کرایہ دِژمٕتۍ۔ تہٕ {تِم یِم فاقہٕ ٲسِتھ} گٔیہِ ختم: یِتھٕ کٔنۍ بنجر سَتھ زامٕتۍ۔ تہٕ سُہ یُس واریاہ شُرۍ چھُ، سُہ چُھ کمزور۔\n6. خداوند چُھ ماران تہٕ زندٕ بناوان: سُہ چُھ قبرس تام انان، تہٕ وُچھان چُھ۔\n7. خداوند چُھ غریب بناوان، تہٕ امیر بناوان: سُہ چُھ بۄن انان، تہٕ تھوٚد کَران۔\n8.\\tسُہ چُھ غریبن میژِ منزٕ تُلِتھ تُلِتھ، تہٕ تِمن شہزادن مَنٛز تھاونہٕ خٲطرٕ، تہٕ تِمن جلال کِس تختس وٲرث بناونہٕ خٲطرٕ، تکیازِ زمینہِ ہٕندِ ستون چِھہ خداوند سٕندِس تہٕ تِمن پیٹھ دُنیا تھوومُت۔\n9.\\tسُہ تھاوِ پننین مقدسن ہٕندِس قدمن تہٕ بدکار روزِ انہِ گٹہِ منز ژھۄپہٕ۔ تکیازِ طاقتہٕ سٍتۍ ہیکہِ نہٕ کانہہ تہِ انسان غالب سپدِتھ۔\n10. خداوند سٕندِ مُخٲلِف گژھن ٹُکرٕ ٹُکرٕ کرنہٕ یِن؛ آسمانہٕ منزٕ کرِ سُہ تِمن پیٹھ گرٛٮ۪ز: خداوند کرِ زمینہِ ہٕندِس اندس پیٹھ فٲصلہٕ۔ تہٕ سُہ دِیہِ پننِس بادشاہس طاقت، تہٕ کرِ پنٕنِس مسح کرنہٕ آمٕتۍ سٕندِس سینگ تھزر۔\n11.\\tتہٕ الکانہ گۆو رامہ سندس گرس منز۔ تہٕ شُرۍ کٔر پادٕرۍ ایلی سٕندِ برونہہ کُن خداوند سٕنز خدمت۔\n12. وۅنۍ ٲسۍ ایلی سٕندِ نیچوۍ بِلیال سٕندِ نیچوۍ۔ تِم ٲسۍ نہٕ خداوند سٕندِس سٍتـ̡ زانان۔\n13. تہٕ پادٕرین ہُند رواج اوس لُکن سٍتـ̡ ، یێلہِ کانہہ نَفر قربانی دِوان چُھ، پادٕرۍ سُند خادم اوس یێلہِ ماز دِوان اوس ، اتھس منز تریہ دند ہُند ماز ہُند ہُک ہُرِتھ ۔\n14.\\tتہٕ تٔمۍ لوٚگ پانس منز، یا کیتلی، یا کۅکرس منز، یا بانس منز۔ سُہ سورُے یُس ماز ہُکن تُلمت اوس پادٕرۍ پانس خٲطرٕ نِوان۔ یِتھٕ پٲٹھۍ کٔر تِمو شیلوہس مَنٛز سارِنٕے اسرٲیلِین سٍتـ̡ یِم تتہِ یِنہٕ وٲلۍ۔\n15.\\tامہ برونہہ زالنہٕ برونہہ آو پادٕرۍ سُند نوکر تہٕ وونُن یُس قربانی دِنہٕ آمُت اوس، پادٕرۍ سٕندِ خٲطرٕ دِیُن ماز دِنہٕ۔ تکیازِ تس آسہِ نہ تۅہہِ ہند ماز بلکہ خام ماز آسہِ۔\n16.\\tتہٕ اگر کٲنسہِ شخصس أمس ووٚن، تِم گژھن نہٕ وُنی چربی زالنس منز ناکام روزُن، تہٕ {تیلہٕ} تیوٗت تُہٕندِس نفس سٍتـ̡ نِنہٕ۔ اَمہ پتہٕ اوس سُہ أمِس جواب دِوان، {نہ}؛ مگر ژے دِیہ وۅنۍ میہ دِنۍ: تہٕ اگر نہ، بہٕ نِہ زبردستی نِن۔ {وٕنکین: ہیب۔ یتھ کٔنۍ زِ دۅہہ}\n17. تێمہِ کِنۍ اوس نوجوانَن ہُند گۅناہ خداوند سٕندِ برونہہ کُن سٮ۪ٹھاہ بوٚڈ ، تکیازِ انسان ٲسۍ خداوند سٕنزِ نذرانہٕ سٍتـ̡ نفرت۔\n18.\\tمگر سموئیل کٔر خداوند سٕندِ برونہہ کُن خدمت، یُس اکھ شُر اوس، یُس کُنہِ\n19.\\tامہِ علاوٕ بنوو تٔمِس ماجہ اکھ لۄکُٹ کوٹ، تہٕ ؤری پتہٕ ؤری أمِس نِش أنِتھ، ییلہ سُہ پننِس خاوندس سٍتۍ سالانہٕ قربانی دِنہٕ خٲطرٕ آیہ۔\n20. تہٕ ایلی ین کٔر الکانہ تہٕ تٔمۍ سٕنزِ زنانہِ برکت تہٕ وونُن، خداوند دِژ ژے امہِ زنانہِ ہُند بیول یُس خداوند دِنہٕ آمُت چُھ۔ تہٕ تِم گٔیہِ پننِس گرس منٛز۔ {قرض...: یا، عرضی یُس تٔمۍ منگمُت وغیرہ}\n21.\\tتہٕ خداوند گۆو حناہس نِش تہٕ تٔمِس زاے ترے نیچوۍ تہٕ زٕ کورِ۔ تہٕ شُر سموئیل گوو خداوند برونہہ کُن۔\n22.\\tوُنہِ اوس ایلی سٮ۪ٹھاہ بُزرگ تہٕ بوزُن یُس تٔمۍ سٕندِس نیچویو سارِنٕے اسرٲیلس سٍتـ̡ کٔرۍ۔ تہٕ کِتھ کٔنۍ ٲسۍ تِمن زنانن سٍتـ̡ یِم جماعت کِس خیمہ کِس دروازس پیٹھ جمع گٔیہِ۔ {جمع: ہیب۔ فوجن ہٕنٛد ذریعہٕ جمع کرنہٕ}\n23.\\tتہٕ تٔمۍ ووٚن تِمن زِ تُہۍ کیازِ چھِو یِتھٕ کتھہٕ کران؟ تکیازِ بہٕ چُھس یمن سارِنٕے لوٗکن ہٕندِ طرفہٕ تُہند بد سلوک بوزان۔ {تُہٕندِ...: یا، بد کلام}\n24. نہ، میٲنۍ نیچو۔ تکیازِ {یہ} چُھنہٕ کانہہ اصل خبر یُس بہٕ بوزان چُھ: تہٕ چُھہ خداوند سٕندِس لوکن خلاف ورزی کران ۔ {زیادٕ: یا، کرٛیٚو}\n25. یێلہِ اَکھ شخٕص بیٚیِس خٕلاف گۅناہ کٔرِ، قاضی کرِ أمِس سٍتـ̡ فٲصلہٕ، مگر یێلہِ کانہہ انسان خداوند سٕندِس خلاف گناہ کرِ، تێلہِ کُس کرِ تٔمِس سٕندِ خٲطرٕ گُناہ کرنہٕ؟ باوجوٗد تہِ بوز نہٕ تِمو پننِس مٲلہِ سٕنز آواز، تِکیازِ خداوند کرِ تِم مٲرِتھ۔\n26. تہٕ شُر سموئیل بٔڑِتھ تہٕ اوس خداوند سٕندِس تہٕ مردن ہٕندِس طرفس سٍتـ̡ تہِ۔\n27.\\tتہٕ خدایہِ سُند اکھ نفر آو ایلی نِش، تہٕ وونُن تٔمِس یِتھٕ پٲٹھۍ چُھس خداوند فرماوان زِ کیا بہٕ اوسُس پننِس مٲلہِ سٕندِس گرس مَنٛز ظٲہر سپُدمُت، یێلہِ تِم فرعون سٕندِس گرس مَنٛز مصرس مَنٛز ٲسۍ۔\n28.\\tتہٕ کیا مے چُھس سُہ اسرٲیلِہ کیو سارِوٕے قبیلو منزٕ پنُن پادٕرۍ بننہٕ خٲطرٕ ژٲرمُت، یُس میانہِ قربان گاہ پیٹھ پیش کرنہٕ خٲطرٕ، بخور زالنہٕ خٲطرٕ، میانہِ برونہہ کُن ایفود لاگنہٕ خٲطرٕ؟ تہٕ کیا میہ دِژ پننِس مٲلہِ سٕندِس گرس سٍتـ̡ یُس بنی اسرائیل سٕندِ نارٕ سٍتـ̡ دِنہٕ آمُت چھُ؟\n29. تێلہِ کٔرِو میانہِ قربانی تہٕ میانہِ نذرانہ سٍتـ̡ یُس میہ پننِس بستی منز حُکُم دِژمُت چُھ، تہٕ پَنٕنٮ۪ن نیٚچوٮ۪ن ہٕنز عزت کٔرِو میانہِ پیٹھ، یُتھ زن اسرٲیلٕچ سارِوٕے کھۄتہٕ بٔڈۍ نذرانہٕ سٍتـ̡ موٚٹِتھ بَناوُن؟\n30. اَمہِ مۄکھٕ چُھہ اِسرٲیلِیُک خداوند وَنُن زِ یێلہِ چُھہ تُہُند گَرٕ تہٕ تُہٕندِس مٲلہِ سُند گَرٕ پَکُن ہمیشہٕ خٲطرٕ پَکُن، مگر وُنہِ چُھ خداوند وَنان۔ یِم مےٚ عزت دِوان چھِ، تِمن ہٕندِ خٲطرٕ کَرٕ بہٕ احترام، تہٕ یِم مےٚ حقارت کران چھِ، تِمن ہٕندِ خٲطرٕ گژھِ ہلکہٕ پٲٹھۍ احترام کرنہٕ۔\n31.\\tوُچھِو یِم دۅہ یِوان زِ بہٕ ژٔٹِتھ ژٔٹِتھ تہٕ چانہِ مٲلہِ سٕندِس گرٕچ نٔر ژٹِتھ تہٕ تۅہہِ ہٕندِس گَرَس مَنٛز گژھہِ نہٕ کانہہ بُزرگ ۔\n32.\\tتہٕ ژے وُچھِو اکھ دُشمن {میانِس} بستی منز، سارِنٕے {دولت} یُس {خدایہ} اسرٲیلِس دِیہِ، تہٕ تُہندِس گرس منز آسہِ نہٕ ہمیشہٕ خٲطرٕ کانہہ بُزرگ انسان۔ {اکھ دشمن...: یا، خیمہ ہُند عذاب، تتھ سارِنٕے دولتس خٲطرٕ یُس خداین اسرٲیلِس دِژمُت آسہِ}\n33.\\tتہٕ تۅہہِ ہُند انسان، یُس نہٕ بہٕ پننہِ قربان گاہ نِش ژٹِتھ ژٹِتھ، تہٕ تۅہہِ ہٕندِس دِلس غمگسار کرنہٕ خٲطرٕ، تہٕ تۅہہِ ہٕندِس گرُک سورُے اضافہٕ گژھِ تِہٕندِس وٲنسہِ ہٕندِس پوشس منز مرُن۔ {پوشس منز...: ہیب۔ مرد}\n34. تہٕ یہِ آسہِ تۅہہِ خٲطرٕ اکھ نشانہٕ، یُس تہندٮ۪ن دۄن نیچوٮ۪ن ہوفنی تہٕ فینہاسس پیٹھ واتہِ۔ أکِس دۅہس منز گژھن یم دۅشوے مرن۔\n35. تہٕ بہٕ کٔرٕ پانس اکھ وفادار پادٕر، {یُس} مطٲبق کرٕ {یہ} یُس میٲنس دلس تہٕ میٲنس ذہنس منٛز {چُھ} چُھ: تہٕ بہٕ بناوٕ تس اکھ یقینی مکانہٕ۔ تہٕ سُہ پَکُن میانہِ برونہہ کُن ہمیشہٕ خٲطرٕ۔\n36.\\tتہٕ یێلہِ یێلہِ تہٕ یُس تہندِس گَرَس مَنٛز بَچُھ، سُہ گژھہِ تٔمِس نِش رۄپہٕ تہٕ اکھ ٹُکرٕ بٔنِتھ تہٕ وَنُن زِ بہٕ تھاوُن پادٕرٮ۪ن ہٕندِس دفترس مَنٛز، یُتھ بہٕ کھٮ۪تھ اکھ ٹُکرٕ کھٮ۪تھ۔ {پُٹ: ہیب۔ شٲمل گٔژھِو} {منزٕ اکھ...: یا، کُنہِ حدس تام پادٲری متعلق}","1. تہٕ شُر سموئیل کٔر ایلی سٕندِ برونہہ کُن خداوند سٕنز خدمت۔ تہٕ خداوند سُند کلام اوس تمن دۅہن قیمتی ۔ {اتہِ} اوس نہٕ کانہہ یلہٕ نظر۔\n2.\\tتہ سپد تمہِ ساعتہ ییلہ ایلی پننہِ جایہ لوٚگمت تہ امۍ سنزن اچھن ہیوٚت، {یُس نہ} تس وچھان اوس۔\n3. تہٕ خدایہ سٕندِس مندرس مَنٛز خدایہِ سُند چراغ ژھیتہٕ گۆو، یێلہِ خدایہِ سُند صندوق {اوس}، تہٕ سموئیل اوس شوٚنگنہٕ خٲطرٕ ترٛاونہٕ آمُت۔\n4.\\tیُس خداوند سموئیلس بُلوو، تہٕ تٔمۍ دِژ جواب، یێلہِ {am} I.\n5.\\tتہٕ سُہ ژوٚل ایلی کُن، تہٕ وونُن، یێلہِ {am} I. تکیازِ ژے چُھس میہ بُلاونہٕ آمُت۔ تہٕ تٔمۍ ووٚن، میہ اوس نہٕ بلاو۔ بییہِ لوٚگ۔ تہٕ سُہ گوٚو تہٕ لوٚگ۔\n6. تہٕ خداوند دِژ بییہِ اکہِ لٹہِ سموئیل۔ تہٕ سموئیل ووٚتھ تہٕ ووت ایلی نِش، تہٕ وونُن، یێلہِ {am} I؛ تکیازِ ژے کٔر میہ بلاو۔ تہٕ تٔمۍ دیُت جواب، میہ بُلوو نہٕ نیچو۔ بییہِ لوٚگ۔\n7. وُنہِ اوس نہٕ سموئیل وُنیُک تام خداوند سُند کلام زانان تہٕ نہ اوس خداوند سُند کلام وُنیُک تام تس برونہہ کُن ظٲہر سپدمُت۔ {وُن...: یا، یِتھٕ پٲٹھـ̡ سموئیل اوس خداوند سُند کلام زاننہٕ برونہہ، تہٕ خداوند سُند کلام أمِس پیٹھ ظٲہر گژھنہٕ برونہہ}\n8. تہٕ خداوند دِژ سموئیلَس دُبارٕ تریمہِ لٹہِ بُلوو۔ تہٕ سُہ ووٚتھ تہٕ ووت ایلی نِش، تہٕ وونُن، یتہِ {am} I؛ تکیازِ ژے کٔر میہ بلاو۔ تہٕ ایلی ین وُچھ زِ خداوند اوس شُر بُلوومُت۔\n9. تَمہِ کِنۍ ووٚن ایلی سموئیلَس زِ گژھِ، رٔٹِتھ رٔٹِو، تہٕ یێلہِ سُہ بُلناوُن، تہٕ یێلہِ سُہ بُلناوُن، تہٕ یێلہِ سُہ بُلاونہٕ یِیہ، تہٕ وَنُن زِ کتھ کرٕن، خداوند۔ تکیازِ تُہند خادم چُھ بوزان۔ چنانچہ سموئیل گوٚو تہٕ لوٚگ پننہِ جایہ۔\n10.\\tتہٕ خداوند آو تہٕ کھڑا گووُن تہٕ بُلووُن سموئیل، سموئیل۔ امہ پتہ دیت سیموئیلن جواب، کتھ کر۔ تکیازِ تُہند خادم چُھ بوزان۔\n11. تہٕ خداوند ووٚن سموئیلس زِ وُچھ، بہٕ کَرٕ اسرٲیلِس مَنٛز اکھ کٲم یُس بوزان چُھ، یێمہِ سٍتـ̡ پرٮ۪تھ أکِس سٕندِس دۅشوٕے کَن گَژھہِ گَژھان۔\n12. اَمہِ دۅہہٕ کَرٕ بہٕ ایلی سٕندِس خٕلاف تِم سارِنٕے {چیز} انجام دِنہٕ یِم مے تٔمۍ سٕندِس گرس مُتعلِق کتھ کٔرمٕژ چھِ، یێلہِ بہٕ شروع کٔرِتھ تہٕ کٔرٕ بہٕ تہِ ختم۔ {ییلہ...: ہیب۔ آغاز تہٕ اختتام}\n13. کیازِ مے چُھس تس ووٚنمُت زِ بہٕ کرٕ تٔمۍ سٕندِس گرس ہمیشہٕ خٲطرٕ یُس سُہ زانان چُھ، سُہ چُھہ تٔمۍ سٕندِس گرس ہمیشہٕ خٲطرٕ فیصلہ کٔرِتھ۔ تکیازِ تٔمۍ سٕندٮ۪و نیچویو کٔر پان بدکار تہٕ تٔمۍ کٔر نہٕ تِمن رُکاونہٕ۔ {میہ خٲطرٕ...: یا، تہٕ بہٕ وَنُن أمِس} {بدکار: یا، لعنت} {پابندی...: ہیب۔ تِمن کٔر نہٕ ڈٮ۪کہٕ}\n14.\\tتہٕ تێمہِ کِنۍ چُھس میہ ایلی سٕندِس گرس سٍتـ̡ حلف کورمُت زِ ایلی سٕندِس گرس ہٕندِس گُناہ سٍتـ̡ گژھہِ نہٕ قربانی تہٕ نذرانہ سٍتـ̡ ہمیشہٕ خٲطرٕ پاک کرنہٕ۔\n15. تہٕ سموئیل روٗد صُبحَس تام لوٚگ، تہٕ کھولُن خداوند سٕندِ گرٕکۍ دروازٕ۔ تہٕ سیموئیلس اوس ایلی یس وژن ہاونہٕ نِش کھوژان۔\n16.\\tاَمہِ پَتہٕ بُلوو سموئیل، تہٕ وونُن سموئیل، میون نیچو۔ تہٕ تٔمۍ دیُت جواب، یور {am} I.\n17.\\tتہٕ ووٚن، سُہ کیا چُھ {خدا} ژےٚ وَنُن؟ بہٕ چُھس ژے دُعا کران زِ ژے کٔرِو نہٕ میہ نِش ژوٗرِ تھاوُن: خدایہ کٔرِن ژے سٍتـ̡ تہٕ زیادٕ، یێلہِ تہٕ ژے ژے تِمن سارِنٕے چیزن ہٕندِس نِش کُنہِ تہِ کتھ ژوٗرِ تھاوٕنـ̡ ۔ {بییہِ تہِ: ہیب۔ تَمہِ کِنۍ کٔرِو اؠڈ} {چیز: یا، لفظ}\n18.\\tتہٕ سموئیلَن ووٚن أمِس پرٮ۪تھ کُنہِ تہِ، تہٕ کورُن نہٕ أمِس نِش کانہہ تہِ۔ تہٕ تٔمۍ ووٚن، یہِ چُھ خداوند سُہ کرُن یُس أمِس اصل باسان۔ {پرٮ۪تھ کُن...: ہیب۔ سٲری چیز، یا، لفظ}\n19.\\tتہٕ سموئیل بٔڑِتھ تہٕ خداوند اوس أمِس سٍتـ̡ تہٕ دِژُن نہٕ تٔمِس کُنہِ تہِ کَلامَس پٲٹھۍ۔\n20. تہٕ سارِنٕے اسرٲیلِس اوس دان پیٛٹھٕ بیرشبع تام زانان زِ سموئیل اوس خداوند سُند پیغمبر بننہٕ خٲطرٕ قایم کرنہٕ آمُت۔ {قائم: یا، وفادار}\n21.\\tتہٕ خداوند آو شیلوہس منز دُبارٕ ظٲہر، تکیازِ خداوند کٔر خداوند سٕندِ کلامٕ سٍتـ̡ شیلوہس مَنٛز سموئیلس سٍتـ̡ ظٲہر۔","1. تہٕ سموئیل سُند کلام ووت سارنٕے اسرٲیلِس تام۔ وۅنۍ دراو اسرٲیل فلسطینن خلاف جنگہٕ کرنہٕ خٲطرٕ، تہٕ لوٚگ ایبینزرس سٍتۍ، تہٕ فلسطینیو کٔر افیکس منز پیش۔ {آو: یا، آو سپس: ہیب۔ اوس}\n2.\\tتہٕ فلسطینیو کٔر اسرٲیلِس خلاف صفہٕ: تہٕ ییلہ تِمو جنگس منز شٲمل گٔیہ، اسرٲیلِس لٔگۍ فلسطینن برونہہ کنہِ مارنہٕ، تہٕ تِمو مارۍ میدانس منز تقریباً ژور ساس نفر۔ {تِم گٔیہِ شٲمِل...: ہیب۔ جنگ آو پھٔہلاونہٕ} {فوج: ہیب۔ array}\n3. تہٕ ییلہ لُکھ خٲمس مَنٛز وٲتِتھ، اسرٲیلٕکۍ بزرگو ووٚن، کیازِ چُھ خداوند اسہِ دۅہہ فلسطینن برونہہ کُن مارمُت؟ أسۍ أنِو خداوند سٕندِ عہدُک صندوق شیلوہٕ منزٕ اسہِ نِش، یُتھ یێلہِ یہِ اسہِ درمِیان واتہِ، سُہ بچاوِ اسہِ دُشمن ہٕندِ اتھہٕ نِش۔ {فیچ: ہیب۔ اسہِ کُن نِیو}\n4. یێمہِ سٍتـ̡ لوکو سوٗز شیلوہس کُن، یُس تتہِ نِش خداوند لشکرن ہٕندِ عہدُک صندوق أنِتھ، یُس کروبِمن درمِیان روزان چُھ، تہٕ ایلی سٕندِ زٕ نیچوۍ، ہوفنی تہٕ فینہاس، اتہِ ٲسۍ خدایہ سٕندِ عہد کِس صندوق سٍتـ̡ ۔\n5.\\tتہٕ یێلہِ خداوند سٕندِ عہدُک صندوق خٲمس مَنٛز آو تہٕ سارِنٕے اسرٲیلَن کٔر سٮ۪ٹھاہ کرٛٮ۪کہٕ دِنہٕ، یێلہِ دُبارٕ دٔژ زمینہِ ہٕندِس دُبارس مَنٛز۔\n6. تہٕ ییلہ فلسطینیو کرٛٮ۪کہٕ ہُند شور بوز، تِمو ووٚن، عبرانین ہٕندِس خٲمس مَنٛز امہِ بٔڈ کرٛٮ۪کہٕ ہُند شور کیا چُھ؟ تہٕ تِمو گٔیہِ سمجھ زِ خداوند سُند صندوق آو خٲمس مَنٛز۔\n7.\\tتہٕ فلسطینی گٔیہِ خوف، تِکیازِ تِمو ووٚن زِ خدا چُھ خٲمس مَنٛز آمُت۔ تہٕ تِمو ووٚن، افسوس! تکیازِ از تام اوس نہ یُتھ کانہہ چیز۔ {امہ برونہہ کُن: ہیب۔ راتھ یا تریم دۅہ}\n8. اسہِ ہُند افسوس! کُس کرِ اسہِ یمن طاقتور دیوتاہن ہٕندِ اتھہٕ نِش بچاو؟ یم چھہِ تم دیوتا یمو مصرین بیابانن منز تمام آفتن سیتۍ مارۍ متۍ۔\n9. مضبوط بٔنِو، تہٕ پَنُن پان ترٲوِو، اے فلسطینی، یُتھ زن تِم تۅہہِ ہٕندِ خٲطرٕ ٲسِو نہٕ عبرانین ہٕندِ خادم، یِتھٕ پٲٹھۍ تِم تہٕ لڑٲے کٔرِو۔ {تراوُن...: ہیب۔ مرد بٔنِو}\n10. تہٕ فلسطینیو لوٚڑ تہٕ اسرٲیلِس لوٚگ تہٕ تِمو ژٔلِتھ پرٮ۪تھ أکِس خیمہٕ سٕندِس خٲمس مَنٛز۔ تکیازِ اِسرٲیلس سٍتـ̡ گٔیہِ ترہ ساس پیدل سٍتـ̡ ۔\n11. تہٕ خدایہ سُند صندوق آو نِنہٕ۔ تہٕ ایلی سٕنٛدۍ زٕ نیچوۍ، ہوفنی تہٕ فینہاس گٔیہٕ مارنہٕ۔ {آیہ مارنہٕ: ہیب۔ مٔر}\n12.\\tتہٕ ژوٚل بنیامین سُند اکھ شخٕص فوجہٕ منز، تہٕ امی دۅہہ آو شیلوہس کُن پلو پھٔٹِتھ تہٕ کلس پیٹھ میٚژِ ہٮ۪تھ۔\n13. تہٕ ییلہ سُہ آو، ایلی بیوٹھ وتہِ نِش أکِس نشستس پیٹھ وُچھان، تکیازِ تٔمۍ سُند دِل اوس خدایہ سٕندِ صندوق خٲطرٕ تھرتھران۔ تہٕ ییلہ یہِ نفر شہرس منز آو، تہٕ ووٚن {یہ}، سورے شہرن کٔر کرٛٮ۪کھ۔\n14.\\tتہٕ ییلہ ایلی ین وُنُک شور بوز، تٔمۍ ووٚن، امہِ ہنگامہ ہُند کیا مطلب چُھ؟ تہٕ مرد آو جلدی سان اژان تہٕ ووٚنن ایلی ۔\n15. وۅنۍ اوس ایلی نتھ ٲٹھ وُہُر۔ تہ امۍ سنزن اچھن ٲس ژھیپہ، سہ اوس نہ وچھان۔ {اوس ڈِم: ہیب۔ کھڑا}\n16.\\tتہٕ أمِس نفرن ووٚن ایلی یُس لشکرٕ منزٕ نیبر آو، تہٕ بہٕ ژوٚل دۅہہ لشکر منزٕ نیبر۔ تہٕ تٔمۍ ووٚن، تتہِ کیا چُھ گومُت، میانہِ نیچو؟ {is...: Heb. یہ چیز چھُ}\n17. تہٕ رسولن دیُت جواب تہٕ وونُن زِ اسرٲیلِس ژوٚل فلسطینن برونہہ کُن، تہٕ لُکن مَنٛز تہِ آو واریاہ قتل عام کرنہٕ، تہٕ تُہند زٕ نیچوۍ، ہوفنی تہٕ فینہاس تہِ گٔیہِ مٔرۍ، تہٕ خدایہ سُند صندوق آو نِنہٕ۔\n18.\\tتہٕ سپُد ییلہ تٔمۍ خدایہ سٕندِ صندوقُک ذکر کٔر، سُہ پیوٚو دروازٕ کِس اندۍ پکھۍ پٔتمہِ کُن کرسی پیٹھ، تہٕ گردن لٔگِتھ تہٕ سُہ موٗد، تکیازِ سُہ اوس اکھ بُزرگ تہٕ گوٚب۔ تہٕ تٔمۍ اوس اسرٲیلُک فیصلہ ژتٲجی ؤری کوٚرمت۔\n19. تہٕ تٔمۍ سٕنزِ نوٗر ، فینہاس سٕنز زنانہٕ ٲس بچہٕ سٍتۍ، یُس زیٚنہٕ خٲطرٕ اوس، تہٕ ییلہ أمس یہ خبر بوز زِ خدایہ سُند صندوق آو نِنہٕ، تہٕ تٔمۍ سُند مول تہٕ تٔمۍ سُند خانٛدار چُھ موٗدمُت، تٔمۍ کٔر نمُن تہٕ تٔمۍ سُند خانٛدار چُھہ مُرد۔ تکیازِ تٔمۍ سٕندِ دَگ آو أمِس پیٹھ۔ {دِنہٕ یِن: یا، کرٛٮ۪و} {آو: ہیب۔ آو بدلاونہٕ}\n20. تہٕ تٔمۍ سٕندِ مرنہٕ وِزِ أمِس سٍتـ̡ کھڑا زنانہٕ ووٚن أمِس خوفہٕ نہٕ۔ تکیازِ ژے چھہ اکھ نیچو زامُت۔ مگر تٔمۍ دیت نہ جواب، نہ اوس تٔمۍ سُند خیال تہِ۔ {نہ تہِ...: ہیب۔ تٔمۍ سُند دِل کٔرِو نہٕ سیٹ کٔرِتھ}\n21.\\tتہٕ تٔمۍ تھوو شُرِس اِخابود ناو، یہِ وَنُن زِ جلال چُھ اِسرٲیلِس نِش نیران، تِکیازِ خدایہِ سُند صندوق آو نِنہٕ، تہٕ تٔمۍ سٕندِس مٲلس تہٕ تٔمۍ سٕندِس خانٛدارس سٍتـ̡ ۔ {ایچابوڈ: یعنی، عظمت کتہِ چُھ؟ یا، کانہہ شان چھُنہ}\n22. تہٕ ووٚن تٔمۍ ووٚن، جلال چُھ اسرٲیلِس نِش نیران، تکیازِ خدایہِ سُند صندوق چُھ نِنہٕ آمُت۔","1. تہٕ فلسطینیو نیو خدایہ سُند صندوق تہٕ اَنِن ایبینزر سٕندِ طرفہٕ اشدودس تام۔\n2.\\tییلہ فلسطینیو خدایہ سُند صندوق نِیو، تِمو أنِو سُہ ڈاگون سٕندِس گرس مَنٛز، تہٕ دگون سٕندِ دٔسۍ تھووُن۔\n3.\\tتہٕ ییلہ تم پگہہ سُلہِ وۅتھ، وچھ دگون پۯاوُن خداوند سٕندِس صندوقس برونہہ کُن زمینس پیٹھ پیوٚو۔ تہٕ تِمو نیو ڈاگون تہٕ تھووُن بییہ پننہِ جایہ۔\n4.\\tتہٕ ییلہ تِم پگہِ صُبحٲے سُلہٕ وُتھ، وُچھ دَگون پۯاوُن خداوند سٕندِس صندوقس برونہہ کُن بُتھِس پٲٹھۍ۔ تہٕ ڈاگون سُند کلہٕ تہٕ تٔمۍ سٕندِ دۅشوے اتھہٕ آیہ دروازس پیٹھ ژٹنہٕ۔ صرف اوس تٔمِس خٲطرٕ {سٹمپ} ڈاگون تراونہٕ آمُت۔ {سٹمپ...: یا، گاڈٕ دار حصہ}\n5.\\tتێلہِ چُھہ نہ ڈاگون سٕندِس گرس منز یِنہٕ وٲلِس پادٕرۍ تہٕ یُس دگون سٕندِس گرس منز یِوان چُھ، چُھہ از تام اَشدودس مَنٛز ڈاگون سٕندِس دروازس پیٹھ پکان ۔\n6. مگر خداوند سُند اَتھٕ اوس تِمن پیٹھ اَشدود سٕندِس پٲٹھۍ، تہٕ تٔمۍ کٔرٕن تِم تباہ تہٕ اَشدود تہٕ تِمن ہٕندِس ساحلس سٍتـ̡ مارٕ۔\n7. تہٕ ییلہ اشدود کیو لوکو وُچھ زِ یہِ چُھہ یُتھ، تِمو ووٚن زِ اسرٲیلِکۍ خدایہِ سٕنز صندوق روزِ نہٕ اسہِ سٍتـ̡ روزُن، تکیازِ تٔمۍ سُند اَتھٕ چُھہ اسہِ سٍتـ̡ تہٕ سٲنِس خداہس سٍتـ̡ دَگ۔\n8.\\tتِمو سوٗزۍ تہٕ سٍتـ̡ کٔرِکھ فلسطینی سٕندِ سارِنٕے آقا تِمن نِش جمع تہٕ وونُن، أسـ̡ کیا کرو اسرٲیلِہ کِس خدایہِ سٕندِس صندوقس سٍتـ̡ ۔ تہٕ تِمو دِژ جواب، اسرٲیلِک خدایہِ سُند صندوق گژھہِ گاتھس تام نِنہٕ۔ تہٕ تِمو تُل اسرٲیلِک خدایہِ سُند صندوق {تتہِ}۔\n9. تہٕ یہٕ اوس {یِتھ} زِ، یێلہِ تِمو یہِ نِنہٕ پتہٕ، خداوند سُند اَتھٕ اوس شہرس خلاف سٮ۪ٹھاہ بٔڈ تباہی سٍتـ̡ تہٕ تٔمۍ دِژ شہرٕکین لوکٕٹٮ۪ن تہٕ بٔڑن نفرن ہٕندِس لۅکٹِس تہٕ بٔڈِس سٍتـ̡ تہٕ تِمن ہٕندِس خفیہ حصس مَنٛز لٔگـ̡ ۔\n10.\\tلہذا سوز تمو خدایہ سُند صندوق ایکرونس کُن۔ تہٕ یہِ سپُد یُتھ خدایہِ سُند صندوق ایکرونس نِش آو، زِ ایکرونِیو دِژ کرٛٮ۪کھ دِتھ زِ تِمو چُھ اسہِ تہٕ سانہِ لوکن مارنہٕ خٲطرٕ اسہِ خٲطرٕ اسرٲیلِک خدایہِ سُند صندوق اوٚنمُت۔ {اسہِ، تو...: ہیب۔ مے مارُن مے تہٕ میانِ}\n11.\\tیێمہِ سٍتـ̡ سوٗزِتھ تِمو سٍتـ̡ فلسطینی ہٕندِس سارِنٕے آقا سٍتـ̡ جمع تہٕ وونُن، اسرٲیلِکِس خدایہِ سُند صندوق، تہٕ دُبارٕ تراوُن پننِس جایہ، یُتھ نہٕ اسہِ تہٕ سانہِ لُکھ مارنہٕ یِن، تکیازِ سٲرۍسٕے شہرس منز گٔیہِ مہلک تباہی۔ اَتہِ اوس خدایہ سُند اَتھٕ سٮ۪ٹھاہ گۄب۔ {أس نہٕ...: ہیب۔ مے نہٕ، تہٕ میانِ}\n12.\\tتہٕ یِم مرد نہٕ مٔرۍ، تِم گٔیہِ ایمروڈس سٍتـ̡ مارنہٕ: تہٕ شہرٕچ فریاد ووت جنتس تام۔","1. تہٕ خداوند سُند صندوق اوس فلسطینن ہٕندِس ملکس مَنٛز سَتھ ریتھ۔\n2. تہٕ فلسطینیو بُلوو پادٕرین تہٕ دیواہن بُلٲوِتھ وونُن، أسۍ کیا کرو خداوند سٕندِس صندوقس سٍتـ̡؟ اسہِ وَن زِ أسۍ کَمہِ سٍتۍ سوزو یہِ أمۍ سٕنزِ جایہ۔\n3. تہٕ تِمو ووٚن، یێلہِ تُہۍ اسرٲیلِکِس خدایہِ سُند صندوق تراوُن، سُہ سوزُن نہٕ خٲلی۔ مگر کُنہِ تہِ پٲٹھـ̡ کٔرِو أمِس اکھ ناپاک نذرانہ واپس: تیلہِ گژھہِ تۅہہ شفا تہٕ ژیہ گژھہِ معلوم زِ تٔمۍ سُند اتھہ کیازِ آو نہٕ ژے نِش ہٹاونہٕ۔\n4.\\tتِمو ووٚن زِ سُہ کیا گُزٲر نذرانہ یُس أسۍ أمِس نِش واپس۔ تِمو دِژ جواب، پانژھ سۄنہٕ ایمروڈ، تہٕ پانژھ سۄنہٕ گگر، {مطٲبق} فلسطینین ہٕندٮ۪ن مالکن ہُند تعداد: اَکہِ وُعُن {اوس} تُہۍ سارِنٕے تہٕ تُہنٛدین آقاوَن پیٹھ۔ {توہ: ہیب۔ تِم}\n5. اَمہِ مۄکھٕ بناوِو تُہۍ پَنٕنٮ۪ن گگرن ہٕنز شکلہٕ تہٕ زمینس سٍتـ̡ بَناوٕنـ̡ ۔ تہٕ تُہۍ کٔرِو اسرٲیلِکِس خدایہِ سٕندِس جلال سٍتـ̡ یێلہِ سُہ تہٕ تُہٕندِس خداہٕ نِش تہٕ تُہٕندِس زمینہٕ نِش ہلکہٕ کٔرِتھ۔\n6. تیلہِ کیازِ چھِو پَنُن دِل سخٕت کٔرِتھ، یِتھٕ پٲٹھۍ مصری تہٕ فرعونن پنُن دِل سختی کٔرۍ؟ ییلہ تٔمۍ تمن منز حیرت انگیز کٲم کٔر، کیا تِمو دِژ نہٕ لُکن تہٕ تِم گٔیہِ؟ {حیرت انگیز: یا، ملامت سان} {لوک: ہیب۔ تِم}\n7.\\tتَمہِ کِنۍ بَنوو اکھ نٔو گاڑۍ، تہٕ نِیُن زٕ دۄدٕ گاڈ، یَتھ پیٹھ نہٕ کانہہ جوُر آسہِ، تہٕ گاڈِ گٔنڈِتھ تہٕ تِمن نِش أنِو تِمن ہٕندِس بَچھرٕ گَرٕ سٍتۍ۔\n8.\\tتہٕ رٔٹِو خداوند سُند صندوق، تہٕ تھووُن گاڑِس پیٹھ۔ تہٕ سۄنہٕ سٕندِ جوٲہِر، یُس تُہۍ أمِس واپس دِوان چھِو، اَمہ سٍتـ̡ أکِس صندوقس منز۔ تہٕ سوزُن یہِ نیرُن۔\n9.\\tتہٕ وُچھو، اگر یہِ پننہِ بٹھہِ کِنۍ بیت شیمش کُن گژھِ، {تیلہِ} چھُ تٔمۍ اسہِ یہِ بٔڈ بُرکاری کٔرمٕژ، مگر اگر نہٕ تیلہِ گژھہِ اسہِ معلوم زِ {یہ} چھُنہٕ تٔمۍ سُند اَتھٕ {یُس} اسہِ سٍتـ̡ مارُن: یہِ {اوس} اکھ موقعہٕ {یُس} اسہِ سٍتـ̡ سپدیومُت۔ {وہ: یا، یہ}\n10. تہٕ مردو کٔر یہ۔ تہٕ تُلُن زٕ دۄدٕ گٲنۍ، تہٕ گَرِ بنٛد کٔرِتھ:\n11.\\tتہٕ تِمو ترٛوو گاڈِس پیٹھ خداوند سُند صندوق، تہٕ خزانہٕ یتھ سٍتـ̡ سۄنہٕ سٕندِ گگر تہٕ تِمن ہٕندِس ایمروڈس ہٕنزِ شکلہٕ ٲس۔\n12.\\tتہٕ گٔیہِ سیوٚد وتہِ بیت شمیش کِس وتہِ کُن، {تہٕ} گٔیہِ شاہراہس کُن، تہٕ گٔیہِ نہٕ دٔچھنِس اتھس کُن یا کھوورِ طرفہٕ پھیرُن۔ تہٕ فلسطینن ہٕندِ مٲلک گٔیہِ تِمن پتہٕ بیت شمش کِس سرحدس تام۔\n13.\\tتہٕ تِمو ٲس وادی منز کٕنکہٕ ہُند فصل لُٹان۔ تہٕ تِمو کٔر أچھ تُلِتھ تہٕ وُچھِتھ گٔیہِ صندوق، تہٕ گٔیہِ یہِ وُچھِتھ خۅش۔\n14.\\tتہٕ گاڑِ آو یشوع سٕندِس کھاہس مَنٛز، یُس اکھ بیت شمایی اوس، تہٕ تتہِ کھڑا یَتھ اکھ بوٚڈ کٔنہِ اوس، تہٕ تِمو کٔرٕکھ گاڑِ ہٕنزِ لٔکرِ ژٔٹِتھ تہٕ کٔرٕن گاڈِ ہٕندِس کھاہس منز زٲلِتھ نذرانہ پیش کرنہٕ۔\n15.\\tتہٕ لاویو نِش خداوند سُند صندوق تہٕ سُہ صندوق یُس اتھ سٍتـ̡ اوس، یتھ مَنٛز سۄنہٕ سٕندِ جوٲہرات ٲس، تہٕ تھووُکھ بٔڈِس کنس پیٹھ، تہٕ بیت شمیش کٮ۪و لوکو کٔر امی دۅہہ خداوند سٕندِ خٲطرٕ زالنہٕ نذرانہ تہٕ قربانی دِنہٕ۔\n16. تہٕ ییلہ فلسطینن ہٕندیو پانژو مالکن وُچھ، تِم گٔیہِ امی دۅہہ اکرون واپس۔\n17.\\tتہٕ یِم سۅنہٕ سٍتـ̡ یُس فلسطینیو واپس دِیُت {یێلہِ سٍتـ̡ خداوند سٍتـ̡ دِنہٕ آمُت چھُ۔ اَشدود خٲطرٕ، غزہ خٲطرٕ، اَکہِ خٲطرٕ، اَسکیلون خٲطرٕ، گاتھ خٲطرٕ، ایکرون خٲطرٕ؛\n18. تہٕ سۄنہٕ گگر {مُطٲبق} فلسطینن ہٕندِس سارِنٕے شہرن ہُند تعداد یُس پانژن مٲلکَن سٍتـ̡ چُھہ، {دونوے} تارٕ دار شہرن تہٕ دیہٲتی گامن ہُند تعداد، حتیٰ کہ عظیم {کٔن} ہابیل سٕندِس پتھرس تام، یتھ پیٹھ تِمو خداوند سُند صندوق ترٲومُت: {کُس کُن چُھ} از تام یشوع سٕندِس میدانس مَنٛز باقی،  بیت شیمائٹ۔ {عظیم...: یا، عظیم پتھر}\n19.\\tتہٕ تٔمۍ دِژ بیت شیمش کین نفرن مار، تکیازِ تِمو اوس خداوند سٕندِس صندوقس مَنٛز نظر دِژمٕژ، حتیٰ کہ تٔمۍ دِژ لُکن ہٕندِس پنٛژاہ ساس تہٕ داہ نفرن ہُند مار۔\n20.\\tتہٕ بیت شیمش کِس مردو ووٚن، کُس چُھ اتھ مقدس خداوند خداہس برونہہ کُن کھڑا گژھنس لایق؟ تہٕ سُہ کُس گژھہِ اسہِ نِش؟\n21. تہٕ تِمو سوٗزۍ کِرجاتجیرِم کین بسکینن نِش پیغمبر تہٕ وونُن زِ فلسطینیو چُھ خداوند سُند صندوق دُبارٕ أنِمُت۔ تم آو بۄن، {تہٕ} یہ پانس تام أنتھ۔","1. تہٕ کِرجاتھجیرِمٕکۍ نفر آیہ، تہٕ اَنُن خداوند سُند صندوق، تہٕ أنِکھ بالہٕ کِس ابینڈاب سٕندِس گَرَس مَنٛز، تہٕ کوٚرُن خداوند سُند صندوق رژھراونہٕ خٲطرٕ پننِس نیچوِس الیعزرس پاک۔\n2. تہٕ یہ سپُد ییلہ صندوق کِرجاتجیریمس منز روزان اوس، زِ وقت اوس زیٹھ۔ تکیازِ یہ اوس وُہ ؤری: تہٕ سارِوٕے اسرٲیلِک گرٕ اوس خداوند سٕندِ پٲٹھـ̡ ماتم کٔرِتھ۔\n3. تہٕ سموئیلَن ووٚن سارِنٕے اِسرٲیلِس سٍتـ̡ وَنُن زِ یێلہِ پَنٕنـ̡ سارِوٕے دِلہٕ سٍتـ̡ خداوند سٕندِس نِش واپس یِو، تہٕ پَنٕنـ̡ دِل کٔرِو خداوند سٕندِ خٲطرٕ تیار، تہٕ کٔرِو تٔمِس سٍتـ̡ خدمت۔\n4. پَتہٕ کٔر بنی اِسرٲیلِیو بعلِم تہٕ اشتروتھ تہٕ کٔرٕکھ صرف خداوند سٕنز خدمت۔\n5. تہٕ سموئیلَن ووٚن زِ سارِنٕے اسرٲیلِس کٔرِو مزپہس مَنٛز جمع تہٕ بہٕ کَرٕ تۅہہِ ہٕندِ خٲطرٕ خداوند سٕندِ خٲطرٕ دُعا۔\n6. تہٕ تِمو گٔے اَکہٕ وَٹہٕ مِزپہٕ کُن، آب لٔگِتھ تہٕ ترووُکھ خداوند سٕندِس برونہہ کُن، تہٕ اَمہ دۅہہٕ کورُکھ روزہٕ تہٕ وونُن زِ أسـ̡ چُھ خداوند سٕندِس خلاف گۅناہ کورمُت۔ تہٕ سموئیل کٔر مِزپہِ مَنٛز بنی اِسرٲیلِس سٍتـ̡ فیصلہ کرنہٕ۔\n7. تہٕ ییلہ فلسطینیو بوز زِ بنی اسرائیل آیہ مزپہ کُن جمع کرنہٕ، فلسطینن ہٕندِ آقا گٔیہِ اسرٲیلِس خٕلاف۔ تہٕ ییلہ بنی اسرائیلیو بوٗز، تِم گٔیہِ فلسطینن نِش کھوژان۔\n8. تہٕ بنی اسرٲیلِو ووٚن سموئیلس زِ اسہِ خٲطرٕ گژھ نہٕ خداوند سٕندِس خداہس نِش فریاد دِنہٕ، یُس سُہ کرِ اسہِ فلسطینن ہٕندِ اتھہٕ نِش بچاو۔ {بند کرو...: ہیب۔ اسہِ نِش گژھ نہ روُن نِش ژھۄپہٕ}\n9.\\tتہٕ سموئیلَن رٔٹ اَکھ کۅکرِ کۅکر، تہٕ دیتُن خداوند سٕندِ خٲطرٕ پوٗرٕ پٲٹھـ̡ زٲلِتھ نذرانہ پیش کرنہٕ۔ تہٕ سموئیلَن کٔر اسرٲیلِس خٲطرٕ خداوند سٕندِ خٲطرٕ فریاد ۔ تہٕ خداوند کٔر سُہ بوز۔ {بوزمُت: یا، جواب}\n10. تہٕ یێلہِ سموئیل دزنہٕ نذرانہ پیش کران اوس، فلسطینی وٲتۍ اسرٲیلِس خٕلاف جنگہٕ خٲطرٕ، مگر خداوند دِژ تمہِ دۅہہ فلسطینن پیٹھ زبردست گرٛاے تہٕ تِم دِژ پریشان۔ تہٕ تِم گٔے اسرٲیلِس برونہہ کُن مارنہٕ۔\n11.\\tتہٕ اِسرٲیلٕکۍ مرد دراو مِزپہٕ منزٕ تہٕ لٔگِکھ فلسطینن ہُند پیچھا تہٕ لٔگِکھ تِمن مارٕ، یوتام تِم بیتھکارس تل وٲتۍ۔\n12.\\tتمہِ پتہ روٚٹ سموئیل اکھ کٔن، تہٕ تھووُن مزپہ تہٕ شینس درمِیان تہٕ وونُن اَمہ کُن ناو ایبینزر تہٕ وونُن زِ خداوند چُھ اسہِ مدد کٔرمٕژ۔ {Ebenezer: یعنی مددک پتھر}\n13. یێمہِ پٲٹھـ̡ گٔیہِ فلسطینی زیر تہٕ تِم وٲتِتھ نہٕ اِسرٲیلِس کِس بٹھِس مَنٛز، تہٕ خداوند سُند اَتھٕ اوس سموئیل سٕندِس سارِنٕے دۅہہٕ فلسطینن خلاف ۔\n14. تہٕ یِم شہر فلسطینیو اسرٲیلِس نِش نِش نِمٕتۍ ٲسۍ، تِم آیہ اِسرٲیلس واپس کرنہٕ، حتیٰ کہ عکرون پیٹھٕ گاتھس تام۔ تہٕ اَمہِ کِس ساحلس سٍتـ̡ دِژ اسرٲیلـ̡ فلسطینن ہٕندِس اتھہٕ نِش نجات دِنہٕ۔ تہٕ اسرائیلس تہٕ امورین درمیان اوس امن۔\n15. تہٕ سموئیل کٔر پننہِ زندگی ہٕندِس سارِنٕے دۅہن اسرٲیلُک فیصلہٕ۔\n16.\\tتہٕ سُہ اوس ؤری پتہٕ ؤری بِتھل، گلگل تہٕ مزپہ کُن گٔژھان تہٕ یِمن سارِنٕے جاین کٔرِن اسرٲیلُک فیصلہٕ۔ {سرکٹس منز: ہیب۔ تہٕ تٔمۍ کٔر سرکٹ}\n17.\\tتہٕ تٔمۍ سُند واپس۔ تکیازِ تٔمۍ سُند مکانہ اوس {اوس}۔ تہٕ تتہِ کوٚر تٔمۍ اسرٲیلُک فیصلہٕ۔ تہٕ تتہِ بنوو تٔمۍ خداوند سٕندِ خٲطرٕ اکھ قربان گاہ۔","1. تہٕ سپُد ییلہ سموئیل بُزرگ اوس، تمٔۍ بنوو پننین نیچوین اسرٲیلِس پیٹھ قاضی۔\n2. وۅنۍ اوس تٔمۍ سٕندِس گۄڈنِکِس بچہٕ سُند ناو جوئل۔ تہٕ تٔمۍ سٕندِس دویِم سُند ناو: {تِم ٲسۍ بیرشیباہس منز جج۔\n3.\\tتہٕ تٔمۍ سٕندِس نیچوۍ گٔیہِ نہٕ تٔمۍ سٕنزِ وتہِ پٲٹھۍ، بلکہ پھٔرِکھ رُشوَت تہٕ رُشوَت تہٕ غلط فیصلہٕ۔\n4. اَمہِ پَتہٕ گٔیہِ اِسرٲیلٕکۍ سارِوٕے بُزرگ جمع تہٕ آیہِ سموئیلس نِش راماہس نِش،\n5. تہٕ ووٚنُن أمِس، وُچھ، تہٕ تُہۍ چھِو بُزرگ تہٕ تُہٕندِس نیچوِس چھِنہٕ تُہنزِ وتہِ پٲٹھۍ، وۅنۍ بناو اسہِ اکھ بادشاہ یُس سارِنٕے قومن ہٕندۍ پٲٹھۍ، اسہِ ہُند فیصلہ کرُن۔\n6.\\tمگر سموئیل سٕندِس معاملس سٍتـ̡ ناراض ییلہ تمو ووٚن، اسہِ دِیو اکھ بادشاہ یُس اسہِ سٍتـ̡ فیصلہ کرُن۔ تہٕ سموئیلن کٔر خداوند سٕنز دُعا۔ {ناراض: ہیب۔ اَمہ کِس نظرس منز اوس بُرٕ\n7. تہٕ خداوند چُھ سموئیلس ووٚنمُت، تہٕ تِمن ہٕندِس سارِنٕے سٍتـ̡ تہٕ یِمن ہٕندِس سٍتـ̡ تہٕ تِمن ہٕندِس سٍتـ̡ بوزُن: کیازِ تِمو چُھہ نہٕ تۅہہِ نکار کٔرمٕژ، مگر تِمو چُھہ نہٕ تِمن پیٹھ بادشاہی کٔرمٕژ۔\n8. یِمو سارِنٕے کامہِ مُطٲبِق یِمو تِمو تِمن دۅہہٕ پیٹھٕ یِم مصرہٕ منزٕ نیبر کٔرۍمٕتۍ، یێمہِ سٍتـ̡ تِمو چُھہ میہ ترٲومُت تہٕ باقین دیوتاہن ہٕنز خدمت کٔرمٕژ، تِتھے پٲٹھۍ چھِ تِم تہِ تۅہہِ سٍتـ̡ کران۔\n9.\\tتێلہِ کٔرِو تِہٕنزِ آواز بوزُن: توتہِ کٔرِو تِمن سٍتـ̡ سنجیدگی سان احتجاج تہٕ تِمن ہُند بادشاہ سُند طریقہٕ ہٲوِو یُس تِمن پیٹھ راج کرِ۔ {بوزو...: یا، اطاعت کرو} {بہرحال...: یا، ییلہ تہِ تۅہہ تمن خلاف سنجیدگی سان احتجاج کورمُت آسہِ، تیلہِ گژھہِ تۅہہ کرُن}\n10.\\tتہٕ سموئیلَن ووٚن خداوند سٕندِ سارِنٕے کلامَن تِمن لُکن یِمو أمِس بادشاہس منگان۔\n11. تہٕ تٔمۍ ووٚن، بادشاہ سُند طریقہٕ آسہِ یُس تۅہہِ پیٹھ راج کرِ: سُہ نِیہِ تُہند نیچو، تہٕ پانس خٲطرٕ، پننین رتھن خٲطرٕ تہٕ گُرۍ سوارِ خٲطرٕ مقرر کرِ۔ تہٕ {کیٚنٛہہ} گژھن تٔمۍ سٕندٮ۪ن رتھن برونہہ کُن۔\n12. تہٕ سُہ کرِ أمِس ساسہٕ بٔدۍ کھۄتہٕ زیادٕ کپتان تہٕ پنژاہ ؤری کھۄتہٕ زیادٕ کپتان مقرر کرنہٕ۔ تہٕ {کرِ تِم مقرر کرنہٕ} تٔمۍ سٕنزِ زمینہٕ کٔرِتھ، تہٕ تٔمۍ سٕندِ فصلہٕ لُٹنہٕ خٲطرٕ، تہٕ پنٕنۍ جنگٕکۍ آلات، تہٕ پننین رتھن ہٕندۍ آلہ بَناوٕنۍ۔\n13.\\tتہٕ سُہ نِیہِ تُہنزِ کورِ مِٹھٲے تہٕ بَننہٕ خٲطرٕ، تہٕ بَننہٕ خٲطرٕ۔\n14. تہٕ سُہ نِیہِ تُہٕندِس کھہَس تہٕ تُہٕندِس باغس تہٕ تُہٕندِس زیتوُن تہٕ تِمن ہٕندِس خدمتگارن دِیہِ۔\n15.\\tتہٕ سُہ نِیہِ تُہٕندِس بُلِس تہٕ تُہٕندِس باغن ہُند دٔہِم حِصہٕ، تہٕ دِیہِ پننین افسرن تہٕ پننین خدمتگارن دِنہٕ۔ {افسر: ہیب۔ خواجہ سرا }\n16.\\tتہٕ سُہ نِیہِ تُہٕندِس خادمَن، تہٕ تُہٕندِس نیک جوان تہٕ تُہٕندِس گَرٕ سٍتـ̡ تہٕ تِمن نِش کرِ پننہِ کامہِ پیٹھ۔\n17.\\tسُہ نِیہِ تُہٕندِس دٔہِمِس کُن تہٕ تُہۍ بٔنِو تٔمۍ سٕندِس خادم۔\n18. تہٕ تُہۍ کٔرِو اَمہِ دۅہہٕ پَنٕنِس بادشاہس سٍتـ̡ یُس ژے ژٲرِمُت چُھ، تہٕ خداوند کرِ نہٕ تۅہہ تمہِ دۅہہٕ بوزنہٕ۔\n19. بہر حال لوکو کٔر سموئیل سٕنزِ آوازِ ماننہٕ نِش انکار۔ تہٕ تِمو ووٚن، نہ۔ مگر اسہِ آسہِ اسہِ پیٹھ اکھ بادشاہ۔\n20. تاکہ أسۍ تہِ گژھن سارِنٕے قومن ہٕندۍ پٲٹھۍ۔ تہٕ یُتھ زِ سٲنۍ بادشاہ کرِ اسہِ فٲصلہٕ، تہٕ اسہِ برونہہ کُن نیرِ، تہٕ سٲنۍ جنگ لڑِ۔\n21. تہٕ سموئیلَن بوز لُکن ہٕندِ سارِنٕے کلام، تہٕ تِم کٔرٕن خداوند سٕندِس کنن مَنٛز پرناونہٕ۔\n22. تہٕ خداوند ووٚن سموئیلس زِ تِہٕنزِ آواز بوزُن تہٕ بنوو تِمن بادشاہ۔ تہٕ سموئیلَن ووٚن اسرٲیلِکِس انسانس زِ پرٮ۪تھ کانہہ انسان گژھ پننِس شہرس کُن۔","1. وۅنۍ اوس بنیامین سُند اکھ شخٕص، یُس ابییل سُند نیچو اوس، زیرور سُند نیچو، بیکورتھ سُند نیچو، افیاہ سُند نیچو، یُس بنیجمیہ سُند نیچو اوس، یُس اکھ طاقتور انسان اوس۔ {a Benjamite: یا، Jemini کِس انسان سُند نیچو} {پاور: یا، مادہ}\n2. تہٕ أمِس اوس اَکھ نیٚچُو، یٔمِس ناو اوس ساؤل، یُس اکھ ژٲر جوان تہٕ نیک اوس، تہٕ اِسرٲیلِس منز اوس نہٕ أمِس کھۅتہٕ زیادٕ نیک شخص۔\n3.\\tتہٕ کیش ساؤل سٕندِس مٲلہِ سٕندِ گَرٕ گٔیہِ ضایع۔ تہٕ کیشَن ووٚن پننِس نیچوِس ساؤلَس زِ وۄنۍ نِو پانس سٍتۍ اکھ نوکر، تہٕ ووٚتھ، گژھ گَرٕ ژھانڈنہٕ۔\n4.\\tتہٕ سُہ ووت کوہ افرائیم کِنۍ تہٕ شالِشہ کِس سرزمینس مٔنزۍ گٔیہ، مگر تِمو لٔبِتھ نہٕ: تمہ پتہ گٔے تِم شلیم کِس سرزمینہٕ کِنۍ، تہٕ تِم ٲسۍ نہٕ تِمن ہٕندِس سرزمینس مٔنزۍ گٔژھمٕتۍ، مگر تِمو لٔب نہٕ۔\n5.\\tییلہ تِم زُف کِس سرزمینس منز وٲتۍ، ساؤلن ووٚن پننِس خادمس زِ {اوس} أمِس سٍتۍ، یِو تہٕ أسۍ واپس۔ میہ ما تراوِ میون مول گۅرِ ہُند خیال تہٕ اسہِ ہٕندِ خٲطرٕ سوچ۔\n6. تہٕ تٔمۍ ووٚن أمِس زِ وُچھِو وُن، یَتھ شہرس مَنٛز چُھ خدایہِ سُند اکھ انسان تہٕ سُہ چُھ اکھ معزز انسان۔ سُہ سورُے یُس ونان چُھ، سُہ چُھ یقینا سپدُن: وۅنۍ گژھو أسۍ تتہِ۔ شاید سُہ ہیکہِ اسہِ وتھ ہٲوِتھ زِ اسہِ گژھہِ گژھُن۔\n7.\\tاَمہِ پتہٕ ووٚن ساؤلَن پننِس خادمَس مَگَر، مَگ، یێلہِ أسۍ نیرِو، أسۍ کیا اَنِو یہِ مرد؟ تکیازِ روٹی چھیہ سانین بانن منز خرچ سپدان، تہٕ خدایہ سٕندِس انسانس نِش اننہٕ خٲطرٕ چُھہ نہٕ کانہہ تحفہٕ: اسہِ کیا چُھہ؟ {چُھ خرچ کرنہٕ آمُت...: ہیب۔ گٔمٕژ گٔمٕژ، وغیرہ} {کیا أسۍ: Heb. کیا اسہِ سۭتۍ؟}\n8.\\tتہٕ خادمَن دِژ ساؤلس دُبارٕ جواب تہٕ وونُن، وُچھ، میہ نِش چُھس رۄپہٕ ہُند ژوٗرِم حصہٕ اتھس منز: {یہ} بہٕ دِیہٕ خدایہ سٕندِس انسانس دِنہٕ، یُس اسہِ وَتھ وَننہٕ خٲطرٕ۔ {میہ چُھ...: ہیب۔ میٲنس اتھس منز چُھ لبنہٕ آمُت}\n9. (اِسرٲیلِس مَنٛز ییلہ اَکھ شخٕص خدایہِ سٍتـ̡ پرژھہٕ گٲر کرنہٕ آمُت اوس، یِتھٕ پٲٹھـ̡ وۆن، یێلہِ أسـ̡ پى۪ٹھہٕ پى۪ٹھـ̡ پى۪ٹھـ̡ پى۪ٹھہٕ پى۪ٹھـ̡ پى۪\n10.\\tاَمہِ پتہٕ ووٚن ساؤلَن پننِس خادمَس سٍتـ̡ رُکُن؛ آؤ، گژھو اسہِ۔ چنانچہ گٔے تِم تتھ شہرس کُن ییتہِ خدایہ سُند انسان اوس۔ {اَکھ وَنُن: حَب۔ تُہند کلام چُھ اصل}\n11.\\tییلہ تِم بالہٕ کھٔسِتھ شہرس کُن گٔیہِ، تِمو وُچھ جوان کورِ آب اننہٕ خٲطرٕ نیبر نیران، تہٕ تِمن وونُن، کیا وُچھن وول چھا یتہِ؟ {پہاڑ...: ہیب۔ شہر کس عروجس منٛز}\n12.\\tتہٕ تِمو دِژ تِمن جواب تہٕ وونُن، سُہ چُھ۔ وُچھِو، {سُہ چُھ} تۅہہِ برونہہ کُن: جلدی کٔرِو، تکیازِ سُہ آو دۅہہ شہرس منز۔ تکیازِ {اتہِ} چُھ از کل تھدِ مقامس پیٹھ لوکن ہنز قربانی سپدان: {قربانی: یا، دعوت}\n13. یێلہِ یێلہِ تُہۍ شہرس مَنٛز وٲتِو، سُہ کھٮ۪نہٕ خٲطرٕ تھدِ جایہِ کھسنہٕ برٛونٛہہ، تِکیازِ سُہ چُھ نہٕ توٚت تام کھٮ۪وان تِکیازِ سُہ چُھ قربانی دِوان۔ {تہٕ} پتہٕ چھِ تِم کھٮ۪وان یُس دِنہٕ یِوان چھُ۔ وۅنۍ وۅنۍ وۅتھان وۅتھ؛ تکیازِ اتھۍ وقتس منز لٔبِتھ ژیہ سُہ لٔبتھ۔ {یمہٕ لٹہٕ: ہیب۔ از تام}\n14.\\tتہٕ تِم گٔیہِ شہرس مَنٛز، یێلہِ تِم شہرس مَنٛز وٲتِتھ، وُچھ سموئیل دراو تِمن خٕلاف، تِمن ہٕندِس تھدِس مقامس تام واتنہٕ مۅکھہٕ۔\n15. وُنہِ اوس خداوند ساؤل سٕندِ یِنہٕ برونہہ أکِس دۅہہٕ سموئیلس پننِس کنس منز ووٚنمُت، وونُن، {وونُن...: ہیب۔ سیموئیل سٕندِ کَن کٔر ظٲہِر}\n16.\\tپگہہ یێمہِ ساتہٕ بہٕ ژے بنیامین سٕندِ سرزمینہٕ منزٕ اکھ نفر سوزُن، تہٕ ژٕ کرٕ سُہ میانین لوکن ہٕندِس اسرٲیلس پیٹھ کپتان بناونہٕ خٲطرٕ، یُتھ سُہ میانین لوکن فلسطینن ہٕندِ اتھہٕ نِش بچٲوِتھ، تکیازِ بہٕ چُھس پننین لوکن وُچھمُت، کیازِ تِہُند فریاد چُھ میہ نِش آمُت۔\n17. تہٕ یێلہِ سموئیلَن ساؤل وُچھ، خداوند ووٚن أمِس سٍتـ̡ یٔمِس شخصس سٍتـ̡ یٔمِس سٍتـ̡ میہ ژے کتھ کٔرمٕژ چھِ۔ یۅہے روزِ میانین لوکن پیٹھ حکومت۔ {reign over: Heb. رُکٲوِو اِن}\n18.\\tتێلہِ ووت ساؤل دروازس منز سموئیلس نِش تہٕ وونُن، بہٕ وَنُن ژے دُعا کَتہِ چھُ۔\n19.\\tتہٕ سموئیلَن دیُت ساؤلس جواب تہٕ وونُن، بہٕ چُھس میہ برونہہ کُن تھدِ مقامس پیٹھ گژھُن۔ تکیازِ ژیہ از میہ سٍتۍ کھٮ۪ن، تہٕ پگہہ بہٕ ژیہ تراوُن، تہٕ ژے وَنُن سُہ سورُے یُس تہندِس دِلس منز چُھ۔\n20.\\tتہٕ یُس تریہ دۅہ برونہہ رٲوِتھ آسہِ، تمن پیٹھ گژھہِ نہ پنُن ذہن۔ تکیازِ تم چھہِ لبنہ یوان۔ تہٕ کٔمِس پیٹھ چُھہ اسرٲیلٕچ سورے خواہش؟ {یہِ} چھُنہٕ ژےٚ تہٕ مٲلہِ سٕندِس سارِنٕے گرس پیٹھ؟ {ترے...: ہیب۔ دۅہس تام تریہ دۅہہ}\n21. تہٕ ساؤلن دیُت جواب تہٕ وونُن، {کیا بہٕ چُھس نہٕ بنی جیمی، یُس اسرٲیلِک لۄکٹِس قبیلس مَنٛز چُھہ؟ تہٕ میون عیال چھہ بنیامین قبیلہ کین سارِنٕے خاندانن منز کم؟ تیلہِ کیازِ چُھکھ ژیہ میہ سٍتۍ یۅہے کتھ کران؟ {تو...: ہیب۔ امہ لفظہ مطابق }\n22.\\tتہٕ سموئیل نیو ساؤل تہٕ تٔمۍ سٕندِس خادمَس مَنٛز، تہٕ أنِن تِمن مَنٛز سارِوٕے کھۄتہٕ بٔڈِس مقامس پیٹھ، یِمن ہُند حکم اوس دِنہٕ آمُت، یُس تقریباً ترہ نفر ٲسۍ۔\n23.\\tتہٕ سموئیلَن ووٚن کُنِس کُنِس سٍتـ̡ سُہ حصہٕ یُس میہ ژے دِژمُت اوس، یُس میہ ژے ووٚنمُت اوس، سُہ تھاوُن پانس سٍتـ̡ تھاوُن۔\n24.\\tتہٕ کٔرِن پھیپھ تہٕ {یہ} یُس اتھ پیٹھ اوس، تہٕ تھووُن ساؤلس برونہہ کُن۔ تہٕ {سموئیل} ووٚن، وُچھو یُس باقٕے چُھ! {یہ} تھوو پانس برونہہ کُن، {تہٕ} کھین: کیازِ از تام چُھس یہ ژے خٲطرٕ تھاونہٕ آمُت ییلہ میہ ووٚنمُت، مے چُھس لوکن دعوت دِژمٕژ۔ چنانچہ ساؤلن کھیوٚو تمہِ دۅہہ سموئیلس سٍتـ̡ کھیوٚن۔ {دٔچھُن: یا، محفوظ}\n25.\\tتہٕ ییلہ تِم تھزرِ جایہِ پیٹھٕ شہرس مَنٛز بۄن آیہ، {سموئیل} کٔر گرٕ کِس تھزرس پیٹھ شاؤلس سٍتـ̡ کتھ باتھ۔\n26. تہٕ تِم وٲتِتھ سُلہٕ سُلہٕ، تہٕ دۅہہٕ کِس بہار کِس موسم بہارس پٲٹھۍ، سموئیلن بُلوو ساؤلس گرٕ کِس تھزرس پیٹھ، تہٕ وونُن زِ بہٕ کرٕ ژے ژےٚ نیرنہٕ۔ تہٕ ساؤل ووٚتھ، تہٕ تِم گٔیہِ دۄشوے نیبر، سُہ تہٕ سموئیل نیبر۔\n27.\\tییلہ تم شہر کس اندس تام پکان ٲسۍ، سموئیلن ووٚن ساؤلس زِ خادم گژھہِ اسہِ برونہہ کُن نیرُن، (تہٕ سُہ گزریو،) مگر ژیہ تھوو کینژس کالس کھڑا یُتھ بہٕ ژے خدایہ سُند کلام ہٲوِتھ۔ {کیٚنٛہہ کال: ہیب۔ از تام}","1.\\tتێلہِ تُل سموئیلَن تیٖلٕچ اکھ شیشی، تہٕ ترووُن پننِس کلس پیٹھ، تہٕ کوٚرُن بوسہ دِتھ تہٕ وونُن، {یہ} چُھہ نہٕ امہِ مۅکھہ زِ خداوند چُھہ ژے تٔمِس وراثتس پیٹھ کپتان بٔنِتھ مسح کورمُت؟\n2.\\tییلہ ژے از میہ نِش نیرِ، تیلہِ میلہِ ژیہ زیلزاہِ منز بنیامین سٕندِس سرحدس پیٹھ راحیل سٕندِس قبرس نِش زٕ نفر لبنہٕ۔ تہٕ تِم وَنَن تۅہہِ یِم گَرٕ یِم ژےٚ ژھارنہٕ یژھان چھِو تِم چھِ لبنہٕ آمٕتۍ، تہٕ یِمن ہُند مٲل چُھس گَرَن ہُند خیال ترٛٲومُت، تہٕ چُھس تۅہہِ خٲطرٕ غم تہٕ ونان زِ بہٕ کیا کرٕ پننِس نیچوِس خٲطرٕ؟ {کیئر: ہیب۔ کاربار}\n3. تیلہِ گژھہِ تتہِ پیٹھہ برونہہ کُن تہ تیبور کِس میدانس مَنٛز واتہِ، تہٕ تتہِ گژھہِ تریہ نفر خدایس نِش بیتھلس تام گژھن، اکھ تریہ شُرۍ ہیتھ تہٕ بیاکھ تریہ روٹی تہٕ بیاکھ اکھ شرابچ بوتل ہیتھ ۔\n4. تہٕ تِم دِن تۅہہِ سلام، تہٕ دِن ژےٚ زٕ روٹ۔ یُس تہندِ اتھہٕ سٍتۍ میلہِ۔ {سلام...: ہیب۔ ژے پرژھ امن}\n5. اَمہِ پَتہٕ گژھِو تُہۍ خدایہِ سٕندِس پہاڑس پیٹھ یِنہٕ، یتہِ فلسطینن ہٕنز چھاونی چھےٚ، تہٕ یێلہِ تہٕ یێلہِ تہٕ شہرس مَنٛز وٲتِو، تێلہِ گژھہِ پیغمبرن ہٕنز اکھ جمٲژ یِم تھدِ جایہِ پیٹھٕ یِوان چھِ، تہٕ اکھ نالہٕ تہٕ اکھ ہارپ ہٮ۪تھ،  تمن برٛونٛہہ؛ تہٕ تِم کرِ پیشن گوئی:\n6. تہٕ خداوند سُند روح گژھہِ توے پیٹھ، تہٕ تُہۍ کرِ تِمن سٍتـ̡ پیشن گویی کرنہٕ، تہٕ یِیہِ بییِس انسانس منز تبدیل کرنہٕ۔\n7. تہٕ یێلہِ یێلہِ یِم نشانہٕ یِن تۅہہِ نِش یِن، {یێلہِ} تہٕ ژے کٔرِو تُہٕندِس موقعس سٍتـ̡ خدمت کرنہٕ۔ تکیازِ خدا چُھ توے سٍتـ̡ ۔ {تہٕ ...: ہیب۔ تہٕ یہ گژھہِ سپدِ، ییلہ یم نشانہٕ بیترِ} {یہ...: ہیب۔ چانہِ خٲطرٕ کٔرِو تُہند اَتھٕ لٔبِتھ}\n8. تہٕ ژٕ گژھ میانہِ برونہہ کُن گلگلس کُن۔ تہٕ وُچھِتھ بہٕ ژے نِش بٔسِتھ، زالنہٕ خٲطرٕ نذرانہ پیش کرنہٕ خٲطرٕ، تہٕ امن ہٕنزِ قربانی دِنہٕ خٲطرٕ: سَتھ دۅہہٕ روزٕ ژے روزُن، یوٚت تام بہٕ ژے نِش یِنہٕ، تہٕ ژے ہٲوِتھ کیا کرُن۔\n9. تہٕ یہٕ اوس {یِتھ} زِ ییلہِ سُہ سموئیلس نِش پتھ پھیرِ، خداین دِژ أمِس بیاکھ دِل: تہٕ تِم سارِنٕے نشانہٕ گٔیہِ تمہِ دۅہہ سپدٕنۍ۔ {واپس: ہیب۔ شولڈر} {دِیُت: ہیب۔ موڑ}\n10.\\tتہٕ ییلہ تِم تتہِ بالس پیٹھ وٲتۍ، وُچھ پیغمبرن ہُند اکھ جمٲژ أمِس سمکھ۔ تہٕ خدایہِ سُند روح آو أمِس پیٹھ، تہٕ تٔمۍ کٔر تِمن مَنٛز پیشن گوئی۔\n11.\\tتہ سپد ییلہ تس برونہہ زانن والیو یہ وُچھ زِ یمۍ پیغمبرن منز پیشن گویی کٔر، تمہ پتہ لوکو وون اکھ أکِس سٍتۍ، یہ کیا چھہ کیش سٕندِس نیچوس نِش آمُت۔ {is} ساؤل تہِ پیغمبرن منز؟ {اکھ...: ہیب۔ اکھ نفر پننس ہمساین خٲطرٕ}\n12.\\tتہٕ أتھۍ جایہ دیت جواب تہٕ وونُن، مگر تہند مول کُس چُھ؟ تَمہِ کِنۍ بنیوو یہِ اکھ محاورہٕ، {کیا ساؤل﴾ تہِ چھُ پیغمبرن مَنٛز؟ {of...: ہیب۔ تتہٕ پیٹھ}\n13. تہٕ ییلہ تٔمۍ پیشن گویی ختم کٔر، سُہ آو تھدِ مقامس پیٹھ۔\n14.\\tتہٕ ساؤل سٕندِس پیٚترَن ووٚن أمِس تہٕ پننِس خادمَس کوٚت گٔیہِ؟ تہٕ تٔمۍ ووٚن، گَرٕ ژھانڈنہٕ خٲطرٕ، تہٕ ییٚلہ أسۍ وُچھ زِ تِم ٲسۍ نہٕ کُنہِ جایہِ، أسۍ وٲتۍ سموئیلس نِش۔\n15.\\tتہٕ ساؤل سٕندِس پیٚترَن ووٚن، بہٕ وَنُن ژےٚ دُعا کَرُن، سموئیلَن کیا ووٚنمُت۔\n16.\\tتہٕ ساؤلن ووٚن پننِس پیٚترس زِ تٔمۍ ووٚن اسہِ سیدِ سیود زِ گَرٕ آیہ لبنہٕ۔ مگر بادشٲہی ہٕندِس معاملس متعلق، یتھ متعلق سیموئیل کتھ کٔر، تٔمۍ ووٚن نہٕ تمِس نہٕ۔\n17. تہٕ سموئیلَن بُلوو لُکھ رٔبِس مِزپہٕ سٍتـ̡ ۔\n18.\\tتہٕ وونُن بنی اسرٲیل، یِتھٕ پٲٹھۍ چُھ اسرٲیلُک خداوند خداوند ونان، مے کٔر اسرٲیلِس مصرہٕ منزٕ نِش تہٕ تۅہہِ نِش تہٕ سارِنٕے سلطنتن ہٕندِ اتھہٕ نِش نجات دِژمٕژ یِمو تۅہہِ سٍتـ̡ ظلم کٔرۍ۔\n19. تہٕ توے چُھ از پَنُن خدایہ رد کورمُت، یُس پانَے تُہٕندِس تمام مُصیبتن تہٕ مصیبتن نِش بچٲو۔ تہٕ ژے چُھہ أمِس ووٚنمُت، {نہ}، مگر اسہِ پیٹھ تھوو اکھ بادشاہ۔ تَمہِ مۄکھٕ کٔرِو پَنٕنـ̡ قٔبیٖلہٕ سٍتـ̡ تہٕ ساسہٕ بٔدۍ سٍتـ̡ خداوند سٕندِ برونہہ کُن پیش۔\n20. تہٕ یێلہِ سموئیل سٕندِ سارِنٕے قبیلہٕ اِسرٲیلِس نزدیک، بنیامین سُند قبیلہٕ آو نِنہٕ۔\n21.\\tییلہ تٔمۍ بنیامین قبیلہٕ تِہندِ عیالس نِش نِنہٕ آو، ماتری سُند عیال آو نِنہٕ، تہٕ کیش سُند نیچو ساؤل آو نِنہٕ، تہٕ ییلہ تمو أمِس ژھانڈان اوس، سُہ ہیوٚک نہٕ لٔبِتھ۔\n22. تَمہِ کِنۍ کٔر تِمو خداوند سٕندِس نِش مزید پرژھہٕ، اگر یہِ انسان وُنہِ تہِ یِنہٕ۔ تہٕ خداوند دیُت جواب، وُچھ، تٔمۍ چُھ پنُن پان چیزن منز ژوٗرِ تھوومُت۔\n23.\\tتہٕ تِمو ژٔلِتھ تہٕ أنِتھ أمِس اَتہِ نِش تہٕ ییلہ سُہ لُکن مَنٛز کھڑا اوس، سُہ اوس کٲنٛسہِ تہِ لُکہٕ کھۅتہٕ تھوٚد تہٕ ہیوٚر کُن۔\n24.\\tتہٕ سموئیلن ووٚن سارنٕے لُکن سٍتـ̡ وُچھو، یُس خداوند چُھ ژٲرمُت، یێلہِ سارِنٕے لُکن مَنٛز چُھہ نہٕ أمِس ہیوٗ کانہہ تہِ؟ تہٕ سارِوٕے لُکھ دِژ کرٛٮ۪کھ، تہٕ وونُن، خدایہ رژھ بادشاہ۔ {خدا...: ہیب۔ بادشاہ زندٕ روزُن}\n25. پَتہٕ ووٚن سموئیلَن لُکن بادشٲہی ہُند طریقہٕ، تہٕ لیوٚکھُن أکِس کتابہِ مَنٛز، تہٕ تھووُن خداوند سٕندِس برونہہ کُن۔ تہٕ سموئیلَن سوٗزۍ سٲری لُکھ پننِس گرس منز۔\n26. تہٕ ساؤل تہِ گوٚو گِبیاہ کُن گَرٕ۔ تہٕ أمِس سٍتـ̡ گۆو انسانن ہُند اکھ جمٲژ، یێمن ہٕندِس دِلس خداین ہُند دِل چھُ۔\n27.\\tمگر بِلیال سٕندِ شُرۍ ووٚن زِ یہِ انسان کِتھہ کٔنۍ کرِ اسہِ بچاو۔ تہٕ تِمو کٔر أمِس حقارت تہٕ أنِکھ نہٕ أمِس کانٛہہ تہِ تحفہٕ۔ مگر تٔمۍ روٗد پنُن امن۔ {رٔلِتھ...: یا، اوس زن سہ زرٕ گومُت}","1.\\tاَمہِ پَتہٕ آو ناہش عمونیت تہٕ کوٚرُن جابشِگلاڈَس خلاف ڈیرٕ ترٲوِتھ تہٕ یَبش سٕندِس سارِوٕے نفرو ووٚن ناہشَس زِ اسہِ سٍتـ̡ کٔرِو اَسہ سٍتـ̡ عہد تہٕ أسۍ کٔرِو تۅہہِ سٍتـ̡ خدمت۔\n2.\\tتہٕ ناہش عمونین دیُت تِمن جواب، یَتھ {شرط} پیٹھ کرٕ بہٕ ژےٚ سٍتـ̡ {اکھ معاہد}، یُتھ بہٕ کرٕ تۅہہِ سارِنٕے دٔچھنِس أچھ کٔرِتھ، تہٕ سارِنٕے اسرٲیلِس سٍتـ̡ ملامت کرنہٕ خٲطرٕ۔\n3.\\tتہٕ یابت سٕندٮ۪و بزرگو ووٚن أمِس زِ اسہِ دِیُن ستن دۅہن مہلت دِیُن، یُتھ أسۍ اسرٲیلِہ کِس سارِنٕے ساحلن تام رسول سوزِتھ، تہٕ پَتہٕ یێلہِ نہٕ اسہِ بچاونہٕ خٲطرٕ کانہہ تہِ نفر آسہِ، أسۍ یِو تۅہہِ نِش نِش۔ {دِیو...: ہیب۔ اسہِ کٔرِو برداشت کٔرِ}\n4.\\tاَمہِ پَتہٕ آو ساؤل سٕندِس گِبعاہس نِش تہٕ وونُکھ لُکن ہٕندِس کنن مَنٛز خبر تہٕ سارِوٕے لُکھ تُلِتھ تہٕ رووُن۔\n5. تہٕ وُچھِو ساؤل کھہٕ منزٕ کھیٚلہِ پَتہٕ نِش دِنہٕ۔ تہٕ ساؤلن ووٚن، یِمن لُکن کیا چُھ یِم روان چھِ؟ تہٕ تِمو ووٚن أمِس جابیش کین نفرن ہٕنز خبر۔\n6. تہٕ خدایہِ سُند روح آو ساؤلس سٍتـ̡ یێلہِ یِم خبر بوٗزِ، تہٕ تٔمِس سُند غصہٕ گۆو سٮ۪ٹھاہ دِنہٕ۔\n7. تہٕ تٔمۍ رٔٹِتھ بیلن ہُند اکھ جو، تہٕ ژٔٹِتھ ژٔٹِتھ تہٕ سوٗزُن رسولن ہٕندِ اتھہٕ سٍتـ̡ اسرٲیلٕکِس سارِنٕے ساحلس منز، یہِ وونُن زِ یُس نہٕ ساؤل تہٕ سموئیلس پَتہٕ یِنہٕ یِنہٕ سٍتـ̡ یُس نہٕ ساؤل سٕندِس پَتہٕ نیرِ، تِتھٕ پٲٹھـ̡ گژھہِ تٔمۍ سٕندِس بیلن سٍتـ̡ کرنہٕ۔ تہٕ خداوند سُند خوف آو لُکن پیٹھ، تہٕ تِم درٛاو اَکہِ رضامندی سٍتـ̡ نیبر۔ {with...: Heb. بطور اکھ انسان}\n8. تہٕ ییلہ تٔمۍ تِمن بیزیکس منز گنزرٲو، بنی اسرائیلٕکۍ ٲسۍ ترے لچھ تہٕ یہوداہ ہٕکۍ مرد ٲسۍ ترہ ساس۔\n9.\\tتہٕ تِمو ووٚن یِمن رسولن یِمن یِنہٕ والٮ۪ن یِتھٕ پٲٹھۍ، یێلہِ آفتاب گرم گژھہِ، تۅہہِ میلہِ مدد۔ تہٕ رسولن آیہِ تہٕ ہٲوِکھ جابیش کین نفرن ہُند ۔ تہٕ تِم ٲسۍ خۄش۔ {مدد: یا، نجات دِنہٕ}\n10. تێمہِ کِنۍ ووٚن جابش سٕندیو لوکو زِ پگہہ گژھہِ أسۍ ژےٚ نِش نیرِو، تہٕ تُہۍ کٔرِو اسہِ سٍتـ̡ سٍتـ̡ یُس تۅہہِ سٍتـ̡ خیر باسان۔\n11.\\tتہٕ پَگہہ دِژ ساؤلَن لُکھ ترٚین کمپنین مَنٛز۔ تہٕ تِم آیہِ صبحس پہرِ منز میزبانس منز، تہٕ مارِکھ امونِس دۅہلہِ ہٕندِس گرمی تام تہٕ یہِ سپُد زِ تِم یِم باقٕے گٔیہِ بکھرِتھ، تہٕ یِمو منزٕ گٔیہِ نہٕ دۅشوے اکوٹہٕ۔\n12. تہٕ لوکو ووٚن سموئیلس زِ سُہ کُس چُھ یُس ووٚنمُت چُھ، کیا ساؤل کرٕ اسہِ پیٹھ بادشاہت؟ مرد أنِو، تاکہ أسۍ مارٕ دِتھ۔\n13. تہٕ ساؤلن ووٚن زِ از گژھِ نہٕ کانہہ انسان مارنہٕ یُن، تکیازِ از تہِ چُھ خداوند اسرٲیلِس مَنٛز نجات دِژمٕژ۔\n14.\\tاَمہِ پَتہٕ ووٚن سموئیلَن لُکن سٍتـ̡ یِمو تہٕ أسۍ گِلگلَس کُن گٔژھِو، تہٕ اَتہِ کٔرِو بادشٲہی تازٕ۔\n15.\\tتہٕ سارِنٕے لُکھ گٔیہِ گلگلَس کُن۔ تہٕ تتہِ بنوو تِمو ساؤل گلگلس منز رب سٕندِ برونہہ کُن بادشاہ۔ تہٕ تتہِ کٔر تِمو خداوند سٕندِ برونہہ کُن امن ہٕنزِ قربانی۔ تہٕ اَتہِ گٔیہِ ساؤل تہٕ اِسرٲیلِکۍ سارِوٕے لُکھ سٮ۪ٹھاہ خۄش۔","1. تہٕ سموئیلَن ووٚن سارِنٕے اِسرٲیلِس سٍتـ̡ ، وُچھِو مے تُہٕنز آواز بوزمٕژ یُس تہٕ چُھس ژے سٍتـ̡ بادشاہ بنوومُت۔\n2. تہٕ وُنہِ وُچھ، بادشاہ چُھس ژےٚ برونہہ کُن پکان: تہٕ بہٕ چُھس بُزرگ تہٕ سوٗر کلہٕ۔ تہٕ وچھ میٲنۍ نیچوۍ چِھہ ژے سٍتۍ: تہٕ بہٕ چُھس پننہ لۅکچارٕ پیٹھٕ از تام ژےٚ برونہہ کُن پکان ۔\n3. وُچھِو، یێلہِ چُھس بہٕ یێلہِ خداوندٕ سٕندِس برونہہ کُن تہٕ تٔمۍ سٕندِس مسح کرنہٕ آمتس برونہہ کُن گوٲہی دِژمٕژ: مے کُس بیل چُھہ نِمُت؟ نتہ میہ کمۍ سٕندِس گٔرۍ؟ یا مےٚ کٔمِس دھوکہٕ دِژمُت؟ میہ کُس ظلم کورمُت؟ یا میہ کٔمۍ سٕندِس اتھس سٍتۍ چُھس پننہ اچھ انہِ کرنہٕ خٲطرٕ رُشوت دِژمٕژ؟ تہٕ بہٕ کٔرٕ یہ ژےٚ واپس۔ {رُشوت: ہیب۔ تاوان} {انہِ گٹہِ...: یا، یہ زِ بہٕ پزِ تس کُن پنٕنۍ أچھ ژوٗرِ تھاوُن}\n4.\\tتہٕ تِمو ووٚن زِ ژے کٔر نہٕ اسہِ دھوکہٕ دِژمُت، تہٕ نہ کٔرٕکھ اسہِ سٍتـ̡ ظلم، تہٕ نہ کٔرٕکھ کٲنٛسہِ ہٕندِس اتھہٕ سٍتـ̡ ۔\n5. تہٕ تٔمۍ ووٚن تِمن زِ خداوند چُھہ تۅہہِ خلاف گواہ تہٕ تٔمۍ سُند مسح کرنہٕ آمُت گواہ چُھہ از دۅہہ، یُس نہٕ میانہِ اتھس منز لبنہٕ آمُت چُھ۔ تہٕ تمو دیت جواب، {سُہ چُھ} گواہ۔\n6. تہٕ سموئیلَن ووٚن لُکن زِ یہِ چُھ خداوند یٔمۍ موسیٰ تہٕ ہارون برونہہ کُن دِژمُت تہٕ یٔمۍ تُہٕندِس آباؤ اجداد مصر کِس سرزمینہٕ منزٕ نیبر کٔرِتھ۔ {ایڈوانسڈ: یا، بنیومُت}\n7. تێمہِ وِزِ کھڑا روزُن، یُتھ بہٕ خداوند سٕندِس سارِنٕے نیک عملن ہٕندِس مٲلِس سٍتـ̡ تہٕ تۅہہِ سٍتـ̡ تہٕ تُہٕندِس مٲلِس سٍتـ̡ کٔرِتھ تہٕ تُہٕندِس مٲلِس سٍتـ̡ کٔرِتھ کٔرِتھ۔ {راستباز...: حب۔ نیکی یا فٲیدٕ} {to: Heb. with}\n8. یێلہِ یعقوب مصرس مَنٛز آو، تہٕ تۅہہِ بابو کٔر خداوند سٍتـ̡ فریاد کرنہٕ، تێلہِ سوٗزۍ خداوند موسیٰ تہٕ ہارون، یِمو تُہند باپ مصرہٕ منزٕ نیبر کٔرِتھ تہٕ یێمہِ جایہ روزُن ۔\n9.\\tتہٕ ییلہ تِمو خداوند پنُن خدا مٔشِد کٔر، تٔمۍ کُن تِم حزور کِس لشکرُک کپتان سیسیرا سٕندِس اتھس منز، تہٕ فلسطینن ہٕندِس اتھس منز، تہٕ موآب کِس بادشاہس اتھس منز، تہٕ تِمو کٔر تِمن خلاف جنگ۔\n10. تہٕ تِمو کٔر خداوند سٕندِ نِش فریاد تہٕ وونُن، أسـ̡ چُھ گۅناہ کورمُت، کیازِ أسـ̡ چُھ خداوند ترٲومُت، تہٕ چُھکھ بعلیم تہٕ اشتروتھٕچ خدمت کٔرمٕژ، مگر وۄنۍ کٔرِو اسہِ دُشمنن ہٕندِ اتھہٕ نِش نجات تہٕ أسۍ کٔرِو تۅہہِ ہٕنز خدمت۔\n11. تہٕ خداوند سوٗزۍ یرُبعل، بیدان، یفتاح تہٕ سموئیل، تہٕ دِژُکھ ژےٚ پرٮ۪تھ طرفہٕ پَنٕنٮ۪ن دُشمنن ہٕندِ اتھہٕ نِش نِش بچاوُن، تہٕ تُہۍ روٗدۍ محفوٗظ۔\n12.\\tتہٕ ییلہ ژے وُچھ زِ عمون کِس اولادَن ہُند بادشاہ نہاش آو توے سٍتـ̡ ، ژے ووٚن میہ نہ۔ مگر اسہِ پیٹھ گژھہِ اکھ بادشاہ بادشاہ: یێلہِ خداوند تُہند خدا تُہند بادشاہ آسہِ۔\n13.\\tتێلہِ وُچھو سُہ بادشاہ یُس ژے ژٲرمُت چُھ، {تہٕ} یُس ژے یژھان چھُو! تہٕ وُچھِو، خداوند چُھ تۄہہِ پیٹھ اکھ بادشاہ مقرر کوٚرمُت۔\n14. یێلہِ تہٕ یێلہِ تُہۍ خداوند سٕندِس حُکمس سٍتـ̡ بغاوت کٔرِو، تہٕ تٔمِس سٕنزِ آوازِ ہٕنز اطاعت کٔرِو، تہٕ خداوند سٕندِس حُکمس خلاف کٔرِو نہٕ بغاوت کٔرِو، تێلہِ گژھِو تُہۍ تہٕ یُس بادشاہ تہِ پانس پیٹھ راج کران چُھہ، تہٕ یێلہِ تہٕ یُس بادشاہ تہِ چُھہ تُہٕندِس خدایہِ سٕنزِ پٲروٲنی کٔرِتھ: {حکم: حب۔ ٲس} {جٲری...: ہیب۔ پَتہٕ آسُن}\n15. مگر یێلہِ نہٕ تۅہہِ خداوند سٕنزِ آوازِ ہٕنز اطاعت کٔرِو، بٔلکہِ خداوند سٕندِس حُکمس خلاف بغاوت کٔرِو، تێلہِ گژھہِ خداوند سُند اتھہٕ تہٕ یێلہِ تہندِس مٲلس سٍتـ̡ آسہِ۔\n16. تێمہِ وۆنـ̡ کھڑا گژھِو تہٕ وُچھِو یہِ بٔڈ چیز، یُس خداوند تُہنزِ نظرن برونہہ کُن کرِ۔\n17.\\t{کیا یہ} چھُنہٕ از کل کٕنٕک فصل؟ بہٕ کَرٕ خداہس بُلاونہٕ، تہٕ سُہ سوزِ گرٛاے تہٕ روٗد۔ یُس تۅہہ وُچھِتھ تہٕ وُچھِو زِ تُہٕنز بدکاری چھیہ بٔڈ، یُس ژے خداوند سٕندِس نظرس منز کٔرمُت چُھ، یُس ژے بادشاہ منگنس مَنٛز کورمُت چھُ۔\n18.\\tتێلہِ دِژ سموئیلَن خداوند سٍتـ̡ بُلاونہٕ۔ تہٕ خداوند سوٗز تمہِ دۅہہ گرٛاے تہٕ روٗد: تہٕ سارِوٕے لُکھ گٔیہِ خداوند تہٕ سموئیلس سٍتـ̡ واریاہ خوف۔\n19. تہٕ سارِوٕے لُکو ووٚن سموئیلس زِ پَنٕنـ̡ پنہٕ نـ̡ خدایہِ سٕندِس خداہس سٍتـ̡ کٔرِو پَنٕنـ̡ پَنٕنـ̡ خادمَن ہٕندِ خٲطرٕ دُعا ، یێلہِ أسـ̡ نہٕ مَرٕن، تِکیازِ أسـ̡ چُھہ پننین سارِنٕے گۅناہَن مَنٛز بُرٕ ہُرراومُت، یُس اسہِ سٍتـ̡ بادشاہ منگنہٕ خٲطرٕ۔\n20. تہٕ سموئیلَن ووٚن لُکن زِ خوفہٕ نہٕ کرُن: یِہ سورُے بد عمل کٔرِو، توتہِ کٔرِو نہٕ خداوند سٕنز پیروی کرنہٕ نِش پتھ کُن، بلکہ کٔرِو خداوند سٕنز پوٗرٕ دِلہٕ سٍتـ̡ خدمت۔\n21.\\tتہٕ پتھ کُن گژھِو نہٕ پتھ کُن: {تیلہٕ گژھِو} بیکار {چیزن} پتہٕ، یُس نہٕ فٲیدٕ دِتھ تہٕ نہ دِنہٕ آمُت چھُ۔ تکیازِ تم چھہِ بیکار۔\n22.\\tکیازِ خداوند کرِ نہٕ پننِس عظیم ناوٕ خٲطرٕ پننین لوکن تراوُن: کیازِ یہِ چُھ خداوند خوش گومُت زِ سُہ چُھ تُہۍ پنُن قوم بنوومُت۔\n23. یێلہِ تہِ میانہِ خٲطرٕ، خدایہ کرِ نہ زِ بہٕ کرٕ خدایہ سٕندِس خلاف گۅناہ کرنہٕ یُس تہٕ تۅہہِ خٲطرٕ دُعا کرنہٕ بند کرُن، مگر بہٕ ہیچھناوٕ ژے اصل تہٕ صحیح وتھ ہیچھناوٕن: {منز: عبرانی۔ منز}\n24.\\tصرف خداوند سٍتـ̡ کھوژُھن، تہٕ پَنٕنـ̡ دِلہٕ سٍتـ̡ خدمت کٔرِو۔ {کتھہ پاٹھۍ...: یا، کیا زبردست چیز}\n25. مگر اگر توتہِ بدکار کٔرِو، تیلہِ گژھِو تۅہہ تہٕ پنُن بادشاہ دۅشوے کھٮ۪نہٕ۔","1. ساؤلن کٔر أکِس ؤریس پیٹھ حکومت۔ تہٕ ییلہ تٔمۍ دۄن ؤرین اسرائیلس پیٹھ حکومت کٔر، {اَکہِ حُکوٗمت...: حب۔ تٔمۍ سٕنٛدِس دورِ حکوٗمتس منٛز اَکہِ ؤرۍ یُک نیٚچُو}\n2. ساؤلن چُھ أمِس ترے ساس اسرٲیلُک انتخاب۔ زٕ ساس ٲسۍ ساؤلس سٍتـ̡ مِشماش تہٕ بیتھل کِس پہاڑس مَنٛز، تہٕ ساس اوس یوناتھن سٍتـ̡ بنیامین کِس گبیاہس مَنٛز۔\n3.\\tتہٕ یوناتھنن دِژ فلسطینن ہٕنزِ چھاونی یُس گیبا ہس منز {اوس}، تہٕ فلسطینیو بوز یہِ۔ تہٕ ساؤلن وُن سٲرۍسٕے زمینس منز بُرٕ، یہِ وَنُن زِ عبرانیو بوزُن۔ {گیبا: یا، بال}\n4.\\tتہٕ سارِنٕے اسرٲیلَن بوز یہِ زِ ساؤلَن اوس فلسطینن ہٕنزِ چھاونی ہُند حملہٕ کوٚرمُت، تہٕ {یہ} اسرٲیلِس تہِ اوس فلسطینن سٍتـ̡ بد ظٲہِر کرنہٕ آمُت۔ تہٕ لُکھ آیہ ساؤل پتہٕ گلگل کُن اِکہٕ وٹہٕ بُلاونہٕ۔ {اوس...: ہیب۔ کیا بدبو}\n5.\\tتہٕ فلسطینیو جمع سپٕدۍ اسرٲیلس سٍتـ̡ لڑنہٕ خٲطرٕ، ترہ ساس رتھ، تہٕ شیہ ساس گُرۍ سوار، تہٕ لُکھ لُکھ سمندرٕ بٹھِس پیٹھ بٔڈِس سٍتـ̡ لڑنہٕ خٲطرٕ، تہٕ تِم وٲتِتھ وٲتِتھ مِخماشس کُن یُس بٔٹھِس کُن بٔڈِتھ چُھ۔\n6.\\tییلہ اسرٲیلِیو وُچھ زِ تِم چِھہ أکِس مُشکِلس مَنٛز، (تِکیازِ لُکھ ٲس مُشکِل گٔژھمٕژ) تہٕ لُکھ گۅپھن مَنٛز، کٔنٮ۪ن مَنٛز، تہٕ تھدٮ۪ن جاین تہٕ گۄڑن مَنٛز ژوٗرِ۔\n7. تہٕ کینہہ عبرانیو گٔے اردن اپارِ گاد تہٕ جلعاد کِس سرزمینس کُن۔ یوٚتام ساؤل سُہ اوس وُنہِ تہِ گلگلس مَنٛز، تہٕ سارِنٕے لُکھ گٔیہِ أمِس پَتہٕ تھرِ تھران۔ {فالو...: ہیب۔ تس پتہ لرزِ}\n8.\\tتہٕ سُہ روٗد سَتھ دۅہہ، سموئیلَن مُقرر کرنہٕ آمُت وقتٕ مُطٲبق، مگر سموئیل آو نہٕ گلگلس کُن۔ تہٕ لوٗکھ گٔیہِ أمِس نِش بکھرِتھ۔\n9. تہٕ ساؤلن ووٚن زِ میانہِ خٲطرٕ أنِو دزنہٕ نذرانہ تہٕ امن ہٕنز پیشکش۔ تہٕ تٔمۍ کٔر دزنہٕ نذرانہ پیش۔\n10. تہٕ سپُد یہِ زِ یێلہِ تٔمۍ دزنہٕ نذرانہ پیش کرُن ختم کٔر، وُچھ سموئیل ووت ۔ تہٕ ساؤل دراو أمِس سمکھنہٕ خٲطرٕ، تاکہ سُہ کرِ أمِس سلام۔ {سلام: ہیب۔ برکت دِیُو}\n11.\\tتہٕ سموئیل ووٚن، ژے کیا چُھہ کورمُت؟ تہٕ ساؤلن ووٚن، تکیازِ میہ وچھ زِ لُکھ گٔیہِ میہ نِش بکھرِتھ، تہٕ {یہ} تہٕ ژے آو نہٕ مقرر کرنہٕ آمٕتۍ دۅہن منز، تہٕ {یہ} فلسطینی گٔیہِ مِخماسس مَنٛز جمع ۔\n12. تێمہِ کِنۍ ووٚن میہ زِ فلسطینی یِن وۅنۍ گلگلس کُن وسُن، تہٕ مے کٔر نہٕ خداہس سٍتـ̡ دُعا کرنہٕ۔ {بنیومُت...: ہیب۔ بُتھِس سٍتۍ کٔرِتھ}\n13. تہٕ سموئیلن ووٚن ساؤلس زِ ژے کٔر بیوقوفی سٍتـ̡ تہٕ ژے چُھہ نہٕ خداوند پنُن خدا سُند حُکُم، یُس تٔمۍ تۅہہِ حُکُم دِیُتمُت اوس، تێکیازِ وُنہِ آسہِ خداوند تُہٕنز بادشاہت اسرٲیلِس پیٹھ ہمیشہٕ خٲطرٕ قٲیم کٔرمٕژ۔\n14. مگر وۅنۍ روزِ نہٕ تہنز بادشٲہی جٲری: خداوند چُھ أمِس پننِس دِلہٕ سٍتـ̡ أکِس انسانس ژھانڈمُت، تہٕ خداوند چُھ أمِس پننِس لوکَن ہُند کپتان بننُک حُکُم دِژمُت، کیازِکہِ ژے چُھہ نہٕ سُہ پورٕ کوٚرمُت یُس خداوند چُھہ حُکُم دِژمُت۔\n15.\\tتہٕ سموئیل ووٚتھ تہٕ ووت گلگل پیٹھٕ بنیامین سٕندِس گبیاہس تام۔ تہٕ ساؤلن کٔر تِمن لُکن ہُند تعداد یِم أمِس سٍتـ̡ موجود ٲسۍ، تقریباً شیہ ہتھ نفر۔ {موجود: ہیب۔ لٔب}\n16. تہٕ ساؤل، تہٕ یوناتھن تٔمۍ سُند نیچو، تہٕ یِمن سٍتـ̡ موجود لُکھ بنیامین کِس گِبعاہس مَنٛز روزنہٕ آمٕتۍ، مگر فلسطینیو کٔر مِخماسس مَنٛز ڈیرٕ۔ {موجود: ہیب۔ لٔب} {گیبیہ: ہیب۔ گیبا}\n17. تہٕ دِژ فلسطینن ہٕندِس خٲمہٕ منزٕ ترٚین کمپنین منز: اَکھ کمپنی گٔیہِ وتہِ کُن یُس اوفراہ کُن گژھان چُھ، شوال کِس سرزمینس کُن:\n18.\\tتہٕ بیاکھ کمپنی پھیرۍ وتھ {کُن} بیتھورون کُن: تہٕ بیاکھ کمپنی پھیرۍ سرحد کِس وتہِ کُن یُس زیبویم کِس وادی کُن بیابانس کُن وچھان چھُ۔\n19. وُنہِ اوس نہٕ سارِنٕے سرزمینس منز کانہہ تہِ لوہار لبنہٕ آمُت، تکیازِ فلسطینیو ووٚن زِ یِمن ہٕندِ تلوار یا نیزٕ بناوٕن:\n20. مگر سارِنٕے اِسرٲیلِیو گٔیہِ فلسطینن نِش، پرٮ۪تھ أکِس انسانس پنُن حصہٕ، تہٕ تٔمۍ سُند کلہٕ تہٕ تٔمۍ سٕندِس کلہٕ سٍتـ̡ تیز کرنہٕ خٲطرٕ۔\n21.\\tتوتہِ ٲس تِمن ہٕندِ خٲطرٕ اکھ فایل، تہٕ کولٹرن ہٕندِ خٲطرٕ، تہٕ کانٹَن ہٕندِ خٲطرٕ، تہٕ کلہٕ خٲطرٕ، تہٕ گُرِ تیز کرنہٕ خٲطرٕ۔ {اکھ فایل: ہیب۔ اکھ فایل، یتھ منز ٲس، یا ہیب۔ اکھ پِم، اکھ تریم شیکل} {تیز: ہیب۔ سیٹ}\n22. یِتھٕ پٲٹھۍ سپُد جنگہٕ کہِ دۅہہٕ زِ ساؤل تہٕ یوناتھن سٍتـ̡ اوس نہٕ کٲنٛسہِ تہِ لُکن ہٕندِس اتھس منز تلوار تہٕ نیزٕ لبنہٕ آمُت، مگر ساؤلس تہٕ یوناتھن سٍتـ̡ اوس تٔمۍ سُند نیچو لبنہٕ آمُت۔\n23.\\tتہٕ فلسطینن ہٕنز چھاونی دراو میخماش کِس وتہِ کُن۔ {گیریسن: یا، سٹینڈنگ کیمپ}","1.\\tوۅنۍ آو اکہ دۅہہ ییلہ ساؤل سٕندِ نیچوۍ یوناتھن ووٚن نوجوانس زِ یُس پنُن ہتھیار نوٚن کٔرِتھ، یُس پنہٕ نِس ہتھیار نِش نِش نیرِو، یُس دوٚیمہِ طرفہٕ فلسطینن ہٕنزِ چھاونی کُن گژھِ۔ مگر تٔمۍ ووٚن نہٕ پننِس مٲلِس۔ {یہ آو ...: یا، اکھ دۅہ اوس}\n2.\\tتہٕ ساؤل روٗد گبعہ کِس اندِس حصس مَنٛز أکِس انار کُلِس تَل یُس مِگرونس مَنٛز {چُھ} چُھ، تہٕ یِم لُکھ أمِس سٍتـ̡ {ٲس} ٲسۍ، تِم ٲسۍ تقریباً شیہ ہتھ نفر۔\n3. تہٕ احیٰ، احیتوبُک نیٚچُو، اِخابودُن بوے تہٕ فینہاسُن نیچو، ایلی سُند نیچو، یُس شیلوہس مَنٛز خداوند سُند پادٕرۍ اوس، یُس ایفود لٲگِتھ اوس۔ تہٕ لوٗکَن ٲس نہٕ پتاہ زِ جوناتھن اوس ژوٚلمُت۔ {احیٰ: وَننہٕ آمُت}\n4. تہٕ تمن وتن درمیان، یِمو سٍتـ̡ یوناتھن فلسطینن ہٕنزِ چھاونی تام واتنچ کوشش کٔر، اَکہِ طرفہٕ اوس اکھ تیز پتھر، تہٕ دوٚیمہِ طرفہٕ اوس اکھ تیز پتھر: تہٕ أکِس سُند ناو اوس بوزیز، تہٕ بییِس سینہ سُند ناو۔\n5.\\tاَکہِ ہُند برونہمہٕ اوس میخمشس خٕلاف شمالس کُن تہٕ بیٛاکھ جنوبس کُن گبیعاہس خٕلاف۔ {برونٛہہ: ہیب۔ دند}\n6.\\tتہٕ یوناتھنن ووٚن نوجوانس یُس پنُن ہتھیار نِش رٔٹِتھ چُھہ، یِمن ہٕندِس بٔرِس نِش گژھُن، یِمن ہٕندِس چھاوَس مَنٛز گژھُن: یہِ ہیکہِ ٲسِتھ زِ خداوند کرِ سانہِ خٲطرٕ کٲم: کیازِکہِ خداوند سٕندِ خٲطرٕ چُھنہٕ کانہہ تہِ روک تھام۔\n7.\\tتہٕ تٔمۍ سٕندِس ہتھیار بردارن ووٚن أمِس دِلَس مَنٛز یُس {چُھ} سُہ کٔرِو: پھیُرُن۔ وچھ بہٕ چُھس ژے سٍتـ̡ تہندِس دِلس مطٲبق تہٕ\n8.\\tپتہٕ ووٚن یوناتھن، وُچھِو أسۍ یِمن نفرن نِش نیرِتھ، تہٕ أسۍ کرو تِمن نِش پنُن پان دِنہٕ۔\n9.\\tاگر تِم اسہِ یۅہے ونان چھِ، توٚت تام روزو یوتام نہ أسۍ ژے نِش یِن۔ تیلہ گژھو أسۍ پننہ جایہ کھڑا تہٕ تمن تام گژھو نہٕ۔ {ٹیری: ہیب۔ خاموش روزُن}\n10.\\tمگر اگر تم یتھہ پاٹھۍ ونان چھہِ، اسہِ نش گژھہِ اسہِ نِش۔ تیلہِ گژھو أسۍ تھوٚد: کیازِ خداوند چُھ تِم سانہِ اتھس مَنٛز دِژمٕتۍ، تہٕ یہِ آسہِ اسہِ خٲطرٕ اکھ نشانی۔\n11.\\tتہٕ یِمو دۅشویو لٔج پان فلسطینن ہٕنزِ چھاونی نِش دریافت، تہٕ فلسطینیو ووٚن، وُچھِو عبرانیو تِمن سوراخن منزٕ نیبر نیران ییتہِ تِمو پان ژوٗرِ ٲس۔\n12. تہٕ چھاونی ہٕندیو نفرو دِژ جوناتھن تہٕ تٔمۍ سٕندِس ہتھیار بردارس جواب تہٕ وونُن، اسہِ نِش آو تہٕ أسۍ ہٲوِو ژےٚ اکھ چیز۔ تہٕ یوناتھنن ووٚن پننِس ہتھیار بردارس زِ میانہِ پتہٕ یِن یِم اسرٲیلِس اتھس مَنٛز دِنہٕ۔\n13.\\tتہٕ جوناتھن ووت پننین اتھن تہٕ پننین قدمن پیٹھ، تہٕ تٔمۍ سٕندِس ہتھیار بردارس پٔتۍ، تہٕ تِم گٔیہِ جوناتھن برونہہ کُن۔ تہٕ تٔمۍ سُنٛد ہتھیار بردار مور أمس پتہٕ۔\n14.\\tتہٕ سُہ گۅڈنیُک ذبح، یُس جوناتھن تہٕ تٔمۍ سٕندِس ہتھیار بردارس کٔر، اوس تقریباً وُہ نفر، تکیازِ یہ اوس نصف ایکڑ زمینہٕ، {یُس} اکھ جوُل {بیلن ہُند} ہل ہٲوِتھ۔ {an...: یا، اکھ ایکڑ زمینُک نصف کھال}\n15.\\tتہٕ میدانس منز، تہٕ سارِنٕے لُکن منز اوس تھرتھر تھر تھرٲومُت: چھاونی تہٕ خراب کرن والۍ، تِم تہِ لٔگۍ تھرتھر، تہٕ زمین لٔج لرز: یِتھٕ کٔنۍ اوس یہِ سٮ۪ٹھاہ لرزان۔ {اکھ سٮ۪ٹھاہ...: ہیب۔ خدایہِ سُند تھر تھرُن}\n16.\\tتہٕ بنیامین سٕندِس گِبعاہس مَنٛز ساؤل سٕندِس چوکیدارَو وُچھ۔ تہٕ وُچھِتھ گٔیہِ ہجوم پٔلِتھ تہٕ تِم گٔیہِ اکھ أکِس ماران۔\n17.\\tاَمہِ پَتہٕ ووٚن ساؤلَن تِمن لُکن یِم أمِس سٍتـ̡ ٲسِتھ، وُچھِو وُچھِو زِ اسہِ نِش کُس چُھہ گٔژھمُت۔ تہٕ ییلہ تِم گنزراونہٕ آو، وُچھ، جوناتھن تہٕ تٔمۍ سُند ہتھیار بردار {تتہِ} ٲسۍ نہٕ۔\n18.\\tتہٕ ساؤلن ووٚن احیاہس زِ خدایہ سُند صندوق اَنُن۔ تِکیازِ خدایہِ سُند صندوق اوس تمہِ وِزِ بنی اسرٲیلِس سٍتـ̡ ۔\n19.\\tتہٕ سپُد ساؤل پادٕرِس سٍتـ̡ کتھ کرنہٕ وِزِ یُس شور اوس فلسطینن ہٕندِس لشکرس مَنٛز یُس شور اوس، سُہ ہُریوو تہٕ ہُرراوُن تہٕ ساؤلن ووٚن پادٕرِس سٍتـ̡ پَنُن اَتھٕ پۯاوُن۔ {شور: یا، ہنگامہٕ}\n20. تہٕ ساؤل تہٕ أمِس سٍتـ̡ سٲری لُکھ جمع گٔیہ، تہٕ تِم آیہِ جنگس مَنٛز، تہٕ وُچھِتھ ٲس پرٮ۪تھ أکِس شخصہٕ سٕنز تلوار پننِس سٲتھیس خٕلاف، {تہٕ اَتھ سٍتـ̡ گٔیہِ سٮ۪ٹھاہ بٔڈ پریشانی۔ {جمع...: ہیب۔ اَکہٕ وَٹہٕ روُن}\n21.\\tامہِ علاوہ اوس عبرانیو تمہِ وقتہٕ برونہہ فلسطینن سٍتۍ، یُس تِمن سٍتـ̡ اندۍ پٔکھۍ خٲمس مَنٛز گٔیہِ، حتیٰ کہ تِم تہِ گٔیہِ تِمن اسرٲیلِین سٍتـ̡ یُس ساؤل تہٕ یوناتھن سٍتـ̡ ٲس۔\n22.\\tیِتھے پٲٹھـ̡ یِمو سارِوٕے اِسرٲیلِکۍ مرد یِمو افرائیم کِس پہاڑس مَنٛز ژوٗرِ ٲسمٕتۍ، یِمو بوز زِ فلسطینی ژٔلۍ، تِمو تہِ گٔیہِ جنگس مَنٛز تِمن پَتہٕ پَتہٕ۔\n23. یێلہِ خداوند بچٲو تمہِ دۅہہ اسرٲیل، تہٕ جنگ گۆو بیت ہیونس کُن۔\n24. تہٕ اَمہِ دۅہہ گٔیہِ اسرٲیلٕکۍ مرد پریشان، تکیازِ ساؤلن اوس لُکن ہُند بد دعا کورمُت، یُس شامس تام کھٮ۪وان چُھ، یُس میہ پننین دُشمنن ہُند انتقام ہُند بدلہٕ چُھ۔ لہذا چُھ نہٕ کٲنسہ تہِ لُکن کھٮ۪نُک مزہ چکھان۔\n25.\\tتہٕ سارِنٕے زمینہٕ آیہ أکِس جنگلس منز۔ تہٕ زمینس پیٹھ اوس ماچھ۔\n26.\\tتہٕ ییلہ لُکھ لُکھ لٔگِس منز وٲتِتھ، وُچھ ماچھ پیوٚو۔ مگر کٲنسہ تہِ نفرن تھوو نہ ٲسس پیٹھ اتھہ: تکیازِ لوٗکھ ٲسۍ قسمس کھوژان۔\n27.\\tمگر یوناتھنن بوز نہٕ ییلہ تٔمۍ سٕندِس مٲلہِ لُکن ہُند قَسم دِیُت، اَمہِ مۄکھٕ ترووُن أمِس لورِ ہُند اند یُس أمِس اتھس منز اوس، تہٕ کوٚرُن ماچھہِ ہٕندِس کۅکرس مَنٛز تہٕ تھووُن پننِس ٲسس پیٹھ اتھہٕ۔ تہٕ تٔمۍ سٕنٛزٕ أچھ ٲس روشن گٔمٕژ۔\n28.\\tاَمہِ پتہٕ دِیُت أکِس لُکن جواب تہٕ وونُن زِ تُہٕندِس مٲلہِ سٍتـ̡ دِیُت لُکن ہُند قَسم تہٕ وونُن زِ یُس اَز کھٮ۪ن کھٮ۪وان چُھ، سُہ چُھہ لعنت۔ تہٕ لوٗکھ ٲسۍ بے ہوش۔ {بے ہوش: یا، تھکاوٹ}\n29. اَمہِ پتہٕ ووٚن جوناتھن، میانہِ مٲلہِ چُھس زمینس پریشان کٔرمٕژ: وُچھ، بہٕ چھُس دُعا کران زِ میانہِ أچھ کِتھہ پٲٹھۍگٔیہِ روشن گٔمٕژ، کیازِ مے چُھس یَتھ ماچھہِ ہُند رژھ رژھ چکھ۔\n30.\\tاگر لوکو پننین دشمنن ہٕندِ لوُٹ لوُٹ یُس تمو لبنہٕ آمُت اوس، تِمن ہٕندِس غُنیمتس سٍتـ̡ کوتاہ کھیوٚن آسہِ۔ تکیازِ کیا وۅنۍ اوس نہٕ فلسطینن منز زیادٕ زیادٕ قتل سپدمُت؟\n31.\\tتہٕ تِمو دِژ تمہِ دۅہہ مِخماش پؠٹھٕ ایجالون تام فلسطینن ہٕندِس لُکن ہُند حملہٕ: تہٕ لُکھ گٔیہِ سٮ۪ٹھاہ بے ہوش۔\n32.\\tتہٕ لُکھ لُکھ غُنیمتس پیٹھ وٕڈِتھ تہٕ کٔرِکھ کۅکرِ تہٕ بَچھرٕ تہٕ کٔرِکھ زمینس پیٹھ۔\n33.\\tاَمہِ پَتہٕ ووٚن تِمو ساؤلَس زِ وُچھِو لُکھ خداوند سٍتـ̡ گۅناہ کران، یێلہِ تِم چِھ خوٗنہٕ سٍتـ̡ کھیوان۔ تہٕ تٔمۍ ووٚن، تہٕ ژےٚ چھِو گُزٲرمٕژ: از دۅہہ کٔرِو میانہِ خٲطرٕ اکھ بٔڈ کٔنہِ۔ {خلاف ورزی کٔرِتھ: یا، دھوکہ دہی سٍتۍ}\n34. تہٕ ساؤلن ووٚن، لُکن مَنٛز پھٔہلِو تہٕ تِمن وَنُن زِ پرٮ۪تھ أکِس انسانس أنِو پنُن دانٛد تہٕ پرٮ۪تھ أکِس انسانس سُند دانٛد، تہٕ یِمن مٲرِتھ کھیٛن۔ تہٕ خوٗنہٕ سٍتـ̡ کھٮ۪نہٕ سٍتـ̡ کٔرِو نہٕ خداوند سٕندِس خلاف گۅناہ۔ تہٕ سارِوٕے لُکھ أنۍ تَمہِ رٲژ پرٮ۪تھ أکِس نفرس سٍتـ̡ پنُن داند تہٕ مارُکھ تتہِ۔ {أمس سۭتۍ: ہیب۔ تٔمۍ سٕنٛدس اتھس منٛز}\n35. تہٕ ساؤلن بنوو خداوند سٕندِ خٲطرٕ اکھ قربان گاہ: یۅہے اوس گۅڈنیُک قربان گاہ یُس تٔمۍ خداوند سٕندِ خٲطرٕ بنوو۔ {یۅہے ...: ہیب۔ سُہ قربان گاہ یُس تٔمۍ خداوند سٕندِ خٲطرٕ تعمیر کرُن شروع کوٚر}\n36. تہٕ ساؤلن ووٚن زِ أسۍ گژھو رٲژ فلسطینن پتہٕ بۄن تہٕ صبحس تام یِم خراب کرٕن، تہٕ یِمو منزٕ گژھہِ نہٕ کانہہ نفر تراوُن۔ تہٕ تِمو ووٚن، یُس تہٕ تۅہہِ سٍتـ̡ خیر آسہِ۔ اَمہِ پتہٕ ووٚن پادٕرۍ زِ أسۍ یَتھ خدایہِ سٕندِس نزدیک۔\n37. تہٕ ساؤلن پرژھ خدایہِ سُند مشورٕ، کیا بہٕ گژھہٕ فلسطینن پتہٕ بۄن؟ کیا ژٕ کٔرِکھ تِم اسرٲیلِس اتھس مَنٛز؟ مگر تمۍ دیت نہ تمہِ دۅہہ تمس جواب۔\n38.\\tتہٕ ساؤلن ووٚن، یێلہِ نِش أنِو، سارِنٕے لُکن ہٕندِس سردارس، تہٕ وُچھِو تہٕ وُچھِو زِ یہ گۅناہ کُس گۆو از کُنہِ جایہ۔ {چیف: ہیب۔ کونر}\n39. یێلہِ زَن خداوند چُھہ زندٕ، یُس اسرٲیلِس بچاوان چُھ، یۆدوے سُہ میانہِ نیچوِس یوناتھن سٍتـ̡ آسہِ، سُہ گژھہِ یقینا مرُن۔ مگر {اَتھ} سارِنٕے لُکن مَنٛز اوس نہٕ کانٛہہ تہِ شخٕص {یٔمۍ أمِس جواب دِیُت}۔\n40. تمہ پتہ ووٚن تٔمۍ سارنٕے اسرٲیلِس سٍتـ̡ اَکہِ طرفہٕ تہٕ بہٕ تہٕ جوناتھن میون نیچو آسہٕ دۆیمہِ طرفہٕ۔ تہٕ لوکو ووٚن ساؤلس یُس تہِ کرُن یُس تۅہہِ خٲطرٕ اچھا باسیو۔\n41. تێمہِ کِنۍ ووٚن ساؤلن اسرٲیلِکِس خداہس سٍتـ̡ دِیُن کامل {لوٹ}۔ تہٕ ساؤل تہٕ یوناتھن آیہ نِنہٕ، مگر لُکھ ژٔلِتھ ژٔلِتھ۔ {دِیو...: یا، معصوم ہاو} {ژل: ہیب۔ برونٹھ کُن}\n42.\\tتہٕ ساؤلن ووٚن، میٲنس تہٕ جوناتھن میٲنس نیچوِس درمِیان تراوُن {لاٹ}۔ تہٕ جوناتھن آو نِنہٕ۔\n43.\\tپتہٕ ووٚن ساؤلن یوناتھنَس زِ ژے کیا چُھہ کورمُت۔ تہٕ جوناتھن ووٚن أمس تہٕ ووٚننس، میہ چُھ مگر لٔرِ ہٕندِس اندس سٍتۍ رژھ\n44.\\tتہٕ ساؤلن دیُت جواب، خدایہ کرِ یۅہے تہٕ زیادٕ تہِ: تکیازِ ژے گژھہِ یقینا مرُن، یوناتھن۔\n45.\\tتہٕ لوکو ووٚن ساؤلس زِ کیا یوناتھن مرُن، یُس اسرٲیلِس مَنٛز یہِ بٔڈ نجات دِژمُت چھُ؟ خدا نہ کرے: یێلہِ خداوند زندٕ آسہِ، تٔمۍ سٕندِس کلہٕ سُند اکھ تہِ مس گژھہِ نہٕ زمینس پیٹھ۔ تکیازِ تٔمۍ چُھ از خدایس سٍتـ̡ کٲم کٔرمٕژ۔ چنانچہ لوکو بچٲو جوناتھن زِ سُہ مٔر نہٕ۔\n46. پتہٕ ووت ساؤل فلسطینن ہٕندِ پتہٕ تہٕ فلسطینی گٔیہِ پننہِ جایہ۔\n47. یێمہِ کِنۍ لوٚگ ساؤلن اسرٲیلس پیٹھ بادشٲہی تہٕ لوٚڑُن پرٮ۪تھ طرفہٕ پننین سارنٕے دُشمنن سٍتـ̡ موآبس سٍتـ̡ تہٕ عمون سٕندِس اولادس خٕلاف، تہٕ ادومس خٕلاف تہٕ زوبہ کِس بادشاہن تہٕ فلسطینن سٍتـ̡ لوٚڑُن تہٕ یێتہِ تہِ پھیُر سُہ پانس سٍتـ̡ پریشان کٔرِتھ۔\n48.\\tتہٕ تٔمۍ کٔرٕن اکھ لشکر جمع تہٕ مارُن امالیکین تہٕ دِژُن اسرٲیلِس تِمو نِش یِمو تِمن ہٕندِس اتھہٕ نِش نِش نجات دِژٕ۔ {جمع کٔرِتھ...: یا، زورٕ سان کٔرِتھ}\n49. وۅنۍ اوس ساؤل سٕندِ نیچوۍ یوناتھن تہٕ ایشوئی تہٕ میلکیشوا: تہٕ تٔمۍ سٕنزن دۅن کورین ہٕندِ ناو ٲسۍ یِم}۔ گۅڈنچہ اولاد میراب سُند ناو، تہٕ لۄکٹۍ میکل سُند ناو:\n50.\\tتہٕ اوس ساؤل سٕنزِ زنانہِ ہُند ناو، یُس احیماز سٕنز کورِ ٲس، تہٕ تٔمۍ سٕندِس میزبان سُند ناو اوس نیر سُند نیچو، یُس ساؤل سٕندِس پیٚتٕر سُند نیچو اوس۔ {ابنر: ہیب۔ ابینر}\n51.\\tتہٕ کیش اوس ساؤل سُند مول۔ تہٕ نیر، ابنیر سُند مول اوس ابیل سُند نیچو۔\n52.\\tتہٕ ساؤل سٕندِس سارِنٕے دۅہہٕ اوس فلسطینن سٍتـ̡ جنگ۔","1. سموئیلَن ووٚن ساؤلس تہِ زِ خداوند چُھ مے سوزمُت زِ تۅہہ چُھہ پننین لوکن پیٹھ بادشاہ بننہٕ خٲطرٕ، اسرٲیلِس پیٹھ، تێمہِ مۅکھہٕ چُھہ تێہہ خداوند سٕندِ کلامٕچ آواز بوزان۔\n2. یِتھٕ پٲٹھـ̡ چُھہ لشکرن ہُند رب فرماوان، مے چُھہ یاد {یہ} یُس عمالیقن اسرٲیلِس سٍتـ̡ کورمُت، کِتھہ پٲٹھـ̡ اوس تٔمِس وتہِ مَنٛز {انتظار} کٔرِتھ، ییلہ سُہ مصرہٕ پیٹھٕ ہیوٚت۔\n3. وۅنۍ گژھ تہٕ امالیک مارُن، تہٕ یُس تہندِس نِش موجود چھُ، تہٕ یِمن نہٕ تراوُن۔ مگر مرد تہٕ زنانہٕ، شُرۍ تہٕ دۄدٕ بچہٕ، داند تہٕ کٹہٕ، اونٹ تہٕ گَرٕ مارٕ۔\n4. تہٕ ساؤلن کٔر لُکھ جمع تہٕ تِمن ہُند گنزرٲوِن تِلایمس منز، زٕ لچھ ساس پیدل تہٕ یہوداہٕکۍ داہ ساس نفر۔\n5.\\tتہٕ ساؤل آو عمالیق کِس شہرس مَنٛز، تہٕ کوٚرُن وادی مَنٛز پیار۔ {لیڈ...: یا، لڑا}\n6. تہٕ ساؤلن ووٚن کینِیَن نِش نیرِو، تہٕ امالیقین منزٕ نِش بۄن نِو، نتہٕ بہٕ تہٕ بہٕ تِمن سٍتـ̡ تباہ کٔرِتھ، تکیازِ یێلہِ تِم مصرہٕ منزٕ دِنہٕ یِنہٕ وِزِ تِم سارِنٕے بنی اِسرٲیلِس سٍتـ̡ مہربانی کٔرٕنـ̡ ۔ چنانچہ کنیتن دراو امالیکین منز۔\n7.\\tتہٕ ساؤلن دِژ حویلہ پیٹھٕ عمالیقین ہُند حملہٕ، یُس تہٕ مصرس خلاف یُس {چُھ}۔\n8.\\tتہٕ تٔمۍ نیو امالیکین ہُند بادشاہ آگاگ زِندٕ تہٕ تلوار ہٕندِ دھار سٍتۍ کوٚرُن سارِنٕے لُکھ تباہ ۔\n9.\\tمگر ساؤل تہٕ لُکن بچٲو آگاگ، تہٕ کۅکرِ تہٕ بیلن تہٕ کۅکرِ تہٕ کۅکرِ تہٕ سارِنٕے نیکی تہٕ یِمن سارِنٕے نیکی سٍتـ̡ بچٲوِتھ تہٕ یِم کٔرٕن نہٕ پوٗرٕ پٲٹھـ̡ تباہ کرنہٕ۔ {fatlings: یا، دۆیم قسم}\n10.\\tپتہٕ آو خداوند سُند کلام سموئیلس نِش وونُن،\n11.\\tیہ چُھہ میہ توبہ کران زِ میہ چُھہ ساؤل بادشاہ مقرر کورمُت، تکیازِ سُہ چُھس میانہِ پیروی کرنہٕ نِش پتھ کُن آمُت، تہٕ کورُن نہٕ میٲنۍ حُکمن پورٕ۔ تہٕ یہ اوس سیموئیلس غم۔ تہٕ سُہ اوس سارِوٕے رٲژ خداوند سٕندِس نِش فریاد دِوان۔\n12.\\tتہٕ ییلہ سموئیل صبحٲے ساؤلس سمکھنہٕ خٲطرٕ ووٚتھ، سموئیلس وونُن زِ ساؤل آو کارملس نِش تہٕ وُچھِتھ ووت أمِس اکھ جاے، تہٕ گٔیہِ گُرِ تہٕ گٔیہِ گلگلس کُن۔\n13. تہٕ سموئیل آو ساؤلس نِش۔ تہٕ ساؤلن ووٚن أمِس زِ خداوند سُند مُبارکَت چھُ: مے چُھہ خداوند سُند حُکُم پوٗرٕ کٔرِمُت۔\n14.\\tتہٕ سموئیلَن ووٚن، تیٚلہِ کیا چُھہ میانین کنن مَنٛز کۅکرِ ہُند بُل تہٕ بیلن ہُند یُس بہٕ بوزان چُھس؟\n15.\\tتہٕ ساؤلن ووٚن، تِمو چھِ یِم امالیکیَو نِش أنِمٕتۍ، تِکیازِ لُکہٕ بچٲوِکھ بہتٔریٖن کۅکرِ تہٕ بیلن ہٕندِس خداہس سٍتـ̡ قربان کرنہٕ مۅکھہٕ۔ تہٕ باقٕے أسۍ چھِ پوٗرٕ پٲٹھۍ تباہ کٔرۍمٕتۍ۔\n16.\\tتێلہِ ووٚن سموئیلَن ساؤلَس زِ رُکُن روزُن، تہٕ بہٕ وَنُن ژے یُس خداوند از رٲژ مےٚ ووٚنمُت۔ تہٕ تٔمۍ ووٚن أمِس وَنُن۔\n17.\\tتہٕ سموئیلن ووٚن، یێلہِ ژے پننِس نظرس منز کم کُنہِ سٍتـ̡ بنیوو نہٕ اسرٲیلٕکۍ قبیلن ہُند سردار، تہٕ خداوند بنوو ژے اسرٲیلِس پیٹھ بادشاہ؟\n18.\\tتہٕ خداوند سوٗز ژے سفرس پیٹھ تہٕ وونُن، گژھ تہٕ گۅنہگارن ہُند مکمل طور تباہ کرُن، تہٕ تِمن خلاف لڑاو یوٚت تام تِم ختم گژھن۔ {تِم...: ہیب۔ تِم چھِ تِم کھٮ۪وان}\n19. تێلہِ کیازِ کٔر نہٕ ژے خداوند سٕنزِ آوازِ ہٕنز فرمانبرداری، بلکہ کٔرٕکھ غنیمتس پیٹھ وُڑن، تہٕ کٔرٕکھ خداوند سٕندِس نظرس منز بُر؟\n20. تہٕ ساؤلن ووٚن سموئیلس زِ آ، بہٕ چُھس خداوند سٕنزِ آوازِ ہٕنز فرمانبرداری کٔرمٕژ، تہٕ چُھس تتھۍ وتہِ پٔکِتھ یُس خداوند مے سوزمُت اوس، تہٕ چُھس عمالیقُک بادشاہ آگاگ أنِمُت، تہٕ چُھکھ امالیقی پوٗرٕ پٲٹھـ̡ تباہ کٔرِمُت۔\n21.\\tمگر لُکو نِش غنیمت، کۅکرِ تہٕ بیل، یُس تِمن چیزن ہُند سردار یُس پوٗرٕ پٲٹھـ̡ تباہ گژھن گژھہِ ہا، گلگلس مَنٛز خداوند سٕندِ خٲطرٕ پنُن خدایہ قربان کرنہٕ خٲطرٕ۔\n22. تہٕ سموئیلَن ووٚن، کیا خداوند چُھ زالنہٕ نذرانہٕ تہٕ قربانین سٍتـ̡ خوش گومُت، یێلہِ چُھہ خداوند سٕنزِ آوازِ ہٕنزِ فرمانبرداری سٍتـ̡ خوش سپدان؟ وچھو، اطاعت کرُن چھہ قربانی کھۅتہ بہتر، تہ بوزُن چھہ رۅپھ کھۅتہ بہتر۔\n23.\\tبغاوت چھہ جادوگری ہند گۅناہ تہ ضد تہ ضد چھہ بدکاری تہ بت پرستی۔ تِکیازِ ژے چُھہ خداوند سٕندِس کلامَس رد کورمُت، تٔمۍ تہِ چُھ ژےٚ بادشاہ بننہٕ نِش تہِ رد کورمُت۔ {جادوگر: ہیب۔ divination}\n24. تہٕ ساؤلن ووٚن سموئیلس زِ میہ چُھ گۅناہ کورمُت، کیازِ میہ چُھ خداوند سٕندِس حکمس تہٕ تُہندِ کلامٕچ خلاف ورزی کٔرمٕژ، کیازِ بہٕ اوسُس لُکن ہُند خوف تہٕ تِہٕنزِ آوازِ ہٕنز فرمانبردار۔\n25. تێمہِ کِنۍ چُھس بہٕ ژے دُعا کران، میون گۅناہ معاف، تہٕ دُبارٕ پانس سٍتـ̡ پھیرُن، یُتھ بہٕ ہێکہٕ خداوند سٕنز عبادت کٔرِتھ۔\n26. تہٕ سموئیلَن ووٚن ساؤلَس زِ بہٕ چُھس نہٕ ژے سٍتـ̡ واپس یِوان، تِکیازِ ژے چُھہ خداوند سُند کلام رد کورمُت، تہٕ خداوند چُھہ ژے اسرٲیلُک بادشاہ بننہٕ نِش انکار کورمُت۔\n27.\\tتہٕ ییلہ سموئیل نیرنہٕ خٲطرٕ پھیُر، تٔمۍ لوٚگ پننہِ پوشہِ ہٕندِس دٔرِس تھپھ تہٕ سُہ پھٔٹِتھ پھٔٹِتھ۔\n28.\\tتہٕ سموئیلن ووٚن أمِس زِ خداوند چُھ از ژے نِش اسرٲیلٕچ بادشٲہی ژٔٹمٕژ، تہٕ دِژُن تۅہہِ سٕندِس أکِس ہمسایہ سٍتـ̡ یُس ژے کھوتہٕ بہتر چُھ۔\n29. تہٕ اسرٲیلٕچ طاقت تہِ کرِ نہٕ اپُز تہٕ نہ توبہٕ، کیازِ سُہ چُھ نہٕ انسان تہٕ توبہ کرُن۔ {طاقت: یا، ابدیت، یا، فتح}\n30. تێمہِ وۆن میہ گۅنہگار گومُت: وُنہِ تہِ کرُن میہ احترام، بہٕ چُھس پننین لوکن ہٕندِس بزرگن برونہہ کُن تہٕ اسرٲیلِس برونہہ کُن دُعا کران تہٕ دُبارٕ پھیرُن یُس بہٕ ہێکہٕ پننہِ خدایہِ سٕنز عبادت کٔرِتھ۔\n31. تہٕ سموئیل پھیُر ساؤلس پتہٕ دُبارٕ۔ تہٕ ساؤل کٔر خداوند سٕنز پوجا کرنہٕ۔\n32.\\tاَمہِ پتہٕ ووٚن سموئیلَن زِ اَمالیکَن ہُند بادشاہ اَغگ اَنِن میانہِ نِش۔ تہٕ آگگ آو أمِس نِش نازک پٲٹھۍ۔ تہٕ آگگن ووٚن، یقینا موتچ تلخی چھیہ پتھ کال۔\n33. تہٕ سموئیلَن ووٚن، یِتھٕ پٲٹھۍ چُھہ چانہِ تلوار زنانن بےٚ اولاد بنٲومٕژ، تِتھے پٲٹھۍ گژھہِ تہنز موج زنانن منز بے اولاد روزِ۔ تہٕ سموئیلَن کٔر گلگلَس مَنٛز خداوند سٕندِ برونہہ کُن آگاگ ٹُکرٕ ٹُکرٕ کٔرِتھ۔\n34. پتہٕ گوٚو سموئیل راماہس کُن۔ تہٕ ساؤل ووت ساؤل سٕندِس گِبعاہس نِش پننِس گَرَس تام۔\n35.\\tتہٕ سموئیل آو نہٕ ساؤلس مرنہٕ کس دۅہس تام ساؤلس وچھنہٕ خٲطرٕ، توتہِ کوٚر سموئیلن ساؤلس خٲطرٕ ماتم تہٕ خداوند کٔر توبہ زِ تٔمۍ بنوو ساؤل اسرٲیلُک بادشاہ۔","1. تہٕ خداوند ووٚن سموئیلس زِ ژے کوتاہ کالس روزٕ ساؤل سٕندِ خٲطرٕ ماتم کٔرِتھ، یێلہِ چُھہ مے أمِس اسرٲیلِس پیٹھ بادشاہی کرنہٕ نِش انکار کورمُت؟ پَنُن سینگ بٔرِتھ تیٖلہٕ سٍتـ̡ تہٕ گژھ بہٕ ژے یسی بیت اللحمس نِش سوزمُت، تکیازِ مے چُھس تٔمۍ سٕندٮ۪ن نیچوین مَنٛز اکھ بادشاہ فراہم کورمُت۔\n2. تہٕ سیموئیلَن ووٚن، بہٕ کِتھ کٔنۍ گژھِتھ؟ اگر ساؤل بوزِ، سُہ کرِ میہ مٲرِتھ۔ تہٕ خداوند ووٚن پانس سٍتـ̡ اکھ گاو تہٕ ونُن، بہٕ چُھس خداوند سٕندِ خٲطرٕ قربانی دِنہِ آمُت۔ {توے سٍتۍ: ہیب۔ تۅہہِ اتھس منز}\n3.\\tتہٕ یسی سٕندِ قربانی خٲطرٕ بُلوو، تہٕ بہٕ ہاوٕ ژے کیا کرُن، تہٕ ژے کرٕ میہ خٲطرٕ مسح کرنہٕ یُس بہٕ ژے ناو دِوان چھُس۔\n4. تہٕ سموئیلَن کٔر سُہ یُس خداوند کٔر تہٕ آو بیت اللحمس مَنٛز۔ تہٕ شہرٕکۍ زِٹھۍ ٲسۍ أمۍ سٕنٛدِ یِنہٕ وِزِ تھرتھر تہٕ وونُن، ژٕ چھوا امن سان یِوان؟ {یِوان: ہیب۔ میٹنگ}\n5. تہٕ ووٚن، امن پٲٹھۍ: بہٕ چُھس خداوند سٕندِ خٲطرٕ قربانی کرنہٕ خٲطرٕ آمُت، پان پاک کرُن، تہٕ گژھو مےٚ سٍتـ̡ قربانیس مَنٛز۔ تہٕ تٔمۍ کٔر یسی تہٕ تٔمۍ سٕنٛدٮ۪ن نیٚچوٮ۪ن پاکیز، تہٕ بُلووُن تِم قۄربٲنی خٲطرٕ۔\n6.\\tتہٕ ییلہ تِم آیہ، تٔمۍ وُچھِتھ الیابس کُن نظر تہٕ وونُن، یٔقیٖنی طور خداوند سُند مسح کرنہٕ آمُت چُھہ أمِس برونہہ کُن۔ {الیاب: وَننہٕ آمُت ایلیہو}\n7. مگر خداوند ووٚن سموئیلس زِ تٔمۍ سٕندِس بُتھِس پیٹھ تہٕ تٔمۍ سٕندِس قدس کُن وُچھُن نہٕ۔ تکیازِ میہ چھہ تس انکار کورمُت: کیازِ {خداوند وچھان} چھہ نہ انسان وچھان۔ تکیازِ انسان چُھ ظاہری شکلہٕ وچھان، مگر خداوند چُھ دلس پیٹھ نظر۔ {نیبرِم...: ہیب۔ اچھ}\n8.\\tاَمہ پتہٕ بُلوو یسیَن ابیناداب تہٕ دِتُن سموئیلس برونہہ کُن نیرُن۔ تہٕ تٔمۍ ووٚن، نۂ خداوند چُھ یہِ ژٲرمُت۔\n9.\\tتمہِ پتہ کٔر یسی شمعہ نیبر نیرُن۔ تہٕ تٔمۍ ووٚن، نۂ خداوند چُھ یہِ ژٲرمُت۔ {شمعہ: شمیع، یتھ شمہ تہِ ونان چھِ}\n10.\\tبییہِ کٔر جیسن پننین ستھ نیچوۍ سیموئیلس برونہہ کُن نیران۔ تہٕ سموئیلَن ووٚن یسیَس زِ خداوند چُھ نہٕ یِم ژارنہٕ آمٕتۍ۔\n11.\\tتہٕ سموئیلن ووٚن یسیس زِ کیا یتہِ چھِہ تہند سارِنٕے شُرۍ؟ تہٕ تٔمۍ ووٚن، وُنہِ تہِ چُھ سارِوٕے کھۄتہٕ لۄکٕٹ باقٕے تہٕ وُچھِتھ چُھ سُہ کۅکرِ رچھان۔ تہٕ سموئیلَن ووٚن جیسَس زِ سُہ سوز تہٕ أنِو، تِکیازِ أسۍ بِہتھ نہٕ توٚت تام نہٕ سُہ یور یِنہٕ۔ {ڈاون: ہیب۔ راؤنڈ}\n12. تہٕ تٔمۍ سوٗز، تہٕ أنِن سُہ اندر۔ وۅنۍ اوس سُہ سُہ سرخ ، {تہٕ} خوبصورت بُتھِس سٍتۍ تہٕ وُچھُن خۅش ۔ تہٕ خداوند ووٚن، وُچھِو أمِس مسح کٔرِتھ، یێمہِ سٍتـ̡ چُھہ یہِ۔ {of a...: Heb. أچھن ہُند فیئر }\n13. تێمہِ پَتہٕ رٔٹ سموئیلَن تیٖلُک سینگ تہٕ کوٚرُن پننین باین ہٕندِس درمِیان مسح تہٕ خداوند سُند روح آو اَمہِ دۅہہٕ پیٹھٕ داؤدس پیٹھ۔ تہٕ سموئیل ووٚتھ تہٕ گوٚو رامہ کُن۔\n14. مگر خداوند سُند روح ژاو ساؤلس نِش، تہٕ خداوند سٕندِ طرفہٕ کٔر أمِس بد روح۔ {پریشان: یا، خوفزد}\n15.\\tتہٕ ساؤل سٕندِس خادمَو ووٚن أمِس زِ وُچھِو، خدایہِ سُند اکھ بد روح چُھہ تۅہہِ پریشان کران۔\n16.\\tسٲنـ̡ رب دِیُن وۅنۍ پننین خدمتگارن {یُس} تۅہہِ برونہہ کنہِ چُھہ، تِم کٔرِن أکِس شخٕص ژھانڈنُک حُکُم، یُس ہارپَس پیٹھ اکھ چالاک کھلٲوِن آسہِ، تہٕ یێلہِ گژھہِ خدایہِ سُند بد روح تہٕ سُہ گِندُن پننِس اتھہٕ سٍتـ̡ گِندُن، تہٕ تُہہِ روزِ ٹھیٖک۔\n17.\\tتہٕ ساؤلن ووٚن پننین خدمتگارن زِ وۅنۍ دِیُن میہ اکھ انسان یُس اصل گِندِتھ تہٕ اَنِن میہ نِش۔\n18.\\tاَمہِ پتہٕ دِژ أکِس خادمَن جواب تہٕ وونُن، وُچھمُت یژھ بیت اللحمی سُند اکھ نیچو، یُس گِندنس مَنٛز چالاک چُھ، تہٕ اکھ طاقتور بہادر انسان، تہٕ جنگی شخص، معاملاتن مَنٛز ہوشیار تہٕ اکھ خوبصورت شخص، تہٕ خداوند چُھ أمِس سٍتـ̡ آسان۔ {معاملہٕ: یا، تقریر}\n19.\\tتێلہِ سوٗزۍ ساؤلن یژھس نِش قاصد تہٕ وونُن، پَنُن نیچو داؤد سوزُن، یُس کۅکرِ سٍتـ̡ چُھ۔\n20.\\tتہٕ یژھن نِش اکھ گَرٕ تہٕ شرابٕچ بوتلہٕ تہٕ اکھ شُر، تہٕ سوٗزُن داؤد سٕندِ نیچوِس ساؤلس نِش۔\n21. تہٕ داؤد آو ساؤلس نِش تہٕ کھڑا أمِس برونہہ کُن، تہٕ سُہ اوس أمِس سٮ۪ٹھاہ محبت کران۔ تہٕ سُہ بنیوو أمۍ سُنٛد ہتھیار بردار۔\n22. تہٕ ساؤل سوز یسیٰ نِش یہِ ونُن زِ داؤد، بہٕ چُھس ژےٚ دُعا کٔرِتھ میانہِ برونہہ کُن کھڑا روزُن۔ تکیازِ تس چھہ میانہِ نظرِ منز عنایت میلان۔\n23.\\tتہٕ سپُد یێلہِ خدایہِ سُند {بد روح} ساؤلس پیٹھ آو، داؤد تُل ہارپ تہٕ گِندُن پننِس اتھہٕ سٍتـ̡ گِندُن، یێلہِ ساؤل تازٕ گوو، تہٕ بد روح گۆو أمِس نِش۔","1. وۅنۍ کٔر فلسطینیو پنٕنۍ فوج جنگہٕ خٲطرٕ جمع تہٕ گٔیہٕ شوخوہس مَنٛز جمع یُس یہوداہ سٍتـ̡ چُھ، تہٕ آیٔے شوخوہس تہٕ عزیقاہَس درمیان افسدمیمس مَنٛز جمع کرنہٕ۔ {ایفسڈیمیم: یا، دمیمُک ساحل، یتھ پسدمیم ونان چھِ}\n2. تہٕ ساؤل تہٕ اسرٲیلٕکۍ مرد گٔیہِ اِکہٕ وٹہٕ جمع تہٕ وادی ایلاہَس نِش لٔگِتھ تہٕ کوٚرُکھ فلسطینن خلاف جنگ۔ {سیٹ...: ہیب۔ جنگہٕ کٔرِتھ کٔرِو}\n3.\\tتہٕ فلسطینی ٲسۍ اکہِ طرفہٕ أکِس پہاڑس پیٹھ کھڑا تہٕ دوٚیمہِ طرفہٕ اوس اسرائیل أکِس پہاڑس پیٹھ کھڑا۔ تہٕ یِمن درمیان ٲس اکھ وادی۔\n4.\\tتہٕ درٛاو فلسطینن ہٕندِ خٲمہٕ منزٕ اکھ چیمپئن یُس گاتھُک جالوت ناو اوس، یٔمِس تھزر شیہ کیوبِٹ تہٕ اکھ طول اوس۔\n5. تہٕ تٔمِس اوس کلس پیٹھ پیتلُک اکھ ہیلمٹ تہٕ سُہ اوس ڈاک کوٹ ہیتھ لیس ۔ تہٕ کوٹُک وزن اوس پانژھ ساس شیکل پیتل۔ {ہتھیار بند: ہیب۔ پلو لٲگِتھ}\n6.\\tتہٕ تٔمِس ٲس زنگن پیٹھ پیتلُک گریو، تہٕ پھیکس درمیان پیتلُک نشانہٕ۔ {ٹارگٹ: یا، گورجٹ}\n7.\\tتہٕ تٔمۍ سٕندِ نیزُک لوٚر اوس وُننہٕ والہِ ہٕندِس بیمہٕ ہٕندۍ پٲٹھۍ۔ تہٕ أمۍ سٕنٛدِ نیزٕ سُنٛد کلہٕ اوس شیٚہ ہتھ شیکل، تہٕ اکھ ڈھال ہیتھ أمِس برٛونٛہہ کُن۔\n8. تہٕ سُہ ووٚتھ تہٕ ووٚتھ اسرٲیلِکۍ لشکر تہٕ تِمن وونُن، تہٕ تِمن وونُن، تہٕ کیازِ چھِو پَنُن جنگ صفہٕ بندی کرنہٕ خٲطرٕ نیران؟ بہٕ چُھس نہٕ فلسطینی، تہٕ تم چُھہ ساؤل سٕندِ خادم؟ ژیہ ژیہ پننہِ خٲطرٕ اکھ مرد ژارن، تہٕ سُہ گژھہِ میانہِ نِش بۄن۔\n9. اگر سُہ میانہِ سٍتـ̡ لڑنس لایق آسہِ، تہٕ مے مارنہٕ خٲطرٕ، تیلہِ بٔنِو أسـ̡ تُہٕندِس خادم۔\n10.\\tتہٕ فلسطینن ووٚن زِ بہٕ چُھس از دۅہہ اسرٲیلِچ فوجن ہٕنز مخالفت کران۔ میہ دِیو اکھ نفر، تاکہ أسۍ ہیکو اکوٹہ لڑتھ۔\n11. ییلہِ ساؤل تہٕ سارِنٕے اسرٲیلِیو فلسطینی سٕندِ یِم کلام بوٗز، تِم گٔیہِ خوفزدہ تہٕ سٮ۪ٹھاہ خوف۔\n12.\\tوُن اوس داؤد بیت اللحمجودہ کِس افراتی سُند نیچو، یٔمۍ سُند ناو {اوس} یسی۔ تہٕ أمِس ٲسۍ ٲٹھ نیچوۍ: تہٕ یہِ نفر اوس ساؤل سٕندِس زمانس مَنٛز أکِس بُزرگ سٕندِس انسانس مَنٛز گٔژھان۔\n13.\\tتہٕ یسیٰ سٕندِ تریہ بٔڈۍ نیچوۍ گٔیہِ ساؤلس پتہٕ جنگس کُن، تہٕ تٔمۍ سٕندٮ۪ن ترٮ۪ن نیچوین ہُند ناو یِم جنگس منز گٔیہِ، تہٕ تٔمِس پتہٕ اوس ابینادب تہٕ تریم شمعہ۔\n14.\\tتہٕ داؤد اوس سارِوٕے کھۄتہٕ لۄکُٹ، تہٕ تریہ بٔڈۍ ساؤل سٕندِ پتہٕ۔\n15. مگر داؤد گوٚو ساؤلس نِش واپس پننِس مٲلہِ سٕندِس دانٛدس کھیٚنہٕ خٲطرٕ۔\n16.\\tتہٕ فلسطینی آو صبحس تہٕ شامس نزدیک تہٕ ژتٲجی دۅہن پانس پیش۔\n17. تہٕ یژھین ووٚن پننِس نیچوِس ڈیوڈس زِ وۅنۍ نِیو پننین باین ہٕندِ خٲطرٕ امہِ خشک {مکایہ} ہُند اکھ ایفا، تہٕ یِم داہ روٹۍ، تہٕ ژٔلِو پننین باین نِش خٲمس کُن۔\n18.\\tتہٕ یِم داہ چیز نِیُن ساس ساس کِس کپتانس نِش، تہٕ وُچھِو تُہند بٲے کِتھہ پٲٹھۍ، تہٕ تِمن ہُند وعدٕ کٔرِتھ۔ {چیز: ہیب۔ دۄدُک چیز} {of...: Heb. اکھ ساس}\n19.\\tوۅنۍ اوس ساؤل، تہٕ تِم تہٕ سارِنٕے اسرٲیلِکۍ مرد ٲسۍ وادی ایلاہس مَنٛز، فلسطینن سٍتـ̡ لڑان۔\n20. تہٕ داؤد ووٚتھ صُبحس سُلہِ تہٕ ترٛٲوُن کَٹھ أکِس رٲچھ وٲلِس نِش، تہٕ نِیُن تہٕ گٔیہِ، یَتھ کٔنۍ یَس أمِس حُکُم اوس کوٚرمُت۔ تہٕ سُہ آو خندقس پیٹھ، ییٚلہ میزبان اوس لڑایہِ خٲطرٕ نیران، تہٕ کٔرٕن جنگہٕ خٲطرٕ کرٛٮ۪کھ۔ {خندق: یا، گاڈِ ہنز جاے} {لڑائی: یا، جنگی صف، یا، لڑائیچ جاے}\n21.\\tاِسرٲیلِس تہٕ فلسطینیو اوس لشکرس خلاف جنگہٕ ترتیب دِژمُت۔\n22.\\tتہٕ داؤد تروو پنٕنۍ گاڑِ گاڈِ وٲلِس اتھس منٛز، تہٕ ژوٚل فوجس مَنٛز، تہٕ آو تہٕ کوٚرُن پننٮ۪ن باین سلام۔ {تٔمۍ سٕنز گاڑی: ہیب۔ تٔمۍ سٕندِ برتن ہٕندِس برتن ہٕندِس سٍتـ̡ {سلام...: Heb. تٔمۍ سٕندٮ۪ن بٲے امن ہٕندِس بٲے پرژھس}\n23.\\tتہٕ یێلہِ تِمن سٍتـ̡ کتھ کٔرِتھ، وُچھِتھ آو فلسطینن ہٕندِس لشکرس منزٕ یێلہِ سٍتـ̡ فاتح، گاتھُک فلسطین، تہٕ داؤد کٔر تِمن سٍتـ̡ کتھ کرنہٕ۔\n24.\\tتہٕ سارِوٕے اِسرٲیلٕکۍ مرد ییلہ أمِس نفرس وُچھِ، ژٔلِتھ ژٔلِتھ تہٕ گٔیہِ خوفہٕ۔ {پیٹھ...: ہیب۔ تٔمۍ سٕنٛدِ بُتھِس پیٹھ}\n25.\\tتہٕ اسرٲیلِیو ووٚن، کیا ژیہ وُچھمُت یہِ شخٕص یُس وُچھمُت چُھ؟ یقینا چُھ سُہ اسرٲیلِچ مخالفت کرنہٕ خٲطرٕ یُس أمِس مارِ، سُہ کرِ أمِس سٮ۪ٹھاہ دولت، تہٕ دِیہِ أمِس پنٕنۍ کور، تہٕ کرِ پننِس مٲلہِ سُند گرٕ اسرٲیلس مَنٛز آزاد۔\n26.\\tتہٕ داؤد ووٚن تِمن نفرن سٍتـ̡ یُس أمِس فلسطینی سٍتـ̡ قتل کرِ، تہٕ اسرٲیلِس نِش ملامت نِنہٕ وٲلِس سٍتـ̡ کیا گژھہِ کرنہٕ۔ تکیازِ یہِ کُس چھُ نہٕ ختنہ کرنہٕ آمُت فلسطینی، یُس زندٕ خدایہ سٕندِس لشکرس خلاف ورزی کرُن؟\n27.\\tتہٕ لوکو دیُت أمِس یِتھٕ پٲٹھـ̡ جواب دِتھ وونُن، یُس أمِس مارِتھ تہٕ یُس أمِس مارِ۔\n28.\\tتہٕ تٔمۍ سٕندِس بٔڈِس بٲے الیابس بوز ییلہ تٔمۍ مردن سٍتـ̡ کتھ کٔر۔ تہٕ الیابس سُند غصہٕ گۆو داؤدس سٍتـ̡ تہٕ تٔمۍ ووٚن، ژیہ کیازِ آو یور تہِ؟ تہٕ ژے کٔمِس نِش ترٲوۍ تِم کینہہ کۅکرِ بیابانس منز؟ بہٕ چھُس چانۍ غرور تہٕ چانہِ دِلٕچ شرارت زانان۔ تِکیازِ تُہۍ چھِو بۄن آمُت یُتھ زِ ژے ہیٛکہٕ جنگ وُچھِتھ۔\n29. تہٕ داؤد ووٚن، مے کیا چُھ وُن؟ {کیا چھُنہ} کانہہ وجہ؟\n30.\\tتہٕ سُہ پھیُر أمِس نِش بییِس کُن، تہٕ یِتھۍ پٲٹھۍ کٔرٕن أمِس جواب۔ {طریقہٕ: ہیب۔ لفظ}\n31.\\tتہٕ یێلہِ سُہ لفظ بوزنہٕ آمُت یُس داؤد کٔر تِمو ساؤلس برونہہ کُن پرناوُن، تہٕ تٔمۍ سوٗزُن أمِس بُنـ̡ ۔ {سوزمُت...: ہیب۔ نِیوو سُہ\n32. تہٕ داؤد ووٚن ساؤلس زِ کٲنسہ تہِ انسان سُند دِل گژھہِ نہٕ أمِس سٍتـ̡ ناکام سپدُن۔ تُہند خادم گژھِ أمِس فلسطینس سٍتـ̡ لڑان۔\n33. تہٕ ساؤلن ووٚن داؤڈس زِ تہٕ تُہۍ ہیوٚک نہٕ أمِس فلسطینس خلاف لڑنہٕ خٲطرٕ گژھِتھ، تِکیازِ تُہۍ چھُکھ نوجوان، تہٕ سُہ چُھہ جوانی پیٹھے جنگ۔\n34.\\tتہٕ داؤدن ووٚن ساؤلس زِ چانہِ خادمَن تھوو پننِس مٲلہِ سٕندِ کۅکرٕ تہٕ اَکھ سٕہہ تہٕ اکھ ریچھ تہٕ تُل کٔرِتھ تہٕ کٔرِتھ تہٕ کٔرِتھ\n35.\\tتہٕ بہٕ دراو أمِس پَتہٕ تہٕ دِژُن أمِس تھپھ تہٕ دِژُن أمِس ٲسِس منزٕ دِنہٕ، تہٕ ییلہ سُہ میٲنِس خلاف ووٚتھ، مے رٔٹِتھ أمِس داڑھ تھپھ کٔرِتھ مارُن۔\n36.\\tچانہِ خادمَن مٲرِتھ شیر تہٕ ریچھ دۅشوے تہٕ یہِ ختنہٕ نہٕ فلسطینی آسہِ یِمو منزٕ اَکھ ہیوٗ یُس زندٕ خدایہ سٕندِس لشکرس خلاف ورزی کٔرِتھ۔\n37.\\tداؤد ووٚن بییہِ زِ خداوند یُس میہ شیر سٕندِ پنجہٕ منزٕ تہٕ ریچھ سٕندِ پنجہٕ نِش نجات دِیُت، سُہ کرِ مے أمِس فلسطینی سٕندِ اتھہٕ نِش نِش۔ تہٕ ساؤلن ووٚن داوڈس زِ گژھ تہٕ خداوند گژھہِ توے سٍتۍ۔\n38.\\tتہٕ ساؤلن لوٚگ داؤدس پنہٕ نِس ہتھیار سٍتـ̡ تہٕ تٔمۍ تھوو پننِس کلس پیٹھ پیتلُک ہیلم۔ امہ علاوٕ کوٚر تٔمۍ أمِس میلُک کوٹ ہیتھ ہتھیار ۔ {مسلح ڈیوڈ...: ہیب۔ ڈیوڈس پلو لٲگتھ\n39.\\tتہٕ داؤد کٔر تلوار پننِس ہتھیارس پیٹھ، تہٕ تٔمۍ کٔر نیرُن۔ تکیازِ تٔمۍ اوس نہٕ ثٲبت کورمُت۔ تہٕ داؤدَن ووٚن ساؤلَس زِ بہٕ ہیوٚک نہٕ یِمن سٍتـ̡ گژھِتھ۔ تکیازِ مے کوٚر نہٕ ثٲبت {تِم}۔ تہٕ ڈیوڈن ترٛٲوۍ تِم أمِس نِش۔\n40.\\tتہٕ تٔمۍ رٔٹِن پنٕنۍ لٔر اتھس منٛز، تہٕ تٔمِس ژٔٹِن نالہٕ منٛزٕ پانژھ ہموار کٔنہِ، تہٕ تھووُن أکِس گٔرِ سٕنٛدِس بیگس منٛز یُس أمِس أکِس کھورِ منٛز تہِ اوس۔ تہٕ تٔمۍ سُند غلیل اوس اتھس منٛز: تہٕ سُہ ووت فلسطینس نزدیک۔ {بروک: یا، وادی} {بیگ: ہیب۔ جہاز}\n41. تہٕ فلسطینی آو تہٕ ووت داؤدس نزدیک۔ تہٕ سُہ شخص یُس ڈھال ننگا اوس أمس برونہہ کُن۔\n42. تہٕ ییلہ فلسطینن اندۍ پکھۍ نظر تہٕ داؤد وُچھ، تٔمۍ کٔر أمِس حقارت کٔرِتھ، تکیازِ سُہ اوس نوجوان، تہٕ سُہ اوس اکھ جوان تہٕ خوبصورت شکلہٕ۔\n43. تہٕ فلسطینن ووٚن داؤدس زِ بہٕ چُھس ہوُن، تہٕ ژٕ چُھکھ لٔڑۍ ہٮ۪تھ میانہِ نِش یِوان؟ تہٕ فلسطینن کٔر داؤدس پننیو دیوتاہن سٍتـ̡ لعنت۔\n44. تہٕ فلسطینن ووٚن داوڈس زِ میانہِ نِش آو تہٕ بہٕ دِیہٕ پنُن ماز ہوہٕکۍ جاناوارن تہٕ کھہہٕ کین درندن دِنہٕ۔\n45.\\tتێلہِ ووٚن داؤد فلسطینس سٍتـ̡ تہٕ ژے چُھہ تلوار تہٕ نیزٕ ہیتھ تہٕ ڈھال ہیتھ میانہِ نِش آمُت، مگر بہٕ چُھس ژے نِش لشکرن ہٕندِ رب سٕندِ ناوٕ سٍتـ̡ آمُت، یُس اسرٲیلـ̡ فوجن ہُند خدا، یُس ژے نافرمانی کٔرمٕژ چُھ۔\n46. اَمہِ دۅہہٕ کَرِ خداوند ژےٚ میٲنِس اتھس مَنٛز۔ تہٕ بہٕ کٔرٕ ژےٚ مارٕ تہٕ ژے نِش کلہٕ نِش کلہٕ۔ تہٕ بہٕ دِیہ از دۅہہ فلسطینن ہٕندِس لشکرس ہٕندِس لاشہٕ ہوہس منز جاناوارن تہٕ زمینہٕ کین جنگلی درندن دِنہٕ۔ یُتھ زِ سارِنٕے زمینس گژھہِ پتاہ زِ اسرٲیلِس مَنٛز چُھ اکھ خدا۔ {ڈیلیور...: ہیب۔ ژیہ بند کرُن}\n47. تہٕ یێمہِ سارِنٕے مجلسہٕ گژھہِ پتاہ زِ خداوند چُھہ نہٕ تلوار تہٕ نیزٕ سٍتـ̡ نجات دِوان، تکیازِ جنگ چُھہ خداوند سُند، تہٕ سُہ دِیہِ ژے سانہِ اتھس مَنٛز۔\n48.\\tتہٕ سپُد ییلہ فلسطینی ووٚتھ، تہٕ آو داؤدس سمکھنہٕ خٲطرٕ نزدیک، تہٕ داؤد ژوٚل لشکرس کُن فلسطینس سمکھنہٕ خٲطرٕ۔\n49.\\tتہٕ داؤد ترووُن پننِس ٹھیلس منز اتھہٕ، تہٕ تتہِ رٔٹِن اکھ کٔن، تہٕ لوٚگُن فلسطینی سٕندِس ڈیکس پیٹھ، یُس کٔنہِ تٔمۍ سٕندِس ڈٮ۪کہٕ سٍتـ̡ ڈوب۔ تہٕ سُہ پیوٚو زمینس پیٹھ بُتھِس پیٹھ۔\n50. یێمہِ پٲٹھـ̡ داؤد دِژ فلسطینس پیٹھ غلیل تہٕ کٔنہِ سٍتـ̡ تہٕ دِتُن فلسطینس پیٹھ تہٕ مارُن سُہ مگر داؤد سٕندِس اتھس منز ٲس نہٕ کانہہ تلوار۔\n51. تێمہِ کِنۍ ژوٚل داؤد تہٕ لوٚگ فلسطینس پیٹھ، تہٕ تٔمۍ سٕنز تلوار تُلِتھ تہٕ کٔرٕن أمِس کلہٕ ژٹِتھ تہٕ ژٹُن أمِس کلہٕ۔ تہٕ ییلہ فلسطینیو وُچھ تہند چیمپئن اوس موٗدمُت، تِم ژٔلۍ۔\n52.\\tتہٕ اِسرٲیلِس تہٕ یہوداہٕکۍ لُکھ ووٚتھ، تہٕ کرٛٮ۪کھ تہٕ لٔگِکھ فلسطینن ہُند پَتہٕ، یوتام تُہۍ وادی تہٕ ایکرون کِس دروازس تام وٲتِتھ۔ تہٕ فلسطینن ہٕندِ زخمیَن ہٕندِ وتہِ پیوٚو شارایمس کُن، حتیٰ کہ گاتھس تام تہٕ ایکرونس تام۔\n53.\\tتہٕ بنی اسرٲیلِس لٔگِتھ واپس، تہٕ تِمو کٔرِکھ پنٕنۍ خیمہ خراب۔\n54. تہٕ داؤد روٚٹ فلسطینی سُند کلہٕ، تہٕ أنِن یروشلم۔ مگر تمۍ ترٲو پنن ہتھیار پننس خیمس منز۔\n55.\\tتہٕ ییلہ ساؤل وُچھ داؤد فلسطینس خلاف نیران، تٔمۍ ووٚن لشکرُک کپتان ابنرس یُس یُس نیچو چُھہ یہِ نوجوان؟ تہٕ ابنیرن ووٚن، {یتھک} تُہند روح چُھ زندٕ، اے بادشاہ، بہٕ چُھس نہٕ ؤنتھ۔\n56.\\tتہٕ بادشاہن ووٚن، ژے پرژھ کٔرِتھ زِ کُس نیچو چھُ۔\n57. تہٕ یێلہِ داؤد فلسطینی سٕندِ قتلہٕ پٲٹھـ̡ واپس آو، عبنرن نیو سُہ تہٕ أنِن سُہ فلسطینی سُند کلہٕ اتھس منز ہیتھ ساؤلس برونہہ کُن۔\n58. تہٕ ساؤلن ووٚن أمِس زِ تُہۍ کُس نیچو چُھہ؟ تہٕ داؤدَن دیُت جواب، بہٕ چُھس چُھس چانہِ خادم یسی بیت اللحمی سُند نیچو۔","1. تہٕ سپُد ییلہ تٔمۍ ساؤلس سٍتـ̡ کتھ کرٕنـ̡ بند کٔر، زِ یوناتھن سُند روح اوس داؤد سٕندِس روحس سٍتـ̡ رٔلِتھ تہٕ یوناتھن اوس تس پننہِ روحہٕ سٍتـ̡ محبت کران۔\n2. تہٕ ساؤلن نیو سُہ تمہِ دۅہہ، تہٕ دِژن نہٕ تس مٲلہِ سٕندِس گَرٕ گَرٕ گَرٕ۔\n3.\\tپَتہٕ کٔر یوناتھن تہٕ داؤد اکھ معاہدٕ، تِکیازِ سُہ اوس أمِس پَنٕنِس روحس سٍتـ̡ محبت کران۔\n4.\\tتہٕ یوناتھنن کٔر پانس سُہ پوشہ یُس أمس پیٹھ اوس، تہٕ دِژن داؤدس تہٕ تٔمۍ سٕندِس پلوس تہٕ تلوارس تہٕ کمانس تہٕ تٔمۍ سٕندِس کمرس منٛز۔\n5. تہٕ داؤد گۆو ییتہِ تہِ ساؤلن سُہ سوزمُت، تہٕ ساؤلن تھوو سُہ جنگی نفرن پیٹھ، تہٕ سُہ آو سارِنٕے لُکن ہٕندِس نظرس منز تہٕ ساؤل سٕندِس خادمَن ہٕندِس نظرس منز قبول۔ {برتاو...: یا، خوشحال}\n6. تہٕ یێلہِ دٲیرٕ داؤد فلسطینی سٕندِ قتلہٕ پٲٹھـ̡ واپس آو، زِ زنانہٕ گٔیہٕ اسرٲیلِہ کِس سارِنٕے شہرو منزٕ گٮ۪وان تہٕ نژان، بادشاہ ساؤلس سٍتـ̡ مِلنہٕ خٲطرٕ، خۅش تہٕ موسیقی ہٕندِس سازو سٍتـ̡ ۔ {فلسطینی: یا، فلسطینی} {آلات...: ہیب۔ ترے تار وٲل آلات}\n7.\\tتہٕ زنانہِ دِژ اکھ أکِس جواب تہٕ وونُن، ساؤلن مارۍ ساس تہٕ داؤد پنہٕ نِس داہ ساس۔\n8.\\tتہٕ ساؤل گوٚو سٮ۪ٹھاہ شرارت، تہٕ یہِ کتھ گٔیہِ أمِس ناراض۔ تہٕ تٔمۍ ووٚن، تِمو چُھ داؤدس سٍتـ̡ داہ ساس منسوب کٔرۍمٕتۍ، تہٕ میہ سٍتـ̡ چُھ ساس ساس منسوب کٔرۍمٕتۍ، تہٕ {کیا} ہیٛکہٕ أمِس بادشاہت ورٲے زیادٕ ٲسِتھ؟ {أمِس ناراض: حب۔ امۍ سنزن نظرن منز اوس بدکار}\n9. تہٕ ساؤل کٔر تمہِ دۅہہ پیٹھٕ تہٕ برونٹھ کُن داؤدس نظر۔\n10. تہٕ پَگہہ سپُد یہِ زِ خدایہِ سُند بد روح آو ساؤلس پیٹھ، تہٕ تٔمۍ کٔر گرس منز پیشن گویی تہٕ داؤد گِندُن پننِس اتھہٕ سٍتـ̡ تہٕ ساؤل سٕندِس اتھس مَنٛز اوس اکھ نیزٕ۔\n11. تہٕ ساؤلن ترٛٲو نیزٕ۔ تکیازِ تٔمۍ ووٚن زِ بہٕ دٲیرس تہِ دیوارس پیٹھ تہِ مارٕ دِتھ۔ تہٕ ڈیوڈ کٔر دۄیہِ لٹہِ پننہِ موجودگی نِش بچان۔\n12. تہٕ ساؤل اوس داؤد سٕندِ سٍتـ̡ کھوژان، تکیازِ خداوند اوس أمِس سٍتـ̡ تہٕ ساؤلس نِش اوس نیران۔\n13. تێمہِ کِنۍ کٔر ساؤلن أمِس نِش تہٕ بنووُن ساس کھۄتہٕ زیادٕ سُہ کپتان۔ تہٕ سُہ گوٚو نیٚبر تہٕ لُکن برونہہ کُن۔\n14.\\tتہٕ داؤد کٔر پنٕنـ̡ سارِنٕے طریقو سٍتـ̡ دانشمندی سٍتـ̡ سٍتـ̡ تہٕ خداوند اوس أمِس سٍتـ̡ ۔ {برتاو...: یا، خوشحال}\n15. تێلہِ ییلہ ساؤلن وُچھ زِ سُہ چُھ سٮ۪ٹھاہ دانشمندانہ سلوک کران، سُہ گوٚو أمِس نِش کھوژان۔\n16.\\tمگر سارِنٕے اسرٲیلِس تہٕ یہوداہ سٍتـ̡ اوس داؤدس محبت کران، تکیازِ سُہ گۆو نٮبر تہٕ تِمن برونہہ کنہِ اژُن۔\n17. تہٕ ساؤلن ووٚن داؤدس زِ میانہِ زِٹھہِ کورِ میراب، بہٕ دِیُس ژے زنانہٕ دِیُن، صرف ژٕ میانہِ خٲطرٕ بہادر روزُن، تہٕ خداوند سٕندِس جنگس منز لڑُن۔ تکیازِ ساؤلن ووٚن زِ میون اتھہ گژھہِ نہ تس پیٹھ بلکہ گژھہِ فلسطینن ہند اتھہ تس پیٹھ۔ {بہادر: ہیب۔ بہادری ہُنٛد نیٚچُو}\n18. تہٕ داؤد ووٚن ساؤلس زِ بہٕ کُس چُھہ؟ تہٕ میانہِ زندگی کیا چُھ، یا میٲنس مٲلۍ سُند عیال کیا چُھ، یُس بہٕ بادشاہ سُند زامتُر آسُن؟\n19.\\tمگر یہ سپد تمہِ ساعتہ ییلہ میراب ساؤل سنز کورِ داؤدس دنہ ییہ تہ سۅ ٲس مہولتھیس ادریلس زنانہِ دِنہٕ آمژ۔\n20.\\tتہٕ میکل ساؤل سٕنزِ کورِ ٲس داؤدس محبت کران، تہٕ تِمو ووٚن ساؤلس تہٕ یہِ کتھ گٔیہِ أمِس خۄش۔ {خوش گٔژھمُت: ہیب۔ امۍ سنزن اچھن منز اوس صحیح}\n21. تہٕ ساؤلن ووٚن، بہٕ دِیہ أمِس أمِس دِنہٕ، یُتھ زن سُہ أمِس خٲطرٕ جال بنہِ، تہٕ فلسطینن ہُند اَتھٕ گژھہِ أمِس خٕلاف۔ تێلہِ ووٚن ساؤلن داؤدس زِ ژٕ گژھ از دۅہہ میون زامتُر بنہٕ۔\n22. تہٕ ساؤلن دِیُت پننین خدمتگارن حُکُم زِ داؤدس سٍتـ̡ ژوٗرِ پٲٹھـ̡ کتھ باتھ کرٕن، تہٕ ونُن، وُچھِو، بادشاہ چُھہ ژے سٍتـ̡ خوش تہٕ تٔمۍ سٕندِس سارِنٕے خادمَن چُھہ ژےٚ محبت کران، تێمہِ مۄکھٕ بٔنِو بادشاہ سُند زامتُر۔\n23.\\tتہٕ ساؤل سٕندِس خدمتگارو کٔر یِم لفظ داؤد سٕندِس کنن مَنٛز بولان۔ تہٕ داؤد ووٚن زِ ژے چُھس بادشاہ سُند زامتُر، یہ وُچھِتھ زِ بہٕ چُھس اکھ غریب، تہٕ ہلکہٕ پٲٹھۍ؟\n24.\\tتہٕ ساؤل سٕندِس نوکرَو ووٚن أمِس وَنُن زِ یِتھٕ پٲٹھۍ اوس داؤد وَنان۔ {پیٹھ...: ہیب۔ یمن لفظن مطٲبق}\n25.\\tتہٕ ساؤلن ووٚن، یِتھٕ پٲٹھۍ وَنُن داؤدس زِ بادشاہ چُھ نہٕ کانہہ داج یژھان، بلکہِ فلسطینن ہٕندِ ہتھ کھالہٕ یُس بادشاہ سٕندِس دُشمنن ہُند انتقام ہُند بدلہٕ نِنہٕ خٲطرٕ۔ مگر ساؤلن سوچ زِ سُہ کرِ داؤد فلسطینن ہٕندِ اتھہٕ سٍتـ̡ پیوٚو۔\n26.\\tتہٕ ییلہ تٔمۍ سٕندٮ۪و خادمَو داؤدس یِم لفظ وَن، داؤدَس گٔیہِ بادشاہ سُند زامتُر آسُن خۄش۔ {میعاد ختم گومُت: ہیب۔ پورٕ}\n27. اَمہِ مۄکھٕ ووت داؤد تہٕ تٔمۍ سٕندِس نفرَس تہٕ مٲرِن فلسطینی زٕ ہتھ نفر۔ تہٕ داؤد أنۍ تِہٕندِ کھالہٕ تہٕ تِمو دِژ بادشاہس پوٗرٕ دٔلیلہٕ دِنہٕ، تاکہ سُہ بنہِ بادشاہ سُند زامتُر۔ تہٕ ساؤلن دیُت أمِس میخال پنٕنۍ کورِ زنانہٕ خٲطرٕ۔\n28.\\tتہٕ ساؤلن وُچھ تہٕ زانان زِ خداوند اوس داؤدس سٍتـ̡ تہٕ {یہ} میکل ساؤل سٕنزِ کورِ ٲس أمِس محبت کران۔\n29. تہٕ ساؤل اوس داؤدٕ سٕندِ نِش زیادٕ کھوژان۔ تہٕ ساؤل بنیوو مسلسل داؤد سُند دُشمن۔\n30. پَتہٕ درٛاو فلسطینی ہٕندِ شہزادٕ تہٕ یہِ سپُد یِمن ہٕندِس سارِنٕے خادمَن ہٕندِس کھۅتہٕ زیادٕ عقلمندی سٍتـ̡ تاکہ تٔمۍ سُنٛد ناو اوس واریاہ زیادٕ مقرر کرنہٕ آمُت۔ {سیٹ بذریعہ: ہیب۔ قیمتی}","1. تہٕ ساؤلن ووٚن پننِس نیچوِس یوناتھن تہٕ تٔمۍ سٕندِس سارِنٕے خدمتگارن سٍتـ̡ کتھ زِ تِم گژھن داؤد مارٕنـ̡ ۔\n2. مگر یوناتھن ساؤل سُند نیچو گۆو داؤدس سٍتـ̡ واریاہ خۅش تہٕ یوناتھنن ووٚن داؤدس زِ میون مول ساؤل چُھ ژے مارُن یژھان، تێمہِ کِنۍ چُھس بہٕ ژے دُعا کران، صُبحَس تام روزُن پانس نِش ہوشیار تہٕ کُنہِ خفیہ جایہِ روزُن، تہٕ پَنُن پان ژوٗرِ روزُن:\n3.\\tتہٕ بہٕ نیرٕ نیرِتھ پننِس مٲلِس سٍتـ̡ کھاہس مَنٛز کھڑا یێلہِ تہٕ بہٕ کَرٕ پننِس مٲلِس سٍتـ̡ کتھ باتھ۔ تہٕ بہٕ کیا وُچھان چھُس، یُس بہٕ ژے وَنُن۔\n4.\\tتہٕ یوناتھن کٔر پننِس مٲلِس ساؤلس سٍتـ̡ داؤدس سٍتـ̡ نیک کتھ تہٕ وونُن زِ بادشاہ گژھہِ نہٕ پننِس خادمس سٍتـ̡ داؤدس سٍتـ̡ گۅناہ کرنہٕ۔ تکیازِ تٔمۍ چُھ نہٕ تۅہہِ سٍتـ̡ گۅناہ کورمُت، تہٕ تٔمۍ سٕنزِ کٲم چھے تۅہہِ سٍتـ̡ واریاہ اصل رودمٕژ:\n5. تِکیازِ تٔمۍ کٔر پَنُن جان پَنٕنِس اتھس مَنٛز، تہٕ مٲرِن فلسطینی تہٕ خداوند کٔرٕن سارِنٕے اسرٲیلِس خٲطرٕ بٔڈ نجات حٲصِل: تہٕ ژے کٔرٕکھ خۅش تہٕ کٔرٕکھ خۅش تہٕ تێلہِ کیازِ کٔرِکھ بے گناہ خونس سٍتـ̡ داؤد سُند قتل کُنہِ وجہہ سٍتـ̡ ۔\n6. تہٕ ساؤلن بوز یوناتھن سٕنز آواز: تہٕ ساؤلُن قسم، یێلہِ خداوند زندٕ چُھ، سُہ گژھِ نہٕ مارنہٕ۔\n7. تہٕ جوناتھن بُلوو داؤد، تہٕ جوناتھنن ہٲوۍ تِم سٲری چیز۔ تہٕ یوناتھن اوٚن داؤد ساؤلس نِش، تہٕ سُہ اوس پتھ کالہٕ پٲٹھۍتسٕندِس حٲضِرس منز۔ {وقتس منز...: ہیب۔ راتھ تریم دۅہ}\n8. تہٕ دُبارٕ گوٚو جنگ: تہٕ داؤد دراو نیٚبر، تہٕ لوٚڑُن فلسطینن سٍتۍ، تہٕ مارُن تِم سٮ۪ٹھاہ قتل کٔرِتھ۔ تہٕ تِم ژٔل أمِس نِش۔ {ام: ہیب۔ تٔمۍ سُنٛد بُتھ}\n9.\\tتہٕ خداوند سُند بد روح اوس ساؤلس پیٹھ، یێلہِ سُہ پننِس گَرَس مَنٛز بِہتھ نیزہ ہیتھ تہٕ داؤد اوس پننِس اتھہٕ سٍتـ̡ گِندان۔\n10. تہٕ ساؤلن کٔر داؤدس دیوارس تام نیزہ سٍتـ̡ مارنٕچ کوشش۔ مگر سُہ ژوٚل ساؤل سٕنزِ حٲضِری نِشہِ تہٕ لوٚگ دیوارس سٍتـ̡ نیزٕ تہٕ ژوٚل داؤد تہٕ ژوٚل تَمہِ رٲژ ژٔلِتھ۔\n11.\\tساؤلن سوٗزۍ داؤد سٕندِس گَرٕ تہٕ سُہ رٲچھ کرنہٕ خٲطرٕ تہٕ صبحٲے مارنہٕ خٲطرٕ، تہٕ میکل داؤد سٕنزِ زنانہِ ووٚن تٔمِس زِ اگر ژٕ رٲژ تام پنُن زُو بچٲوِتھ تہٕ پگہہ یِیہِ مارنہٕ۔\n12.\\tچنانچہ میکل تروو ڈیوڈس دارِ منزہ تہ ژوٚل تہ ژوٚل تہ ژوٚل۔\n13.\\tتہٕ میخالن تُل اکھ تصویر، تہٕ تھووُن بسترس منز، تہٕ تھووُن ژھاوُن ہُند اکھ تکیہ تہٕ تھووُن پلو سٍتـ̡۔ {تصویر: ہیب۔ ٹیرافیم}\n14. تہٕ ییلہ ساؤل داؤد نِنہٕ خٲطرٕ قاصد سوٗز، تٔمۍ ووٚن سُہ چُھ بیمار۔\n15.\\tتہٕ ساؤل سوٗزۍ رسول داؤدس نِش دُوُدس نِش وُچھنہٕ خٲطرٕ، یہِ وونُن زِ سُہ أنِو میہ نِش بسترس منز، یُتھ بہٕ مارٕ کٔرِتھ۔\n16.\\tییلہ قاصد اژان آیہ، وچھ بسترس منز اوس اکھ شبیہہ یتھ منز ژھاوۍ سُند اکھ تِلہٕ اوس۔\n17.\\tتہٕ ساؤلن ووٚن مِکالَس زِ ژے کیازِ دِژ میہ یُتھ دھوکہٕ دِتھ میون دُشمن ژلُن، یُس ژلہِ ژٔلِتھ تہٕ میخلن دیُت ساؤلس جواب، تٔمۍ ووٚن مے گژھُن، میہ کیازِ کرِ ژیہ مارُن؟\n18.\\tتێلہِ ژوٚل داؤد تہٕ ژوٚل تہٕ سموئیلس نِش آو راماہس نِش، تہٕ وونُن سُہ سورُے یُس ساؤلن أمِس سٍتـ̡ کورمُت اوس۔ تہٕ سُہ تہٕ سموئیل گٔیہِ نیوتھس منز روزان۔\n19.\\tتہٕ ساؤلس وونُن زِ وُچھو داؤد راماہ کِس نایوتھس مَنٛز۔\n20. تہٕ ساؤلن سوٗزۍ داؤد نِنہٕ خٲطرٕ قاصد تہٕ ییلہ تِمو پیغمبرن ہٕنز پیشن گویی کران وُچھ، تہٕ سموئیل اوس تِمن پیٹھ مقرر کرنہٕ آمُت، خدا سُند روح اوس ساؤل سٕندِس رسولن پیٹھ تہٕ تِمو کٔر پیشن گویی تہِ۔\n21.\\tییلہ یہ ساؤل وننہ آو تٔمۍ سوٗزۍ باقی قاصد، تہٕ تِمو کٔر یِتھۍ پٲٹھۍ پیشن گوئی۔ تہٕ ساؤلن سوُز تریمہِ لٹہِ بییہِ قاصد، تہٕ تِمو کٔر پیشن گویی تہِ۔\n22.\\tاَمہ پَتہٕ ووت سُہ تہِ راماہس نِش، تہٕ ووت أکِس بٔڈِس کُرِس کُن یُس سیچوس مَنٛز چُھہ، تہٕ تٔمۍ پرژھُن تہٕ وونُن، سموئیل تہٕ داؤد کتہِ چھِ؟ تہٕ {اَکہ} ووٚن، وُچھِو، {تِمَن} چھِ رامہ کِس نایوتھس مَنٛز۔\n23.\\tتہٕ سُہ گۆو تتہِ رامہس مَنٛز نایوتھ کُن، تہٕ خدایہِ سُند روح تہِ اوس أمِس پیٹھ، تہٕ سُہ پوٚک تہٕ پیشن گویی کٔرٕن، یوتام سُہ راماہس مَنٛز نایوتھ ووتُن۔\n24. تہٕ تٔمۍ کٔر پَنٕنۍ پَنٕنۍ پَلو تہٕ تِتھۍ پٲٹھۍ کٔرٕن سموئیلس برونہہ کُن پیشن گویی تہٕ لوٚگ سٲرۍسٕے دۅہس تہٕ سٲرۍسٕے رٲژ ننگہٕ روزِتھ۔ کیازِ چھہِ تم ونان زِ کیا ساؤل تہِ چھہ پیغمبرن منز؟ {lay: Heb. گٔیہِ}","1. تہٕ داؤد ژوٚل رامہ کِس نایوتھ پیٹھ، تہٕ آو تہٕ وونُن جوناتھن برونہہ کُن، مے کیا چُھہ کورمُت؟ میٲنۍ بدکاری کیا چھِ؟ تہٕ میٲنس مٲلس برونہہ کُن کیا گۅناہ چُھ، یُس سُہ میانہِ زندگی ژھاران چُھ؟\n2. تہٕ تٔمۍ ووٚن أمِس خدایہِ نَز۔ ژے گژھِ نہ مرُن: وچھ میون مول کرِ نہ کانہہ بوٚڈ یا لۅکٹ، مگر سُہ کرِ میہ یہ ہاوُن: تہٕ میون مول کیازِ تھاوِ یہ چیز میہ نِش۔ یہِ {چھُ} نہٕ {تَمہِ}۔ {شو...: ہیب۔ میون کَن کھولو}\n3. تہٕ داؤد وۆن بییہِ قسم، تہٕ وونُن، تُہند مول چُھ یقینا زانان زِ میہ چُھہ چانہِ نظرن منز فضل میلان۔ تہٕ سُہ چُھ ونان زِ یوناتھنس گژھہِ نہٕ یہِ زاننہٕ، نتہٕ گژھہِ سُہ غمگیٖن روزُن، مگر پٔزۍ پٲٹھۍ چُھ خداوند زندٕ روزان، تہٕ {یِتھک} چُھہ تُہند روح زِندٕ روزان، {یێتھکِھ} چُھہ میانہِ تہٕ موتس درمِیان صرف اکھ قدم۔\n4. پتہٕ ووٚن یوناتھن داوڈس زِ یُس تہِ تُہند روح یژھان چُھ، بہٕ کٔرٕ تہٕ چانہِ خٲطرٕ تہِ۔ {کنہِ تہِ...: یا، ونو تہند دماغ کیا چُھ تہٕ بہٕ کرٕ وغیرہ} {خواہش: ہیب۔ کتھ کران، یا، سوچان}\n5.\\tتہٕ داؤدن ووٚن جوناتھنَس زِ پَگہہ چُھہ نٔو زوٗنہِ، تہٕ بہٕ پزِ نہٕ بادشاہس سٍتـ̡ مازس پیٹھ بِہنہٕ نِش ناکام روزُن، مگر بہٕ گژھہِ نیرُن، یُتھ بہٕ تریمہِ دۅہس تام کھاہس منز ژوٗرِ روزُن۔\n6.\\tاگر چانہِ مٲلہِ میہ یاد آسہِ، تیلہِ ونُن زِ ڈیوڈس ووٚن میہ سٍتـ̡ رخصت زِ سُہ گژھہِ بیت اللحم کِس شہرس کُن ژلُن، تکیازِ اتہِ چُھہ سارنٕے عیالس خٲطرٕ سالانہٕ قربانی دِنہٕ یوان۔ {قربانی: یا، دعوت}\n7.\\tاگر سہ یتھہ پاٹھۍ ونان چھہِ، {یہِ} چھہ ٹھیک۔ چانہِ خادمس گژھہِ امن مگر اگر سُہ واریاہ غصہ آسہِ، {تیلہِ} گژھہِ یقینی زِ بدی ہند فیصلہ چھہ أمِس سٍتـ̡ کرنہٕ۔\n8.\\tتێلہِ کٔرِو تۅہہ پننِس خادمس سٍتـ̡ مہربانی سٍتـ̡ تکیازِ ژے چُھہ پنُن خادم پانس سٍتـ̡ خداوند سٕندِس معاہدس مَنٛز انمُت، باوجوٗد تہِ اگر میانہِ مَنٛز بدکاری آسہِ، تیلہِ کٔرِو مے پان مارُن۔ کیازِ ژے کیازِ چھکھ میہ پننس مٲلس نِش انان؟\n9.\\tتہٕ جوناتھن ووٚن، ژے نِش دور گژھُن، تکیازِ اگر میہ پتاہ آسہِ زِ میٲنس مٲلۍ سٕندِ دٔسۍ چُھ بُرٲیی ہُند فیصلہ ژےٚ کرنہٕ آمُت، تیلہِ کیا بہٕ ژے یہ ؤنِتھ؟\n10.\\tاَمہِ پتہٕ ووٚن داؤد جوناتھنَس زِ مے کُس وَنُن؟ نتہٕ کیا چُھہ تُہند مول ژیہ سختی سان جواب دِیہِ؟\n11. تہٕ یوناتھن ووٚن ڈیوڈس زِ آ تہٕ گژھو میدانس مَنٛز۔ تہٕ تِم گٔیہِ دۄشوے مٲدانَس منٛز۔\n12.\\tتہٕ یوناتھنن ووٚن داوڈس زِ اے خداوند اسرائیلُک خدا، ییلہ میہ پننِس مٲلس پگہہ کُنہِ تہِ وِزِ دِنہٕ آمُت، تہٕ وُچھ، {یێلہِ} داؤدس سٍتـ̡ خیر آسہِ، تہٕ بہٕ چُھس نہٕ ژے نِش سوزان تہٕ ہاوُن تہٕ ہاوُن۔ {آواز: ہیب۔ تلاش} {shew...: Heb. پنُن کَن کھولو}\n13.\\tخداوند کٔرِن یۅہے تہٕ واریاہ زیادٕ، مگر اگر میانہِ مٲلہِ ژے بد کار کرُن، تیلہِ کرٕ بہٕ ژے ہٲوِتھ تہٕ ژے نیرُن، یُتھ ژے امن سان نیرُن، تہٕ خداوند روزِ توے سٍتۍ، یِتھٕ پٲٹھۍ سُہ میٲنِس مٲلِس سٍتـ̡ اوس۔ {شو...: ہیب۔ پنُن کَن کھولو}\n14. تہٕ یێلہِ تہِ بہٕ زندٕہ روزِتھ تہٕ بہٕ کٔرِو نہٕ مٔرِتھ خداوند سٕنز مہربانی ہاونہٕ۔\n15.\\tمگر ژے گژھ نہٕ میانہِ گرٕ سٍتـ̡ پنٕنۍ مہربانی ہمیشہٕ خٲطرٕ ژٔٹِتھ: نہ، نہٕ ییلہِ خداوند داؤد سٕندِس دُشمن ہٕندِس دُشمن ہٕندِس زمینہٕ سٍتـ̡ ژٔٹِتھ ژٔٹِتھ ۔\n16.\\tیێلہِ کٔر یوناتھنن داؤد سٕندِس گرس سٍتـ̡ {اکھ معاہد}، {ونُن} زِ خداوند گژھہِ داؤد سٕندِس دُشمنن ہٕندِس دُشمنس سٍتـ̡ {یہ} تہِ ضروری۔ {بنیومُت: ہیب۔ کٹ}\n17.\\tتہٕ جوناتھن دِژ داؤدس بییہِ قسم، تکیازِ سُہ اوس أمس محبت کران، تکیازِ سُہ اوس أمس پننس روحس محبت کران۔ {کیازِ...: یا، تس سیتۍ محبت کٔرتھ}\n18. اَمہِ پَتہٕ ووٚن یوناتھن داؤدَس زِ پَگہہ چُھہ نٔو زوٗنہِ: تہٕ تُہٕندِس جاۓ گژھِ خٲلی، تِکیازِ تُہٕنزِ جاۓ آسہِ خٲلی۔ {خٲلی: ہیب۔ مِسڈ}\n19.\\tتہٕ ییلہ تہِ ژیہ تریہ دۅہ روزِ، {تیلہِ} گژھِو جلدی بۄن تہٕ تتھ جایہِ یُس ژیہ پنُن پان ژوٗرِ تھوومُت اوس، تہٕ روزُن کنہِ ایزلس نِش۔ {جلدی: یا، مستعدی سان: ہیب۔ بٔڈۍ {ییلہ ...: ہیب۔ کاربارٕ کِس دۅہس منز} {ایزل: یا، یُس وتھ ہاوان چھُ}\n20.\\tتہٕ بہٕ چلاوٕ تریہ تیر اندۍ پکھۍ، یتھہ پاٹھۍ میہ کُنہِ نشانس پیٹھ گولہ لگٲومُت۔\n21.\\tتہٕ وُچھِتھ سوز بہٕ اکھ لڑکہٕ، {ونان}، گژھ تیر ژھانڈان۔ اگر بہٕ واضح پٲٹھۍ لڑکہٕ ونان، وچھ، تیر چھِ ژے اَتھ طرفہٕ، تِم رٔٹِو۔ تیلہ چُھہ تۅہہ یِمن سٍتـ̡ {یِتھٕ کٔن}خداوند چُھ زندٕ۔ {کانہہ تکلیف نہٕ: ہیب۔ کانٛہہ تہِ نہٕ}\n22.\\tمگر اگر بہٕ نوجوانس یۅہے ونان، وچھ تیر چھہِ ژے نیبر۔ پَنٕنہِ وَتہِ پٔکِو: کیازِ خداوند چُھہ ژےٚ ژٔٹِتھ دِژمُت۔\n23.\\tتہٕ یُس معاملہٕ ژے تہٕ میہ کتھ کٔرمٕژ چُھ، وُچھِو، خداوند روزُن تہٕ میانہِ درمِیان ہمیشہٕ خٲطرٕ۔\n24. تہٕ داؤد ژوٗر کھاہس مَنٛز، تہٕ ییلہ نٔو زوٗن آو تہٕ بادشاہن بِیوٹھ سُہ ماز کھٮ۪نہٕ خٲطرٕ۔\n25.\\tتہٕ بادشاہ بیوٹھ پننہِ جایہ پٲٹھۍ، یِتھے پٲٹھۍ دیوارس نِش أکِس نشستس پیٹھ، تہٕ یوناتھن ووٚتھ، تہٕ ابنیر بیوٹھ ساؤل سٕندِس نِش تہٕ داؤد سٕنز جاے ٲس خٲلی۔\n26.\\tتوتہِ کٔر نہٕ ساؤلن تمہِ دۅہہ کانہہ تہِ کتھ تہِ، تکیازِ تس گوو کینہہ گومُت، سُہ چُھہ نہٕ پاک گومُت۔ یقینا چُھ نہٕ سُہ {چُھ} صاف۔\n27.\\tتہٕ سپُد پگہہ دۅہہ، یُس داؤد سٕنز جاے ٲس خٲلی، تہٕ ساؤلن ووٚن پننِس نیچوِس یوناتھنس زِ یژھ سُند نیچو کیازِ آو نہٕ راتھ تہٕ نہ دۅہہ؟\n28.\\tتہٕ یوناتھنن دیُت ساؤلس جواب، داؤد دِژ میہ سٍتـ̡ {بیت اللحمس گژھُن} اجازت دِنہٕ:\n29. تہٕ تٔمۍ ووٚن، بہٕ چُھس ژےٚ دُعا کران۔ تکیازِ سانہِ عیالس چھہ شہرس منز قربانی دوان۔ تہٕ میانہِ بٲے، تٔمۍ دِژ مے حُکُم {تتہِ روزنُک}: تہٕ وۄنۍ، اگر میہ چانہِ نظرن منز احسان میلہِ، بہٕ گژھ ژےٚ دُعا تہٕ پنٕنۍ بٲے وُچھان۔ لہذا چُھ نہٕ سُہ بادشاہ سٕندِس میزس پیٹھ یوان۔\n30.\\tاَمہِ پَتہٕ گۆو ساؤل سُند شَرارتہٕ یوناتھنس سٍتـ̡ تہٕ تٔمِس وونُن، اے بد کار سٕندِس نیچو، کیا بہٕ چُھس نہٕ پتاہ زِ ژے چُھکھ یسیٰ سُند نیچو پننہِ پریشٲنی مۅکھہٕ تہٕ پننہِ ماجہ ہٕندِس ننگہٕ سٍتـ̡ ژارنہٕ آمُت؟ {توہ...: یا، توے بغاوت کٔرِو: حب۔ بغاوتُک نیٚچُو}\n31.\\tیوتام یژھ سُند نیچو زمینس پیٹھ روزِ، توٚت تام گژھہِ نہ تۅہہ قایم سپدِتھ تہٕ نہ تہنز بادشٲہی روزِ۔ لہٰذا سوز تہٕ أنِو سُہ میانہِ نِش، تکیازِ سُہ گژھہِ یقینا مرُن۔ {شال...: ہیب۔ چُھ موتُک نیٚچُو}\n32. تہٕ یوناتھنن دیُت پننِس مٲلِس ساؤلس جواب تہٕ وونُن زِ سُہ کیازِ یِیہِ مارنہٕ؟ تٔمۍ کیا کوٚر ؟\n33.\\tتہٕ ساؤلن لوٚگ أمِس کُن نیزہ تہٕ یێمہِ سٍتـ̡ جوناتھن پتاہ زِ تٔمِس مٲلہِ سُند مُقرر چُھ داؤد مارُن۔\n34.\\tیِتھٕ ووٚتھ جوناتھن سٮ۪ٹھاہ شَرارتہٕ سٍتـ̡ میزہٕ پیٹھ، تہٕ ریتھ کِس دٔیمہِ دۅہہٕ کھیوٚن نہٕ کانہہ ماز، تکیازِ أمِس اوس داؤدٕ سٕندِ خٲطرٕ غمگسار گومُت، تکیازِ تٔمۍ سٕندِس مٲلہِ اوس أمِس شرمسار کورمُت۔\n35.\\tتہٕ صُبحے سپُد یہِ زِ جوناتھن دراو داؤدس سٍتـ̡ مُقرر کرنہٕ وِزِ میدانس مَنٛز، تہٕ أمِس سٍتـ̡ اکھ لۄکُٹ لڑکہٕ۔\n36.\\tتہٕ تٔمۍ ووٚن پننِس لڑکَس زِ ژٔلِتھ ژٔلِتھ وُچھِو تِم تیر یِم بہٕ چلاوان چھِ۔ {تہِ}ییلہ لڑکہٕ ژوٚل، تٔمۍ لگٲو پانس برونہہ کُن تیر۔ {امہِ پتہٕ...: ہیب۔ أمِس نِش گزرنہٕ خٲطرٕ}\n37.\\tتہٕ ییلہ لڑکہٕ تتھ تیرس پیٹھ ووت یُس جوناتھنن گولہِ لگٲومُت اوس، جوناتھن ووٚتھ لڑکہٕ پتہٕ تہٕ وونُن، کیا یہ تیر چُھنہٕ ژےٚ نیبر نیران؟\n38.\\tتہٕ جوناتھن ووٚتھ لڑکہٕ پتہٕ، تیز کرُن، جلدی کرو، روزُن نہٕ۔ تہٕ جوناتھن سٕندِ لڑکہٕ کٔر تیر جمع تہٕ آو پننِس مٲلکَس نِش۔\n39.\\tمگر لڑکہٕ ٲس نہٕ کانہہ خبر، صرف جوناتھن تہٕ ڈیوڈس ٲس یہِ معاملہٕ زانان۔\n40.\\tتہٕ جوناتھن دِژ پنُن توپ خانہٕ پننِس لڑکِس تہٕ وونُن تٔمِس گژھِ، تِمن نِن شہرس کُن۔ {توپ خانہ: ہیب۔ آلات} {تہند لڑکہ: ہیب۔ سُہ لڑکہٕ یُس أمِس اوس}\n41.\\t{تہٕ}ییلہ لڑکہٕ نیرِ، داؤد ووٚتھ {أکِس جایہ} جنوبس کُن، تہٕ پیوٚو بُتھِس پیٹھ زمینس پیٹھ، تہٕ کوٚرُن تریہ لٹہِ نمُن: تہٕ تِمو کٔر اکھ أکِس بوسہٕ، تہٕ رووُن اکھ أکِس سٍتۍ، یوٚت تام داؤد ہیوٚت تام داؤد ہیوٚت۔\n42. تہٕ یوناتھنن ووٚن داوڈس زِ امن سان گژھ، یێلہِ أسۍ دۄشوٕے خداوند سٕندِ ناوٕ سٍتـ̡ قَسم کٔرِتھ، یہِ ونُن زِ خداوند روزِ میانہِ تہٕ تۅہہِ درمِیان تہٕ میانہِ نِش تہٕ تُہٕندِس بُلِس درمِیان ہمیشہٕ خٲطرٕ۔ {forasmuch...: یا، خداوند گژھہِ تمہِ چیزُک گواہ یُس بیترِ بیترِ}\n43.\\tتہٕ سُہ ووٚتھ تہٕ درٛاو تہٕ جوناتھن گوٚو شہرس مَنٛز۔","1.\\tاَمہ پَتہٕ آو داؤد نوبس نِش پادٕرۍ احیمیلخس نِش، تہٕ احیمیلک گوٚو داؤد سٕندِس مُلاقات سٍتـ̡ خوف، تہٕ وونُن تٔمِس زِ ژے کیازِ چُھکھ کُنی، تہٕ ژے سٍتـ̡ چُھہ نہٕ کانہہ تہِ۔ {اہیمیلک: یتھ احیا تہِ ونان چھِ}\n2.\\tتہٕ داؤدن ووٚن پادٕرۍ احیمیلخس زِ بادشاہن چُھ مےٚ اَکہِ کاربارُک حُکُم دِژمُت، تہٕ ووٚنمُت زِ کٲنسہ تہِ گژھِ نہٕ کٲنسہ تہِ زان زِ بہٕ کَمہِ کِس کاربارس مُتلق بہٕ سوزان چھُ، تہٕ مے چھُس یِتھۍ جایہِ نوکر مقرر کٔرۍمٕتۍ۔\n3. وۅنۍ کیا چُھہ تۅہہِ اتھس تل؟ میٲنس اتھس منز دِیُن پانژھ {روٹ} روٹی، نتہ یُس موجود آسہِ۔ {موجود: ہیب۔ لٔب}\n4.\\tتہٕ پادرین دیُت داؤدس جواب تہٕ وونُن، {میانِس اتھس تَل چُھنہٕ کانہہ عام روٹی، مگر مقدس روٹی چِھ۔ اگر جوان مرد کم از کم زنانن نِش پانس تھٲوتھ آسہِ۔\n5.\\tتہٕ داؤدن دیُت پادٕرِس جواب تہٕ وونُن، یێلہِ بہٕ نیبر نیرنہٕ پتہٕ چُھس یِمن ترٮ۪ن دۅہن زنانہٕ اسہِ نِش تھونہٕ آمٕژ، تہٕ جوانن ہٕندِ بانہٕ چھِ پاک، تہٕ روٹی چِھہ عام پٲٹھۍ، آ، حالانکہ یہ اوس از دۅہہ بانس منز مقدس کرنہٕ آمُت۔ {آ...: یا، خاص کر ییلہ از دۅہہ بانس منز بییہ کانہہ مقدس آسہِ}\n6.\\tیێلہِ دِژ پادٕرٮ۪ن تٔمِس مقدس روٹی، تکیازِ اَتہِ اوس نہٕ کانہہ روٹی بٔرِتھ یُس خداوند سٕندِ برونہہ کُن نِنہٕ آمُت اوس، یُس دۅہہٕ گرم روٹی تھاونہٕ مۅکھہ نِنہٕ آمُت اوس۔\n7. وۅنۍ اوس ساؤل سٕندِس خادمَن مَنٛز اَکھ شخٕص اَمہِ دۅہٕ خداوند سٕندِس برونہہ کُن رٔٹِتھ تھاونہٕ آمُت۔ تہٕ تٔمۍ سُند ناو اوس ڈوگ، اکھ ایڈومیٹ، یُس ساؤلس سُند سارِوٕے کھۄتہٕ بٔڈ چرواہ اوس۔\n8.\\tتہٕ داؤد ووٚن اہیمیلکس تہٕ کیا یتہِ چُھنہٕ تۅہہِ اتھہٕ نیزٕ یا تلوار تلوار؟ تِکیازِ بہٕ چھُس نہٕ پنٕنۍ تلوار تہٕ نہ پنٕنۍ ہتھیار، تِکیازِ بادشاہ سٕنٛدِس کاربارس ٲس جلدی کرنٕچ ضرورت۔\n9.\\tتہٕ پادٕرۍ ووٚن، گولیات فلسطینی سٕنز تلوار، یُس ژے ایلہ کِس وادی مَنٛز مارُن، وُچھِو یہِ {یِتھ} ایفوڈس پٔتِس پٔتِس پلوس منز ؤلِتھ، یێلہِ تہِ نِیُن {یہ} نِن، تکیازِ {یێتہِ} چُھہ نہٕ اَمہ علاوٕ بییہ کانہہ تہِ۔ تہٕ ڈیوڈس ووٚن، {تِتھ} چُھ نہٕ کانہہ تہِ۔ مے دِیُن یہِ۔\n10.\\tتہٕ داؤد ووٚتھ تہٕ ژوٚل تمہِ دۅہہ ساؤل سٕندِ خوفہٕ سٍتـ̡ تہٕ گۆو گاتھ کِس بادشاہس آچیش نِش۔\n11.\\tتہٕ آچیش سٕندٮ۪و خادمَو ووٚن أمِس زِ کیا یہِ چھُنہٕ داؤد ملکُک بادشاہ؟ کیا تِمو گیوٚو نہٕ أکِس أکِس نژنَس مَنٛز، یہِ وَنُن زِ ساؤلَن چھُ پَنٕنہِ ساسہٕ بٔدۍ تہٕ داؤدَن مٲرِتھ دَہ ساس۔\n12. تہٕ داؤد تھوو یِم لفظ پننِس دِلس منز، تہٕ سُہ اوس گاتھ کِس بادشاہ آچیش سٕندِس سٍتـ̡ کھوژان۔\n13.\\tتہٕ تٔمۍ بدلوو تِمن برونہہ کنہِ پنُن رٔویہ تہٕ تِمن ہٕندِس اتھس منز کوٚرُن پاگل ہُند بہانہ تہٕ دروازٕ کِس دروازس پیٹھ لٔگِتھ تہٕ ترووُن پنُن تھوُک داڑھس پیٹھ۔ {سکربلڈ: یا، نشانہٕ}\n14.\\tاَمہ پتہٕ ووٚن آچیش پننین خادمَن وُچھِتھ زِ یہِ چُھہ پاگل گومُت، تیلہِ کیازِ چھُکھ سُہ میانہِ نِش أنِمُت؟ {پاگل چُھ: یا، پاگل چُھ}\n15.\\tمیہ چھا پاگلن ہنز ضرورت، زِ ژیہ چھکھ یہ {فیلو} میانہِ حضوری منز پاگل سُند کردار ادا کرنہٕ خٲطرٕ أنمُت؟ کیا یہ {ساتھ} ییہ میٲنس گرس منز؟","1.\\tتَمہِ کِنۍ دراو داؤد تتہِ تہٕ ژوٚل گۅپھِ عدُلامس کُن، تہٕ ییلہ تٔمۍ سٕندِس بٲے تہٕ تٔمۍ سٕندِس مٲلہِ سٕندِس سارِنٕے گرَن بوٗز، تِم گٔیہِ تتہِ أمِس نِش۔\n2.\\tتہٕ پریتھ کانہہ یُس مصیبت منز اوس، تہٕ پریتھ کانہہ یُس مقروض اوس، تہٕ پرٮ۪تھ کانہہ {یُس} ناراض اوس، سٍتـ̡ گۆو پانس پانس سٍتـ̡ جمع کرنہٕ۔ تہٕ سُہ بنیوو تمن پیٹھ کپتان: تہٕ أمس سۭتۍ ٲسۍ تقریباً ژور ہتھ نفر۔ {اوس قرضس منز: ہیب۔ اوس اکھ قرض دہندہ} {غیر مطمئن: Heb. روحُک تلخ}\n3.\\tتہٕ داؤد گۆو موآب کِس مزپہس کُن، تہٕ تٔمۍ ووٚن موآب کِس بادشاہس زِ میون مول تہٕ میانہِ موج، بہٕ چُھس ژے دُعا کران زِ یێلہِ گژھن ژے سٍتـ̡ یِنہٕ سٍتـ̡ تہٕ یێلہِ بێیہِ تہٕ یێلہِ پتاہ زِ خدایہ کیا کرِ میانہِ خٲطرٕ۔\n4.\\tتہٕ تِم أنۍ موآب کِس بادشاہس برونہہ کُن، تہٕ تِم روٗد أمِس سٍتـ̡ روزان یێلہِ داؤد سٍتـ̡ رٔٹِتھ اوس۔\n5. تہٕ پیغمبر گاد ووٚن داؤدس زِ رٔٹِتھ روزُن نہٕ۔ نیرُن، تہٕ ژے گژھ یہوداہ کِس سرزمینس مَنٛز۔ اَمہ پتہٕ دراو داؤد تہٕ آو ہارتھ کِس جنگلس منز۔\n6.\\tییلہ ساؤل بوٗز زِ داؤد آو دریافت کرنہٕ، تہٕ یِم نفر أمِس سٍتـ̡ ٲسۍ، (وۅنۍ اوس ساؤل رامہ کِس أکِس کُلِس تَل گبعاہس مَنٛز روزان، تٔمِس اتھس منز نیزٕ ٲس، تہٕ تٔمۍ سٕندِ سٲری خادم ٲسۍ أمِس اندۍ پکھۍ کھڑا ٲسۍ۔) {کُل...: یا، تھدِ جایہِ پیٹھ گروو}\n7.\\tتێلہِ ووٚن ساؤلن پننین خدمتگارن یُس تس اندۍ پکھۍ کھڑا اوس، بوزو اے بنیمی۔ یسی سُند نیچو دِیہ ژیہ سارِنٕے کھہٕ تہٕ انگور دِنہٕ، {تہٕ} بناوِ ژیہ سارِنٕے ساسہٕ بٔدۍ کپتان تہٕ ہتہٕ ہتن ہٕندِس کپتان۔\n8.\\tتہٕ یێلہِ سارِوٕے چُھہ میہ خٕلاف سٲزِش کٔرمٕژ، تہٕ {یێلہِ} چُھہ نہٕ کانہہ تہِ یُس میانہِ خٲطرٕ افسوس چُھ، تہٕ {یێلہِ} چُھہ نہٕ کانہہ تہِ یُس میانہِ خٲطرٕ افسوس چُھ، یا چُھہ مے ہاوان زِ میانہِ نیچِوِ چُھس میٲنِس خادمس خٕلاف ہنگامہ کورمُت، یُس انتظارس منز روزُن،  یتھ دۅہس پیٹھ؟ {شیوتھ...: ہیب۔ میون کَن کھولُن}\n9.\\tاَمہِ پَتہٕ دِیُت ڈوگ ادومی سُند جواب، یُس ساؤل سٕندِس نوکرَن پیٹھ تھونہٕ آمُت اوس، تہٕ وونُن، مے وُچھ یسیٰ سُند نیچو نوب، احیتوبُک نیچو اہیملیکس نِش یِوان۔\n10.\\tتہٕ تٔمۍ پرژھ خداوند سٕندِ خٲطرٕ، تہٕ دِتُن أمِس گولِتھ فلسطینی سٕنز تلوار۔\n11.\\tپتہٕ سوٗز بادشاہن احیمیلیکس پادٕر، احیتوبُک نیچو تہٕ تٔمۍ سٕندِس مٲلہِ سٕندِس سارِنٕے گرس سٍتـ̡ پادٕرۍ بُلاونہٕ خٲطرٕ، تہٕ تِم آیہ سارِنٕے بادشاہس نِش۔\n12.\\tتہٕ ساؤلن ووٚن، وۅنۍ بوزو، اے احیتوبُک نیچو۔ تہٕ تٔمۍ دیُت جواب، یتہٕ بہٕ چُھس، ماے لارڈ۔ {یتہِ...: ہیب۔ میہ وچھو}\n13. تہٕ ساؤلن ووٚن أمِس زِ ژے تہٕ یسیٰ سٕندِس نیچوِس کیازِ کٔر میہ خلاف سٲزِش زِ ژے چُھکھ أمِس روٹی تہٕ تلوار دِژمٕژ تہٕ خدایس نِش پرژھمُت زِ سُہ گژھہِ میہ خلاف کھڑا روزُن، یُتھ زن از دۅہہ انتظار کرُن؟\n14. اَمہِ پتہٕ دِیُت اَہِمِلِخن بادشاہس جواب تہٕ وونُن، تہٕ کُس چُھ تُہٕندِس سارِنٕے خادمَن مَنٛز وفادار یُس بادشاہ سُند زامتُر چُھ، تہٕ چُھہ تُہٕندِس حُکمس مُطٲبِق تہٕ تُہٕندِس گرس مَنٛز عزت تھاوان چُھ؟\n15.\\tکیا میہ کٔر امہِ پتہٕ خدایہ سٕندِ خٲطرٕ پرژھنہٕ یُن؟ یہ گژھہِ میہ نِش دور آسُن: بادشاہ گژھِ نہٕ پننِس خادمس سٍتـ̡ کانہہ تہِ چیز منسوب کٔرِتھ، {نۂ} میٲنس مٲلہِ سٕندِس سارِنٕے گرس سٍتـ̡ تہِ کیازِ تُہند خادم اوس نہٕ اتھ سارِنٕے سارِنٕے کِس بارس منز کانہہ تہِ خبر، کم یا زیادٕ۔ {کم...: ہیب۔ لوٚکُٹ یا بٔڑ}\n16.\\tتہٕ بادشاہن ووٚن زِ ژے گژھ یٔقیٖنی طور مرُن، اہیمیلک، تہٕ پننِس مٲلہِ سٕندِس سارِنٕے گرس سٍتـ̡ مَرُن۔\n17. تہٕ بادشاہن ووٚن أمِس أندۍ پٔکھۍ کھڑا پیدل پٔکۍ، پھیرِو تہٕ مٲرِن رب سٕندِ پادٕرۍ۔ تکیازِ تہند اتھہ تہِ چھہ ڈیوڈس سٍتۍ، تہ تمن ٲس پتاہ زِ سہ کر ژوٚل، تہ میہ ہٲوۍ نہ میہ کُن۔ مگر بادشاہ سٕندِ خادم ٲسۍ نہٕ خداوند سٕندِس پادٕرین پیٹھ پَنُن اتھہٕ تراونہٕ خٲطرٕ اتھہٕ تُلان۔ {پیدل آدمی: یا، گارڈ: ہیب۔ رنرز}\n18.\\tتہٕ بادشاہن ووٚن ڈوگس پھیرُن تہٕ پٔرِو پادٕرین پیٹھ۔ تہٕ ڈوگ ایڈومیٹ پھیُر تہٕ سُہ پیوٚو پادٕرین پیٹھ، تہٕ تمہ دۅہہ مارِن ژورہ تہٕ پانژھ نفر یِم کُنہِ کُنہِ ایفوڈ لٲگِتھ ٲسۍ۔\n19.\\tتہٕ نوب، پادٕرین ہُند شہر، تلوار ہٕندِس کنارس سٍتـ̡ لٔج أمِس مردس تہٕ زنانہٕ، شُرِ تہٕ دۄدٕ تہٕ دٲر تہٕ گَرٕ تہٕ کۅکرٕ تلوار ہٕندِ کنارٕ سٍتـ̡ مارنہٕ۔\n20.\\tتہٕ احیتوبس سُند نیچو احیمیلک سُند اکھ نیچو، یُس ابیاتھر ناو اوس، ژوٚل تہٕ ژوٚل داؤد سٕندِس پتہٕ۔\n21. تہٕ ابیاتھرن ہٲو داوُڈس زِ ساؤلن اوس خداوند سٕندِ پادٕرۍ مٲرِتھ مٲرِمٕتۍ۔\n22.\\tتہٕ داؤدن ووٚن ابیاتھرس زِ میہ ٲس تمہِ دۅہہ پتاہ ییلہ ڈوگ ادومی اتہِ اوس، سُہ کرِ یٔقیٖنی طور ساؤلس ونان: میہ چُھہ چانہِ مٲلہِ سٕندِس گرس ہٕندِس سارِنٕے نفرن ہُند مرُن۔\n23.\\tمیہ سٍتـ̡ روزُن، خوفہٕ مہٕ کرُن، یُس میانہِ زندگی ژھاران چُھ، سُہ چُھہ تُہٕنزِ زُو ژھاران مگر ژٕ روزٕ میانہِ سٍتـ̡ رٲچھ کٔرِتھ۔","1. پتہٕ ووٚن تِمو داؤدُس زِ وُچھِو فلسطینی کایلاہس سٍتـ̡ لڑان تہٕ تِم چھِ لُٹان۔\n2. تێمہِ کِنۍ پرژھ داؤد خداوند سٕندِس سٍتـ̡ پرژھہٕ زِ بہٕ گژھٕ یِمن فلسطینن مارٕ دِنہٕ؟ تہٕ خداوند ووٚن داؤدس زِ گژھ تہٕ فلسطینن مار دِیُن تہٕ کیلہ بچاون۔\n3. تہٕ داؤد سٕندٮ۪و نفرو ووٚن أمِس زِ وُچھِو أسۍ یَتہِ یہوداہَس مَنٛز کھوژان: تیلہِ کوتاہ زیادٕ یێلہِ أسۍ فلسطینن ہٕندِس لشکرس خلاف کیلہ یِو؟\n4. اَمہِ پَتہٕ کٔر داؤدَن بییہِ اکہِ لٹہِ خداوند سٕندِس نِش پرژھ۔ تہٕ خداوند دِیُت أمِس جواب تہٕ ووٚنُن، ووٚتھ، وُچھِو کیلہ کُن۔ تکیازِ بہٕ دِیہ فلسطینی پننس اتھس منز۔\n5.\\tیێلہِ گٔیہِ داؤد تہٕ تٔمۍ سٕندِس نفرس کٔرِتھ تہٕ لوٚگ فلسطینن سٍتـ̡ تہٕ أنِکھ تِہٕندِ چاروٲے تہٕ دِتُکھ تِمن سٍتـ̡ سٮ۪ٹھاہ ذبح کٔرِتھ۔ چنانچہ بچٲو ڈیوڈن کیلہ کین بسکین۔\n6.\\tتہٕ سپُد سپُد، ییلہ احیمیلک نیچو ابیاتھر داؤدس نِش کیلہ نِش ژوٚل، {یہ} ووت سُہ اتھس منز اکھ ایفوڈ ہٮ۪تھ۔\n7. تہٕ ساؤل آو وننہٕ زِ داؤد اوس کیلاہس نِش آمُت۔ تہٕ ساؤلن ووٚن، خداین چُھ سُہ میٲنس اتھس منز حوالہٕ کوٚرمُت۔ تکیازِ سُہ چُھ أکِس شہرس منز اژِتھ بند کرنہٕ آمُت یتھ منز دروازٕ تہٕ سلاخہٕ چھِ۔\n8. تہٕ ساؤلن بُلوو سارِنٕے لُکھ جنگہٕ خٲطرٕ، کیلاہس نِش گژھُن، داؤد تہٕ تٔمۍ سٕندِس نفرن محاصرٕ کرنہٕ خٲطرٕ۔\n9. تہٕ داؤدس ٲس پتاہ زِ ساؤل اوس ژوٗرِ پٲٹھـ̡ أمِس سٍتـ̡ شرارت کران۔ تہٕ تٔمۍ ووٚن پادٕرۍ ابیاتھرس زِ ایفود اَنِن۔\n10. اَمہِ پَتہٕ ووٚن داؤد، اے خدایہِ اِسرٲیلِی، تُہٕندِس خادمَس چُھ یٔقیٖنی پٲٹھـ̡ بوزمُت زِ ساؤل چُھ میانہِ خٲطرٕ شہر تباہ کرنہٕ خٲطرٕ یژھان۔\n11.\\tکیا کیلہ ہٕندِس مرد کٔرِن میہ پننِس اتھس مَنٛز؟ ساؤل گژھہِ بۄن، یُتھ زن چانہِ خادمَن بوزمُت چُھ؟ اے خدایہِ اسرٲیلُک خدا، بہٕ چُھس ژے گُزٲرِتھ زِ پنٕنِس خادمَس وَنُن۔ تہٕ خداوند ووٚن، سُہ گژھہِ بۄن وسُن۔\n12. تیلہِ ووٚن داؤد، کیا کیلاہٕکۍ مرد کٔرِن مے تہٕ میانین نفرن ساؤل سٕندِس اتھس مَنٛز؟ تہٕ خداوند ووٚن تِم دِیہِ تۅہہِ دِنہٕ۔ {ڈیلیور: ہیب۔ شٹ اپ}\n13.\\tتمہِ پتہ گٔیہِ داؤد تہٕ تٔمۍ سٕندِس نفر، یُس تقریباً شیہ ہتھ ٲسۍ، ووٚتھ تہٕ دراو کیلہ منزٕ نیرِتھ تہٕ گٔیہِ ییتہِ تِم گٔژھِتھ گٔیہِ۔ تہٕ ساؤل آو وننہٕ زِ داؤد اوس کیلہ نِش ژلان۔ تہٕ سُہ اوس نیبر نیرنس منع کران۔\n14.\\tتہٕ داؤد روٗد بیابانن مَنٛز مضبوٗط گٔژھتھ تہٕ روٗد زیف کِس بیابانس مَنٛز أکِس پہاڑس مَنٛز۔ تہٕ ساؤل اوس پریتھ دۅہہ أمِس ژھانڈان، مگر خداین کوٚر نہٕ سُہ پننِس اتھس منز۔\n15.\\tتہٕ داؤد وُچھ زِ ساؤل آو پننہِ جان ژھارنہِ نیبر، تہٕ داؤد اوس زیف کِس بیابانس مَنٛز أکِس جنگلس مَنٛز۔\n16. تہٕ جوناتھن ساؤل سُند نیچو ووٚتھ، تہٕ ووت داؤدس نِش جنگلَس مَنٛز، تہٕ کوٚرُن خدایس سٍتـ̡ پنُن اَتھٕ مضبوط۔\n17.\\tتہٕ تٔمۍ ووٚن أمِس زِ خوفہٕ نہٕ گژھُن، یێلہِ میانہِ مٲلہِ ساؤل سُند اتھہٕ میلہِ نہٕ۔ تہٕ ژٕ بنہٕ اسرائیلُک بادشاہ، تہٕ بہٕ آسہٕ ژےٚ پتہٕ۔ تہٕ ساؤل تہِ چُھ میون مول زانان۔\n18. تہٕ یِمو دۅشویو کوٚر خداوند سٕندِس برونہہ کُن اکھ عہد تہٕ داؤد گوو جنگلس مَنٛز، تہٕ جوناتھن گۆو پننِس گَرَس منز۔\n19.\\tاَمہِ پَتہٕ ووت زِفیتس ساؤلس نِش گبیعہ کِس نِش، یہِ وونُن زِ کیا داؤد چُھنہٕ اسہِ سٍتـ̡ جنگلَس مَنٛز، ہچیلہ کِس بالس مَنٛز، یُس یشیمون کِس جنوبس کُن چُھہ؟ {پیٹھ...: ہیب۔ دچھنہِ اتھس پیٹھ} {جیشیمون: یا، بیابان}\n20. وۅنۍ اے بادشاہ، پنہٕ نِس روحہٕ سٕنزِ سارِنٕے خواہشَس مُطٲبِق ؤسِو بۄن وسُن۔ تہٕ سون حصہٕ گژھہِ سُہ بادشاہ سٕندِس اتھس منز واتناوُن۔\n21.\\tتہٕ ساؤلن ووٚن، خداوند سٕندِ سٍتـ̡ بابرکت ہو، تکیازِ ژیہ چھکھ میہ پیٹھ رحم کران۔\n22.\\tگژھ میہ دُعا کرُن، تیٲری کٔرِتھ تہٕ وُچھِو تٔمۍ سٕنز جاے ییتہِ تٔمۍ سُند جاے چھُ، {تہٕ} کٔمۍ سُہ تتہِ وُچھمُت: کیازِ مے چُھ وننہٕ آمُت {زِ} سُہ چُھ سٮ۪ٹھاہ باریکی سان ورتاوان۔ {ہونٹ...: ہیب۔ کھۅر آسہِ}\n23.\\tتێلہِ وُچھِو تہٕ تِمن سارِنٕے جایَن ہُند علم نِش یێلہِ سُہ پانس ژوٗرِ روزان چُھ، تہٕ یێلہِ یێلہِ سُہ زمینس مَنٛز آسہِ، بہٕ گژھہٕ تس سارِنٕے ساسہٕ بٔدۍ یہوداہ سٍتـ̡ ژھانڈان۔\n24.\\tتہٕ تِم وٲتِتھ گٔیہِ ساؤلس برونہہ کُن زِف کُن، مگر داؤد تہٕ تٔمۍ سٕندِ نفر ٲسۍ یشیمون کِس جنوبس کِس مٲدانس مَنٛز ماعون کِس بیابانس مَنٛز۔\n25.\\tساؤل تہٕ تٔمۍ سٕندِ نفر گٔیہِ أمِس ژھانڈنہِ۔ تہٕ تِمو ووٚن داؤد: کیازِ ووت سُہ أکِس کَنہِ پتھرس منز، تہٕ روٗد ماون کِس بیابانس مَنٛز۔ تہٕ ییلہ ساؤلن بوٗز، سُہ لوٚگ ماون کِس بیابانس مَنٛز داؤدس پتہٕ۔ {into...: یا، کنہِ پیٹھ}\n26. تہٕ ساؤل گوٚو بالہٕ کِس اَتھ طرفہٕ، تہٕ داؤد تہٕ تٔمۍ سٕندِس نفرن کٔر بالہٕ کِس اَتھ طرفہٕ، تہٕ داؤد کٔر ساؤل سٕندِ خوفہٕ سٍتـ̡ ژلنہٕ خٲطرٕ جلدی ۔ تکیازِ ساؤل تہٕ تٔمۍ سٕندِس نفرو گٔیہِ داؤد تہٕ تٔمۍ سٕندِس نفرس اندۍ پکھۍ یِمن نِنہٕ خٲطرٕ۔\n27. مگر ساؤلس نِش آو اکھ قاصد یُس وونُن زِ جلدی کرو تہٕ یِو۔ تکیازِ فلسطینیو چھہ زمینس پیٹھ حملہ کوٚرمت۔ {حملہ...: ہیب۔ پنُن پان پھٔہلٲوِتھ وغیرہ}\n28.\\tتێلہِ آو ساؤل داؤدُک پَتہٕ واپس، تہٕ ووت فلسطینن خٕلاف، تێمہِ کِنۍ ووت تِمو اتھ جایہ سیلاہمہلیکوتھ۔ {سیلاہمہلیکوتھ: یعنی تقسیمن ہٕنز چٹ}\n29. تہٕ داؤد ووت تتہِ پیٹھ، تہٕ روٗد اینگیدی کِس مضبوٗط مقامس مَنٛز۔","1. تہٕ سپُد یہِ سپدُن، ییٚلہِ ساؤل فلسطینن ہٕندِس پٲٹھۍواپس آو دِنہٕ، یہِ آو أمِس وَننہٕ، وَنُن زِ داؤد چُھہ اینگیدی کِس بیابانس مَنٛز۔ {فالونگ: ہیب۔ پتہٕ}\n2. پتہٕ نیو ساؤلن سارِوٕے اسرٲیلِو منزٕ ترے ساس ژارنہٕ آمٕتۍ نفر، تہٕ گۆو داؤد تہٕ تٔمۍ سٕندِس نفرس جنگلی ژھاوٕن ہٕندِس پتھرس پیٹھ۔\n3.\\tتہٕ سُہ آو وتہِ کُنہِ گۅپھہِ منز۔ تہٕ ساؤل دراو پننین کھۅرن تھپھ کرنہٕ خٲطرٕ، تہٕ داؤد تہٕ تٔمۍ سٕندِ نفر روٗد غارہِ ہٕندِس اندس منز۔\n4. تہٕ داؤد سٕندیو لوکو ووٚن أمِس زِ سُہ دۅہ وُچھِو یُس خداوند ژے ووٚنمُت، وُچھ، بہٕ کٔرٕ تُہند دُشمن تہٕ تُہٕندِس اتھس مَنٛز، یُتھ تہٕ ژے کرٕ تٔمِس سٍتـ̡ یُتھ تہٕ ژے رژھرِ۔ امہ پتہ ووٚتھ ڈیوڈ تہ ژٹُن ساؤل سٕندِ پوشاکُک سکرٹ ژٹان۔ {ساؤل سُند...: ہیب۔ سُہ پوشاک یُس ساؤل سُند اوس}\n5. تہٕ امہ پتہ سپد یہ زِ داؤد سُند دِل دِل دِژ، تکیازِ تٔمۍ اوس ساؤل سُند سکرٹ ژٹمُت۔\n6. تہٕ تٔمۍ ووٚن پننین نفرن زِ خداوند چُھس منع کٔرِتھ زِ بہٕ کرٕ پننِس آقا سٕندِس مسح شدٕ سٍتـ̡ پنُن اتھہٕ تٔمِس سٍتـ̡ پھٔہلاونہٕ، یێلہِ سُہ چُھہ خداوند سُند مسح کرنہٕ آمُت۔\n7.\\tتێلہِ روٗد داؤد پَنٕنـ̡ خادمَن یِمن کلامَن سٍتـ̡ تہٕ دِتُن نہٕ تِم ساؤلس خلاف کھڑا گژھن۔ مگر ساؤل ووٚتھ گۅپھہِ منزہ نیبر تہ ووت پننہِ وتہِ۔ {روزُن: ہیب۔ کٹ آف}\n8.\\tداؤد تہِ ووٚتھ تہٕ گۅپھہِ منزہ نیبر تہٕ وونُن ساؤلس پتہٕ وۆنُن، میانہِ آقا بادشاہ۔ تہٕ ییلہِ ساؤلن پتھ کُن نظر دِژ، داؤد ووت زمینس کُن بُتھ تھٲوِتھ تہٕ نمُن۔\n9. تہٕ داؤدن ووٚن ساؤلس زِ ژے کیازِ چُھکھ انسانن ہٕنز کتھ بوزان تہٕ وُچھان داؤد چُھ تُہند دکھ ژھاران۔\n10.\\tوُچھ، از دۅہہ چُھہ تۅہہِ وُچھمُت زِ خداوند چُھہ ژے دۅہہ گۅپھِ مَنٛز میٲنس اتھس مَنٛز واتنوومُت: تہٕ {کینٛہہ} دِژ ژے مارُن، مگر {میانہِ أچھ} بچٲو ژےٚ۔ تہٕ میہ ووٚن، بہٕ کٔرٕ نہٕ پننِس مٲلکَس خلاف پنُن اتھہٕ۔ تکیازِ سُہ چُھ خداوند سُند مسح کرنہٕ آمُت۔\n11.\\tامہِ علاوٕ، میانہِ بابہ، وُچھ، آ، وُچھ چانہِ پوشہِ ہُند داکرٕ میٲنِس اتھس منز، کیازِ یێلہِ میہ ژٔٹِتھ تہٕ ژے ژے ژٔٹِتھ ژٔٹِتھ تہٕ وُچھکھ ژے سٍتـ̡ تہٕ وُچھُن زِ میٲنِس اتھس مَنٛز چُھنہٕ کانہہ بُرٕ تہٕ گُناہ تہٕ میہ چُھہ نہٕ ژے سٍتـ̡ گۅناہ کورمُت۔ توتہِ چھکھ میانہِ روحُک شکار کران زِ یہ رٹنہٕ خٲطرٕ۔\n12.\\tخداوند کرِ میانہِ تہٕ ژے درمِیان فٲصلہٕ، تہٕ خداوند کرِ میانہِ سٍتـ̡ انتقام، مگر میون اتھہٕ گژھہِ نہٕ توے پیٹھ۔\n13. یِتھ کٔنۍ زَن پرانین ہُند محاورہ چُھ ونان زِ بدکار چُھ بدکارن سٍتـ̡ نیران، مگر میون اتھہٕ گژھہِ نہٕ توے پیٹھ۔\n14.\\tاسرٲیلُک بادشاہ کٔمہِ پتہٕ چُھ نیران؟ کمہِ پتہٕ چھُکھ ژےٚ پَتہٕ لَگان؟ أکِس موٗدمٕتِس ہوٗنِس پتہٕ، پَتہٕ پَتہٕ۔\n15. تێمہِ کِنۍ گژھہِ خداوند فیصلہ تہٕ میانہِ تہٕ ژے درمِیان فیصلہ کرُن، تہٕ وُچھِو تہٕ میانہِ کامہِ ہٕنز وکالہٕ کرٕن، تہٕ کٔرِن مے پننہِ اتھہٕ نِش نجات دِنہٕ۔ {ڈیلیور: ہیب۔ جج}\n16.\\tتہٕ سپُد یێلہِ داؤد ساؤلس سٍتـ̡ یِم لفظ بولُن بند کٔرِتھ، ساؤلن ووٚن زِ کیا یہِ چُھہ تُہٕنز آواز، میانہِ نیچو داؤد؟ تہٕ ساؤلن کٔر آواز تُلتھ تہٕ رووُن۔\n17. تہٕ تٔمۍ ووٚن داؤدس زِ تہٕ ژٕ چُھکھ میانہِ کھوتہٕ زیادٕ نیک آسان، کیازِ ژے چُھس مےٚ نیکی انعامہٕ دِژمُت، یێلہِ زن مے چُھہ ژے بُرِس سٍتـ̡ دِژمُت۔\n18. تہٕ ژے چُھہ از ہٲومُت زِ ژے کِتھہ پٲٹھـ̡ چُھہ میہ سٍتـ̡ رژھ رٔٹمٕژ: یوتام یێلہِ خداوند میہ پننِس اتھس منز دِژمُت، تێہہ کٔر نہٕ مے مٲرِتھ۔ شٹ اپ}\n19.\\tیێلہِ یێلہِ کانہہ انسان پنُن دُشمن لبان چھُ، سُہ دِیہِ أمِس ژٔلِتھ؟ اَمہِ مۄکھٕ چُھہ خداوند ژے یُس ژے از میانہِ سٍتـ̡ کورمُت چُھ، سُہ چُھہ تۅہہِ سٍتـ̡ اَتھ سٍتـ̡ اَتھ سٍتـ̡\n20. تہٕ وُن، وُچھ، بہٕ چُھس پوٗرٕ پٲٹھـ̡ پتاہ زِ ژٕ بنہٕ یٔقیٖنی بادشاہ، تہٕ یہِ زِ اسرٲیلٕچ بادشاہت گژھہِ تۅہہِ ہٕندِس اتھس مَنٛز قایم کرنہٕ۔\n21. تێمہِ کِنۍ کٔرِو میہ خدایہِ سٍتـ̡ قسم، زِ ژٕ ژٕ ژٔٹِکھ نہٕ میانہِ پتہٕ میون بُل ژٹُن، تہٕ ژٕ کٔرٕ نہٕ میانہِ مٲلہِ سٕندِس گرٕ منزٕ میون ناو ختم کرنہٕ۔\n22. تہٕ داؤد کٔر شاؤلس سٍتـ̡ قسم۔ تہٕ ساؤل گوٚو گرٕ۔ مگر داؤد تہٕ تٔمۍ سٕندِ نفرو کٔر تِم رٔٹِتھ ۔","1. تہٕ سیموئیل موٗد۔ تہٕ سارِنٕے اِسرٲیلِیو جمع کٔرِتھ کٔرِکھ أمِس ماتم تہٕ کٔرِکھ راماہس مَنٛز پننِس گَرَس مَنٛز دفن۔ تہٕ داؤد ووٚتھ، تہٕ ووت پران کِس بیابانس منٛز۔\n2.\\tتہِ اوس ماونس منز اکھ شخژ، یمۍ سُند مال {اوس} کارملس منز۔ تہٕ أمِس اوس سٮ۪ٹھاہ بوٚڈ تہٕ أمِس ٲسۍ ترے ساس کۅکرِ تہٕ اکھ ساس ژھاوٕل: تہٕ سُہ اوس کارملس منز پنٕنۍ دانٛد کاسان۔ {ملکیت: یا، کاربار}\n3.\\tوۅنۍ چھہ امۍ سُند ناو {اوس} نبال۔ تہٕ تٔمۍ سٕنزِ زنانہٕ ابیگیل سُند ناو: تہٕ {سُہ} ٲس اصل سمجھ واجنہِ زنانہٕ، تہٕ خوبصورت شکلہٕ: مگر مرد اوس پننین اعمالن منٛز بدکار تہٕ بدکار ۔ تہٕ سُہ اوس کالب سٕندِس گرس منز۔\n4.\\tتہٕ داؤد بوز بیابانن منز زِ نابلن کٔر پنہٕ نِس کۅکرِ ژٹان۔\n5.\\tتہٕ داؤد سوٗزۍ داہ جوان تہٕ داؤد ووٚن نوجوانَن تہٕ نَبلس نِش گژھِو تہٕ میانہِ ناوٕ سٍتـ̡ سلام کٔرِو: أمِس پرژھ میانہِ امن کِس ناوس پیٹھ}\n6. تہٕ یِتھٕ پٲٹھۍ کٔرِو تُہۍ یُس زندٕ روزان چُھ، تہٕ تُہٕندِس گرس سٍتـ̡ امن تہٕ یێلہِ تہٕ سارِنٕے سٍتـ̡ آسُن سُلُن۔\n7.\\tتہٕ وُنہِ چُھس بوزمُت زِ ژے چُھہ ژٔرِتھ ژٔٹِتھ تہٕ یِمن ہٕندِس سٍتـ̡ أسـ̡ أسـ̡ تِمن دَگ دِنہٕ آمُت، یێلہِ سٍتـ̡ تِم کارملس مَنٛز ٲسۍ۔ {زخم: ہیب۔ شرمندہ}\n8. پننین جوانن پرژھو تہٕ تِم ہٲوِن تۅہہِ۔ اَمہِ مۄکھٕ گٔژھِو نوجوانَن پنہٕ نِس نظرن مَنٛز عنایت حٲصِل کرنہٕ، تِکیازِ أسۍ چھِ أکِس اصل دۅہہٕ یِوان: بہٕ چھُس دُعا کَران، یُس تہٕ یُس تہٕ تُہٕندِس اتھس مَنٛز یِیہ، تہٕ پننِس نیچوِس ڈیوڈس دِیُن۔\n9. تہٕ ییلہ داؤد سٕندِ جوان آیہ، تِمو کٔر داؤد سٕندِ ناوٕ سٍتـ̡ تِمن سارِنٕے لفظن مطٲبق نابلس سٍتـ̡ کتھ تہٕ بند گٔیہٕ۔ {بند: ہیب۔ آرام دِنہٕ آمُت}\n10.\\tتہٕ نابلن دیت داؤد سٕندِس خادمَن جواب تہٕ وونُن، داؤد کُس چُھ؟ تہٕ جیسی سُند نیچو کُس چُھ؟ از کل چھہِ واریاہ نوکر یم پریتھ انسان پننس آقا نِش ژٹان چھہِ۔\n11.\\tتیلہِ کیا بہٕ پنُن روٹ، پنُن آب تہٕ پنُن ماز یُس میہ پننین کاسنہٕ والٮ۪ن خٲطرٕ مارمُت چھُ، تہٕ دِیُس تِمن نفرن دِنہٕ یُس نہٕ بہٕ پتاہ چھُس زِ تِم کتہِ چھِ؟ {ماز: ہیب۔ ذبح}\n12.\\tتہ داؤد سٕندِ جوان پھیرۍ پنٕنـ̡ وَتھ تہٕ دُبارٕ گٔیہِ، تہٕ یِمو وَنُن تِم سارِنٕے کَلام۔\n13.\\tتہٕ داؤدن ووٚن پننین نفرن زِ پرتھ کٲنسہِ سٕنز تلوار لٲگِتھ۔ تہٕ تِمو لٲگِتھ پرٮ۪تھ أکِس شخصس سٕنز تلوار۔ تہٕ داؤد تہِ لوٚگ تلوار تھپھ کٔرِتھ، تہٕ داؤدس پَتہٕ ووت تقریباً ژور ہتھ نفر۔ تہٕ زٕ ہتھ روزن وٲلۍ۔\n14.\\tمگر أکۍ نوجوانَن ووٚن نابل سٕنزِ زنانہِ ابیگیلس ووٚن، وُچھِو داؤد سُہ بیابان منزٕ سٲنِس آقا سُند سلام کرنہٕ خٲطرٕ قاصد سوزمُت۔ تہٕ تٔمۍ کٔر تمن پیٹھ طنز کرنہٕ۔ {ریلڈ...: ہیب۔ تمن پیٹھ وٕڑن}\n15.\\tمگر مرد ٲسۍ اسہِ سٍتـ̡ سٮ۪ٹھاہ رٔٹۍ، تہٕ أسـ̡ أسـ̡ نہٕ کانہہ تہِ تکلیف دِنہٕ آمُت، یوتام أسـ̡ تِمن سٍتـ̡ وٲتِتھ ٲسِو، ییلہ أسـ̡ کھہس مَنٛز ٲسِو: {Hurt: Heb. شرمندہ}\n16.\\tتِم ٲسۍ رٲژ تہٕ دۅہہٕ سانہِ خٲطرٕ اکھ دیوار، سارِوٕے وقتس دوران أسۍ تِمن سٍتـ̡ دانٛد رچھان۔\n17. تێمہِ کِنۍ زانِو تہٕ غور کرو تہٕ غور کرو تہٕ کیا کرِ۔ تکیازِ بد کار چھہ سٲنِس آقا سٍتـ̡ تہٕ تٔمۍ سٕندِس سارِنٕے گرس سٍتـ̡ قایم کرنہٕ آمُت، تکیازِ سُہ چُھ بلیالُک نیچو یُس نہٕ أمِس سٍتـ̡ کتھ کٔرِتھ۔\n18.\\tاَمہ پتہٕ کٔر ابیگیلن جلدی تہٕ زٕ ہتھ روٹۍ، تہٕ زٕ بوتلہٕ شراب، تہٕ پانژھ کۅکرِ تیار تہٕ پانژھ کۅکرِ تہٕ کشمش ہٕندۍ ہتھ گٔنڈۍ، تہٕ زٕ ہتھ کۅکرِ تہٕ ترٲوٕن گَرَن پیٹھ۔ {کلسٹرس: یا، گانٹھ}\n19.\\tتہٕ تٔمۍ ووٚن پننین خادمَن ، گژھ میانہِ برونہہ کُن۔ وچھ بہٕ چُھس ژےٚ پتہٕ یوان۔ مگر تٔمۍ ووٚن نہٕ پننِس خانٛدارس نبال۔\n20.\\tتہٕ یێلہِ سُہ گَرِ سٍتـ̡ گٔیہِ سُہ بالہٕ کِس پوشہٕ پیٹھ، تہٕ وُچھِتھ داؤد تہٕ تٔمۍ سٕندِس نفر ؤسِتھ أمِس خٕلاف۔ تہٕ سۅ سمکھییہِ تمن سٍتۍ۔\n21.\\tوُن اوس داؤدُن ووٚنمُت، یُس سُہ {نفر} سُند سُہ سُہ چُھ بیابانن مَنٛز تھوومُت، یُتھ زن أمِس سٍتـ̡ {متعلق} سارِنٕے چیزن ہُند کانہہ تہِ ضایع سپدُن، تہٕ تٔمۍ کٔر میہ بُرُک بدلہٕ۔\n22. یێلہِ تہِ چُھہ خدا داؤد سٕندِس دُشمنن سٍتـ̡ تہِ یێلہِ بہٕ صُبحٕکہِ گاشہٕ سٍتـ̡ أمِس سٍتـ̡ سارِوٕے سٍتـ̡ یُس دیوارس سٍتـ̡ دٲیرٕ دِوان چُھس۔\n23. تہٕ ییلہ ابیگیلن داؤد وُچھ، سۅ کٔر جلدی تہٕ گٔیہِ گَرٕ تہٕ لٔگِن داؤدس برونہہ کُن بُتھِس پیٹھ، تہٕ پَنُن پان کٔرٕن زمینس پیٹھ۔\n24.\\tتہٕ پیوٚو تٔمۍ سٕندِس قدمن پیٹھ، تہٕ وونُن، میانہِ آقا، میہ کٔرِن یہِ بدکاری {آسُن} تہٕ بہٕ چُھس ژے دُعا کران زِ تہٕ پنٕنۍ خادمہ ہٕنز کتھ بوزٕنۍ۔ {سامعین: ہیب۔ کَن}\n25.\\tمیانہِ آقا، بہٕ چُھس ژے دُعا کران زِ یێلہِ سُند ناو {چُھ}، تِتھے پٲٹھـ̡ چُھہ سُہ {چُھ}۔ نابل چھُ تٔمِس سٍتـ̡ ناو، تہٕ بیوقوفی چُھہ أمِس سٍتـ̡ بێیہِ سٍتـ̡ سٍتـ� {حوالہٕ: ہیب۔ تٔمۍ سٕندِس دِلس پیٹھ تراوُن} {نابل: یعنی بیوقوف}\n26.\\tتێلہِ چُھہ یێلہِ خداوند زندٕ چُھ، تہٕ تێہُند روح چُھہ زندٕ، یێلہِ چُھہ خداوند ژے رُکٲوِتھ تہٕ پنہٕ نِس اتھہٕ سٍتـ̡ پنُن انتقام نِش رُکٲوِمُت، تێلہِ گژھہِ پَنٕنـ̡ دُشمن تہٕ یِم میانہِ آغہٕ سٍتـ̡ بد خواہشـ̡ کران چھِ، تِم گژھن نابل ہٕندۍ پٲٹھۍ۔ {انتقام...: ہیب۔ پنُن پان بچاوُن}\n27. تہٕ وۅنۍ یُس برکت چانہِ خاتونِ میٲنس آقاس تام دِژمُت چھُ، سُہ گژھہِ میانِس آقا سٕندِس پٲروی کرن والٮ۪ن نوجوانن تہِ دِنہٕ۔ {برکت: یا، موجود} {فالو...: ہیب۔ قدمن پیٹھ پکُن، وغیرہ}\n28.\\tبہٕ چُھس ژے دُعا کَران، پَنٕنـ̡ خانٛدارِ ہٕندِس گُناہ سٍتـ̡ معافی، یێلہِ خداوند بَناوِ یٔقیٖنی طور میٲنِس مٲلکَس پٲٹھـ̡ گرٕ۔ تکیازِ میون رب چُھ خداوند سٕندِس جنگس منز لڑان، تہٕ ژے چُھنہٕ سارِنٕے دۅہن منز بُرٕ لبنہٕ آمُت۔\n29. توتہِ چُھ اکھ انسان تُہند تعاقب کرنہٕ خٲطرٕ تہٕ تُہند روح ژھارنہٕ خٲطرٕ پٲدٕ گومُت، مگر میانہِ آقا سُند روح گژھہِ زندگی ہٕندِس بنڈلس مَنٛز خداوند تُہندس خداہس سٍتـ̡ بند۔ تہٕ چانہِ دُشمن ہٕندِ روحہٕ سٍتـ̡ سُہ ژٔلِتھ دِنہٕ یِنہٕ وٲلِس دُشمن ہٕندِس دُشمن ہ {یتھ کٔنۍ...: ہیب۔ اکھ غلیل ہینہٕ کس وسطس منٛز}\n30. تہٕ یێلہِ سپدِ یێلہِ خداوند میانہِ آقاس سٍتـ̡ تۅہہِ سٍتـ̡ یُس تُہٕندِس بارس مُتلق کتھ کٔرمٕژ آسہِ، تہٕ کرِ ژے اسرٲیلُک بادشاہ بنوو۔\n31.\\tیُس نہٕ تۅہہِ خٲطرٕ کانہہ غم، تہٕ نہ گژھِ میٲنِس آقا سٍتـ̡ دِل دِلُک جُرم، نَتہٕ ژے چُھہ بے وجہ خون، یا میانہِ آقا سُند بدلہٕ چُھ، مگر ییلہ خداوند میٲنِس مالہٕ سٍتـ̡ رٔٹِتھ سٍتـ̡ پَنُن دٲیرٕ یاد کرُن۔ {کانہہ غم: ہیب۔ کانہہ ٹھوکر کھسُن، یا ٹھوکر}\n32. تہٕ داؤدَن ووٚن ابیگیلَس یُس اسرٲیلُک خداوند خدا آسہِ، یٔمۍ ژے از دۅہہ مےٚ مِلنہٕ خٲطرٕ سوزمُت چھُ:\n33. تہٕ چُھہ چانہِ نصیحت تہٕ بابرکت {بٔن}، یٔمۍ میہ از دۅہہ خونس منز یِنہٕ نِش تہٕ پننِس اتھہٕ سٍتـ̡ انتقام نِش رُکٲو۔\n34.\\tیِتھ کٔنۍ زِ یێلہِ سٍتـ̡ چُھہ اسرٲیلُک خداوند زندٕ، یێمہِ سٍتـ̡ ژے ژے دِنہٕ نِش رُکٲوِتھ، یێمہِ سٍتـ̡ ژے جلدی کٔرِتھ میہ سمکھنہٕ آمُت، یێلہِ چُھہ نہٕ صُبحٕکہِ گاشہٕ سٍتـ̡ نَبلس سٍتـ̡ کانہہ تہِ یُس دیوارس سٍتـ̡ دِنہٕ آمُت آسہِ۔\n35.\\tیِتھٕ دٲیود روٚٹ تٔمۍ سُند اَتھٕ یُس أمِس أنِمُت اوس، تہٕ وونُن أمِس سُہ پنہٕ نِس گَرَس کُن۔ وچھ میہ چھیہ چانۍ آواز بوزمژ، تہ تہند شخص قبول۔\n36. تہٕ ابیگیل آو نابل۔ تہٕ وُچھ، تٔمۍ کٔر پننِس گرس منٛز اکھ دعوت، بادشاہ سٕندِ دعوتٕکۍ پٲٹھۍ۔ تہٕ نبالُن دِل اوس پانس اندر خۅش گومُت، تکیازِ سُہ اوس سٮ۪ٹھاہ شرابہٕ شرابس منز، اَمہِ مۅکھٕ اوس نہٕ تس صُبحہ گاشس تام کینہہ تہِ، کم یا زیادٕ۔\n37.\\tمگر یہ سپد صُبحہ ییلہ نابلس نش شراب نیبر نیرِتھ تہ تسنزِ زنانہِ ٲس تمس یہ کتھ وننہ آمژ، زِ تسند دل گۆو تس اندر مرُن، تہ سُہ بنیوو اکھ کنہِ۔\n38.\\tتہ گۆو دہن دہن دۅہن پتہ زِ خداوند دیت نابلس مار، سہ مرُن۔\n39.\\tتہٕ ییلہ داؤدس بوز زِ نابل چُھ موٗدمُت، تٔمۍ ووٚنُن، بابرکت خداوند یٔمۍ نابل سٕندِ اتھہٕ سٍتـ̡ میانہِ ملامت ہُند سبب دِژمُت تہٕ پننِس خادمس بد نِش بچٲومُت، کیازِ خداوند چُھ نابل سٕنز بدکاری پننِس کلس پیٹھ واپس کٔرمٕژ۔ تہٕ داؤدن سوٗز تہٕ کٔرٕن ابیگیلس سٍتـ̡ کتھ باتھ، سُہ نِنہٕ خٲطرٕ أمِس نِش خانٛدارِنہِ خٲطرٕ۔\n40. تہٕ ییلہ داؤد سٕندِ خادم ابیگیلس نِش کارملس نِش وٲتِ، تِمو کٔر أمِس سٍتـ̡ کتھ کرنہٕ، زِ داؤد سٕندِ سٍتـ̡ چُھہ اسہِ ژے نِش نِنہٕ خٲطرٕ۔\n41.\\tتہٕ سۅ ووٚتھ، تہٕ کٔرٕن زمینس کُن بُتھِس پیٹھ نمُن، تہٕ وونُن، وُچھ، {وُچھ} پنٕنۍ خادمہ بٔنِتھ میانہِ آقا سٕندٮ۪ن خادمن ہٕندِس کھۅر چھلنہٕ خٲطرٕ۔\n42.\\tتہٕ ابیگیل گٔیہِ جلدی تہٕ ووٚتھ تہٕ گٔیہِ أکِس گَرَس پیٹھ، یِم أمِس پَتہٕ پَتہٕ گٔیہِ۔ تہٕ سۄ گٔیہٕ داؤد سٕندِس رسولن پتہٕ، تہٕ بنییہٕ تٔمۍ سٕنز زنان۔ {تٔمۍ سٕندِ پتہٕ: ہیب۔ تٔمۍ سٕنٛدس قدمن پیٹھ}\n43.\\tداؤد تہِ نیو یزریلُک اہنوام۔ تہٕ تِم آسہٕ دۄشوے أمۍ سٕنٛزٕ خانٛدارِنہِ تہِ۔\n44.\\tمگر ساؤلن ٲس میخالس پنٕنۍ کوٗر داؤد سٕنز زنان لیش سٕندِس نیچوِس پھلتی یس دِژمٕژ، یُس گلیمُک اوس۔ {پھلٹی: تہٕ چُھ ونان، فالٹیئل}","1.\\tتہٕ زیفیتس آو ساؤلس نِش گبیعہس نِش یہ ؤنِتھ زِ کیا داؤد چُھ نہٕ یشیمون برونہہ کُن ہچیلہ کِس بالس مَنٛز ژوٗرِ روزان؟\n2. تمہ پتہ ووت ساؤل تہ ووت زیف کِس بیابانس منز، پانس سٍتـ̡ ترے ساس منتخب اسرٲیلِکۍ نفر ہٮ۪تھ، زیف کِس بیابانس مَنٛز داؤد سٕندِس سٍتـ̡ ژھانڈنہٕ خٲطرٕ۔\n3.\\tتہٕ ساؤل کٔر ہچِلہ کِس بالس منز، یُس یشیمون برونہہ کنہِ چھُ۔ مگر داؤد روٗد بیابانن مَنٛز، تہٕ وُچھ زِ ساؤل آو أمِس پتہٕ بیابانن منٛز۔\n4. اَمہِ مۄکھٕ سوٗزۍ داؤدَن جاسوٗس، تہٕ سوٗزِن زِ ساؤل اوس سٮ۪ٹھاہ عملہٕ سٍتـ̡ آمُت۔\n5. تہٕ داؤد ووت تہٕ ووت تتھ جایہِ ییتہِ ساؤل اوس دِژمُت، تہٕ داؤد وُچھ سُہ جاے یتہِ ساؤل اوس لوٚگمُت، تہٕ نیر سُند نیچو ابنیر یُس تٔمۍ سٕندِس لشکرُک کپتان اوس، تہٕ ساؤل لوٚگ خندقس مَنٛز، تہٕ لُکھ لٔگۍ أمِس اندۍ پٔکھۍ۔ {خندق: یا، تٔمۍ سٕنٛزن گاڑین منٛز}\n6. اَمہِ پَتہٕ دِیُت داؤدَس جواب تہٕ وونُن احیمیلِک حِتی، تہٕ زرویاہ سٕندِس نیچوِس ابیشایی یُس جوآب سُند بٲے اوس، وونُن، کُس گژھِ میانہِ سٍتـ̡ ساؤلس نِش خٲمس تام۔ تہٕ ابیشایی ووٚن بہٕ ژےٚ سٍتۍ بۄن۔\n7.\\tتہٕ داؤد تہٕ ابیشایی آیہِ رٲژ لُکن نِش۔ تہٕ وُچھِتھ اوس ساؤل خندقس منز شوٚنگِتھ تہٕ تٔمۍ سُند نیزٕ اوس تٔمِس سٕندِس کھورِ سٍتـ̡ زمینس مَنٛز بٔنِتھ، مگر ابنیر تہٕ لُکھ ٲسۍ أمِس اندۍ پٔکھۍ لٔگِتھ۔\n8.\\tاَمہِ پَتہٕ ووٚن ابیشایی داؤدَس زِ خداین دِژ از دۅہہ تُہند دُشمن تُہندس اتھس منز، تێمہِ مۅکھہ دِیُس بہٕ دُعا کٔرِتھ نیزٕ سٍتـ̡ زمینس سٍتـ̡ تہٕ بہٕ دِیہٕ نہٕ تس دوٚیمہِ لٹہِ مارٕ۔ {ڈیلیورڈ: ہیب۔ شٹ اپ}\n9. تہٕ داؤدَن ووٚن ابیشایی زِ أمِس کٔرِو نہٕ تباہ کٔرِتھ، تِکیازِ کُس ہیکہِ خداوند سٕندِس مسح کرنہٕ آمتس خلاف پنُن اتھہٕ بڑٲوِتھ، تہٕ کُس ہیکہِ بے گناہ ٲسِتھ؟\n10. داؤد ووٚن بییہِ زِ یێلہِ خداوند زندٕ چُھ، خداوند کرِ تس مار۔ نتہٕ گژھہِ تٔمۍ سُند دۅہ مرُن؛ نتہٕ گژھہِ سُہ جنگس منز وسِتھ مارُن۔\n11. خداوند چُھس منع کران زِ بہٕ کرٕ خداوند سٕندِس مسح شدٕ سٕندِس سٍتـ̡ پنُن اَتھٕ پھٔہلاونہٕ، مگر بہٕ چُھس ژے دُعا کٔرِتھ، سُہ نیزٕ یُس تٔمِس سٍتـ̡ چُھہ تٔمِس سٍتـ̡ تہٕ آبہٕ سٍتـ̡ رٔٹِتھ تہٕ أسـ̡ نیرُن۔\n12. یێمہِ کِنۍ نِیوو داؤدٕ ساؤل سٕندِس بُلسٹرس پیٹھٕ نیزٕ تہٕ آبہٕ ہُند کرُن۔ تہٕ تِمو کٔر تِم ژٔٹۍ، تہٕ کٲنسہ تہِ وُچھمُت {یہ} تہٕ نہ اوس خبر {یہ}، نہ بیدار: تکیازِ تِم ٲسۍ سٲری شوٚنگۍمٕتۍ۔ تکیازِ خداوند سٕندِ طرفہٕ گۆو تِمن سٍتـ̡ سٍتـ̡ س\n13.\\tپَتہٕ ووت دوٚیمہِ طرفہٕ تہٕ ووت دوٗر أکِس بالہٕ کِس تھزرس پیٹھ۔ تمن درمیان اکھ زبردست جاے {وجود}:\n14.\\tتہٕ داؤد کٔر لُکن تہٕ نیر سٕندِس نیچوِس ابنرس کُن وونُن زِ ژے چُھہ نہٕ جواب دِوان، ابنیر۔ اَمہِ پتہٕ دِیُت ابنیرن جواب تہٕ وونُن، ژٕ کُس چُھکھ بادشاہس فریاد کران؟\n15.\\tتہٕ داؤدن ووٚن ابنیرس زِ ژٕ چُھہ نہٕ بہادر انسان؟ تہٕ اسرٲیلِس مَنٛز کُس چُھہ تۅہہِ ہِش پٲٹھۍ؟ تیلہِ کیازِ تھوو نہٕ ژے پنُن آقا بادشاہ؟ تکیازِ تُہند آقا بادشاہ تباہ کرنہٕ خٲطرٕ آو اکھ لوکھ۔\n16.\\tیہ کتھ چھیہ نہ اصل یُس ژیہ کرمژ چھیہ۔ {یێلہِ}خداوند چُھہ زندٕ، تہٕ چُھہ تُہۍ مرنس لایق، کیازِ تێہہ چُھہ نہٕ پَنُن آقا رژھراونہٕ آمُت، یُس خداوند سُند مسح چُھ کرنہٕ آمُت۔ تہٕ وۅنۍ وچھ بادشاہ سُند نیزٕ کتہِ چُھ، تہٕ آبُک کۅکرُن یُس {اوس} تٔمۍ سٕندِس بولسٹرس پیٹھ۔ {مرنس لایق: ہیب۔ موتٕکۍ نیٚچو}\n17.\\tتہٕ ساؤلس ٲس داؤد سٕنز آواز زانان تہٕ وونُن، کیا یہ چُھہ تہنز آواز، میون نیچو داؤد؟ تہٕ داؤدن ووٚن، {یہِ} چھُ میٲنۍ آواز، اے بادشاہ۔\n18.\\tتہٕ تٔمۍ ووٚن، میون آقا کیازِ چُھ پننِس خادمس پَتہٕ پَکان؟ میہ کیا کوٚر میہ کیا؟ نتہ میٲنس اتھس منز کیا بد کار چھہ؟\n19.\\tتێلہِ چُھس بہٕ ژے دُعا کران زِ میانہِ آقا بادشاہ بوز پننِس خادمس سٕنز کلام۔ یێلہِ خداوند چُھہ ژے میانہِ خلاف ہنگامہ دِژمُت، تێلہِ گژھہِ سُہ نذرانہ قبول: مگر یێلہِ تِم انسانن ہٕندِ اولاد آسن، تِم گژھن خداوند سٕندِ برونہہ کُن لعنت۔ تِکیازِ تِمو چُھ مے از دۅہہ خداوند سٕندِس وراثتس منز روزنہٕ نِش کڑنہٕ آمُت، یہِ ونان زِ گژھ باقین دیوتاہن ہٕنز خدمت۔ {قبول: ہیب۔ بوش} {پٲٹھۍ: ہیب۔ کلیونگ}\n20. تێلہِ گژھہِ نہٕ میٲنۍ خوُن خداوند سٕندِس بُتھِس برونہہ کُن زمینہِ پیٹھ وسُن، تکیازِ اسرٲیلُک بادشاہ چُھ پسو ژھانڈنہٕ خٲطرٕ نیبر نیران، یِتھ پٲٹھۍ پہاڑن مَنٛز تیتر شکار کران چُھ۔\n21. اَمہِ پَتہٕ ووٚن ساؤل، مےٚ چُھ گۅناہ کورمُت: واپس، میانہِ نیچو داؤد، تکیازِ بہٕ کٔرٕ نہٕ ژے مزید نقصان واتناوُن، کیازِ میون روح اوس از تہِ چانہِ نظرِ خٲطرٕ قیمتی: وُچھ، بہٕ چُھس بیوقوفُک کردار ادا کورمُت، تہٕ سٮ۪ٹھاہ غلطی کٔرمٕژ۔\n22.\\tتہٕ داؤدَن دیُت جواب تہٕ وونُن، وُچھو بادشاہ سُند نیزٕ! تہٕ اکھ نوجوان یِن تہٕ اَنُن۔\n23. خداوند کٔر پرٮ۪تھ أکِس انسانس پنٕنۍ نیکی تہٕ تٔمۍ سٕنز وفاداری، یێلہِ خداوند چُھہ ژے از تہِ میانِس اتھس مَنٛز دِژمُت، مگر بہٕ کٔرٕ نہٕ خداوند سٕندِس مسح شدٕ سٕندِس خلاف پنُن اَتھٕ بڑاوُن۔\n24. تہٕ یێلہِ چُھہ تۅہہِ ہٕنزِ زندگی میانین نظرن منز از تام طے سپٕدمٕژ، تێلہِ گژھہِ میانہِ زندگی خداوند سٕنزِ نظرِ منز واریاہ طے کرنہٕ یُن، تہٕ سُہ گژھہِ مے سارِوٕے مصیبت نِش نجات دِنہٕ۔\n25. تێمہِ پَتہٕ ووٚن ساؤلَن داؤدَس مُبارکت، میانہِ نیچو داؤد، تێہہ کرٕ دۅشوے بٔڈ کامہِ تہٕ توتہِ گٔژھِو غالب۔ چنانچہ داؤد پوٚک وتہِ تہٕ ساؤل آو پننہِ جایہ واپس۔","1. تہٕ داؤد ووٚن پننِس دِلس مَنٛز، بہٕ گژھہٕ اکہِ دۅہہ ساؤل سٕندِ اتھہٕ سٍتـ̡ مارٕ: {بہٕ چُھہ نہٕ بہٕ بہٕ جلدی فلسطینن ہٕندِس سرزمینس مَنٛز ژلُنـ̡ بێیہِ۔ تہٕ ساؤل گژھِ میانہِ نِش مایوس، یُس اسرٲیلِس کِس کُنہِ تہِ ساحلس منز میہ ژھانڈنہٕ خٲطرٕ تہٕ بہٕ ژلہٕ بہٕ تٔمۍ سٕندِ اتھہٕ نِش نیرُن۔ {ختم: ہیب۔ کھٮ۪نہٕ یِن}\n2. تہٕ داؤد ووٚتھ، تہٕ سُہ ووت شیہ ہتھ نفرن سٍتـ̡ یِم أمِس سٍتـ̡ ٲسۍ، یُس گاتھ کِس بادشاہ ماوخ سٕندِس نیچوِس آچِش نِش اوس۔\n3.\\tتہٕ داؤد اوس گاتھس مَنٛز اکیشس سٍتـ̡ روزان، سُہ تہٕ تٔمۍ سٕندِس مردس سٍتـ̡ ، پرٮ۪تھ کانہہ مرد پننِس گرس سٍتـ̡ ، حتیٰ کہ داؤد پنہٕ نـ̡ دۅن زنانن سٍتـ̡ تہٕ ابیگیل کارمیلیتس سٍتـ̡ یُس نابل سٕنزِ زنانہٕ سٍتـ̡ روزان اوس۔\n4. تہٕ ساؤل آو وننہٕ زِ داؤد ژوٚل گاتھ کُن، تہٕ تٔمۍ اوس نہٕ بییہِ أمِس خٲطرٕ دُبارٕ ژھانڈان۔\n5.\\tتہٕ داؤدن ووٚن اچیشس زِ اگر میہ وۅنۍ چانہِ نظرن منز فضل میلہِ، تِم دِژن میہ کُنہِ دیس منز کُنہِ شہرس مَنٛز جاۓ، یُتھ بہٕ روزُن، تکیازِ تُہند خادم کیازِ روزِ ژے سٍتـ̡ شٲہی شہرس مَنٛز۔\n6.\\tاَمہ دۅہہ دِژ اَمہ دۅہہ زِکلاگ زِکلاگ تہٕ اَمہ دۅہہ چُھ یہوداہ کِس بادشاہن سٍتـ̡ ۔\n7. تہٕ یُس وقت داؤد فلسطینن ہٕندِس ملکس منز روزان اوس، سُہ اوس پورٕ ؤری تہٕ ژور ریتھ۔ {وقت: ہیب۔ دۅہن ہند تعداد} {اکھ پورہ ؤری: ہیب۔ دۄہن ہُنٛد اکھ ؤری}\n8.\\tتہٕ داؤد تہٕ تٔمۍ سٕندِس نفرو گٔیہِ ہیوٚر تہٕ گیشورِیَن تہٕ عزریَن تہٕ امالیکین پیٹھ حملہٕ، تِکیازِ تِم قومہٕ ٲسۍ پرانہِ زمانہٕ زمینہٕ کِس بسکین، یِتھ کٔنۍ تُہۍ شورس کُن گژھان چھِ، حتیٰ کہ مصر کِس سرزمینس تام تہِ۔ {Gezrites: یا، Gerzites}\n9.\\tتہٕ داؤدَن دِژ زمینہٕ تہٕ کٔرٕن نہٕ مرد تہٕ زنانہٕ زِندٕ، تہٕ نِیُن دانٛدٕ، تہٕ گَرٕ تہٕ اونٹ، تہٕ پَلَو نِتھ واپس، تہٕ آو آچِش کُن۔\n10.\\tتہٕ اَچِشَن ووٚن، ژے کتہِ وَتھ بَنوومٕژ؟ تہٕ داؤد ووٚن یہوداہ کِس جنوبس خلاف، تہٕ یرہمیلیٹس کِس جنوبس خلاف، تہٕ کینیٹس کِس جنوبس خلاف۔ {کتہِ...: یا، کیا ژیہ بَنوو نہٕ وَتھ وغیرہ}\n11.\\tتہٕ داؤدن بچٲو نہ مرد تہٕ زنانہِ زندٕ، یُس گاتھس تام خبر دِنہٕ مۅکھہٕ وَنُن تہٕ وونُن زِ تِم گژھن اسہِ کُن ونُن، تہٕ یِتھے پٲٹھۍ روزِ تٔمۍ سُند طریقہٕ یُس سُہ فلسطینن ہٕندِس ملکس منز روزان آسہِ۔\n12.\\tتہٕ آکیشَن کٔر داؤدُس پٲٹھۍ، یہِ وَنُن زِ تٔمۍ بنوو پَنٕنـ̡ قوم اِسرٲیلِس سٍتـ̡ تٔمِس سٍتـ̡ نفرت کرنہٕ خٲطرٕ۔ تَمہِ مۄکھٕ روزِ سُہ ہمیشہٕ خٲطرٕ میون خادم۔ {بلکل ...: ہیب۔ بدبو}","1. تہٕ تِمن دۅہن سپد یہ زِ فلسطینیو کٔر اسرٲیلِس سٍتـ̡ لڑنہٕ خٲطرٕ پنٕنۍ فوج جمع کرنہٕ۔ تہٕ اَچِشَن ووٚن داؤدَس زِ ژٕ گژھِو پَکہٕ پٲٹھۍ، ژٕ تہٕ تُہٕندِس نفرَس سٍتـ̡ میہ سٍتـ̡ جنگہٕ خٲطرٕ نیرِو۔\n2.\\tتہٕ داؤدَن ووٚن اَچِشَس زِ یٔقیٖنی پٲٹھـ̡ ژے پتاہ زِ تُہند خادم کیا ہیکہِ کٔرِتھ۔ تہٕ اچیشَن ووٚن ڈیوڈس، تَمہِ مۄکھٕ بناوٕ بہٕ ژے ہمیشہٕ خٲطرٕ پنُن کلہٕ رٲچھ کَرُن۔\n3.\\tوۅنۍ اوس سموئیل موٗدمُت، تہٕ سارِوٕے اسرٲیلَن اوس أمِس ماتم کٔرِتھ، تہٕ کورُن راماہس مَنٛز تہٕ پننِس شہرس مَنٛز تہِ دفن۔ تہٕ ساؤلن کٔر تِم یِم واقف روح ٲسۍ، تہٕ جادوگر ٲسۍ زمینہٕ نِش نیبر کٔرۍمٕتۍ۔\n4. تہٕ فلسطینیو جمع کٔرِتھ آے شونیمس مَنٛز تہٕ ساؤلن کٔر سارِنٕے اسرٲیلِس جمع تہٕ تِمو کٔر گلبواہس مَنٛز۔\n5.\\tتہٕ ییلہ ساؤلن فلسطینن ہُند لشکر وُچھ، سُہ گوٚو کھوژُن، تہٕ تٔمۍ سُند دِل لوٚگ سٮ۪ٹھاہ تھرتھر۔\n6. تہٕ ییلہ ساؤلن خداوند سٕندِ سٍتـ̡ پرژھہ، خداوند دیُت نہٕ أمِس جواب، نہ خوابو سٍتـ̡ تہٕ نہ اُرِم سٍتـ̡ تہٕ نۂ پیغمبرن سٍتـ̡ ۔\n7. اَمہِ پَتہٕ ووٚن ساؤلَن پننِس خادمَن سٍتـ̡ ژھٲنڈِتھ یُس اکھ مانوس روح آسہِ، یُتھ بہٕ أمِس نِش گژھِتھ پرژھہٕ گٲر کٔرِتھ۔ تہٕ تٔمۍ سٕندٮ۪و نوکرو ووٚن أمِس وُچھ، {وُچھ} اکھ زنانہٕ چھے ییمِس اینڈورس منز اکھ مانوس روح چُھ۔\n8.\\tتہٕ ساؤلن لوٚگ پان پوش تہٕ لوٚگ بیاکھ پَلَو، تہٕ سُہ گوٚو تہٕ أمِس سٍتـ̡ زٕ نفر تہٕ تِم آیہِ رٲژ زنانہِ نِش۔ تہٕ تٔمۍ ووٚن، بہٕ چُھس ژے دُعا کٔرِتھ، یُس مانوس روحہٕ سٍتـ̡ خدایہِ سٍتـ̡ تہٕ اَنـ̡ سُہ یُس بہٕ ژے ناو دِیہٕ۔\n9.\\tتہٕ زنانہِ ووٚن أمِس زِ وُچھ، ژے چھے پتاہ زِ ساؤلن کیا کوٚر تہٕ کِتھہ کٔنۍ چھُ أمِس زمینہٕ منزٕ یِمن ہٕندِس روحس تہٕ جادوگر ژٹِتھ ژٔٹۍمٕتۍ، تیلہِ کیازِ چُھکھ ژے میانہِ زِندٕ خٲطرٕ جال تراوُن، یُس میہ مرُن دِنہٕ خٲطرٕ؟\n10.\\tتہٕ ساؤل چُھ أمِس خداوند سٕندِ سٍتـ̡ قسم دِوان زِ یێلہِ خداوند زندٕ چُھ، تێلہِ گژھہِ نہٕ تۅہہِ سٍتـ̡ امہِ کتھہِ ہُند کانہہ عذاب۔\n11.\\tزنانہِ ووٚن، بہٕ کُس کرٕ ژےٚ نِش؟ تہٕ تٔمۍ ووٚن، مے أنِو سیموئیل۔\n12. تہٕ ییلہِ زنانہِ سموئیلس وُچھ، سُہ وُچھ بَڑِ آوازِ سٍتـ̡ تہٕ زنانہِ ووٚن ساؤلس سٍتـ̡ کتھ زِ ژے کیازِ چُھکھ میہ دھوکہٕ دِژمُت؟ تُہٕندِ خٲطرٕ چُھہ ساؤل۔\n13.\\tتہٕ بادشاہن ووٚن أمِس زِ خوفزدہ گژھ نہٕ، ژے کمہِ خٲطرٕ؟ تہٕ زنانہِ ووٚن ساؤلس زِ میہ وچھ دیوتا زمینہِ منزہ کھسان۔\n14.\\tتہٕ تٔمۍ ووٚن أمِس کَمہِ شکلہِ ہُند؟ تہٕ تٔمۍ ووٚن، اکھ بُزرگ آو ووٚتھ؛ تہٕ سُہ چُھ پوشہٕ سٍتۍ ؤلِتھ۔ تہٕ ساؤلن وُچھ زِ یہِ اوس سموئیل، تہٕ سُہ ووٚتھ بُتھ زمینس کُن تہٕ نمُن۔ {کیا...: ہیب۔ تہنز شکل کیا چِھ؟}\n15. تہٕ سموئیلن ووٚن ساؤلس زِ ژے کیازِ چُھہ میہ پرورش کرنہٕ خٲطرٕ پریشان کٔرتھ؟ تہٕ ساؤلن دیُت جواب، بہٕ چُھس پریشان گومُت۔ تکیازِ فلسطینی چھہ میہ خلاف جنگ کران، تہٕ خدا چُھ میہ نِش دور گومُت، تہٕ چُھہ نہٕ میہ جواب دِوان، نہ پیغمبرن سٍتۍ، تہٕ نہ خوابن سٍتۍ، تێلہِ چُھس مے ژے بُلاونہٕ آمُت، یێلہِ تہٕ ژٕ ہێکہٕ مے زانہٕ زِ بہٕ کیا کرُن، {پیغمبرن ہٕندِ ذریعہٕ: عبرانی۔ پیغمبرن ہٕندِ اتھہٕ سٍتۍ}\n16. تیلہِ ووٚن سموئیل، تێلہِ کیازِ چُھکھ ژے میہ منگان، یێلہِ چُھہ خداوند ژے نِش ژۆٹمُت تہٕ چُھہ تُہند دُشمن بنیومُت؟\n17. تہٕ خداوند چُھ أمِس سٍتـ̡ یِتھٕ پٲٹھۍ میانہِ سٍتـ̡ کتھ کٔرمٕژ، کیازِ خداوند چُھہ تُہندِ اتھہٕ نِش بادشاہت ژٔٹِتھ تہٕ دِژُن تُہٕندِس ہمساین تہٕ دِژُن داؤدس سٍتـ̡ {أمِس سٍتـ̡: یا پانس خٲطرٕ} {مے: ہیب۔ ماین ہینڈ}\n18.\\tکیازِ ژے کٔر نہٕ خداوند سٕنزِ آوازِ ہٕنز فرمانبرداری تہٕ نہ کٔرٕکھ امالیکَس پیٹھ تٔمۍ سُند شدید قہر تہٕ، تێلہِ چُھ خداوند سٕندِ سٍتـ̡ از تہِ یہِ کٲم کٔرمٕژ۔\n19. امہِ علاوٕ کرِ خداوند اسرٲیلِس پانس سٍتـ̡ فلسطینن ہٕندِس اتھس مَنٛز، تہٕ پَتہٕ تہٕ تُہٕندِس نیٚچوِس رٔٹِتھ روزُن: خداوند تہِ دِیہِ اسرٲیلُک لشکر فلسطینن ہٕندِس اتھس مَنٛز۔\n20. پَتہٕ پیوٚو ساؤل سٲرۍسٕے زمینس پیٹھ، تہٕ سموئیل سٕندِ کلامَس سٍتـ̡ کھوژُن تہٕ أمِس مَنٛز اوس نہٕ کانہہ طاقت۔ تکیازِ تٔمۍ اوس نہٕ سارِوٕے دۅہس تہٕ نہ سارِوٕے رٲژ کانہہ روٹی کھیوٚمٕژ۔ {گٔیہِ...: ہیب۔ جلدی کٔرِتھ پیوٚو تہٕ پنہٕ نِس قدس سٍتۍ پیوٚو\n21.\\tتہٕ زنانہٕ آیہِ ساؤلس نِش، تہٕ وُچھن ساؤلس نِش تہٕ وُچھُن تٔمِس دَگ دِنہٕ آمُت، تہٕ وُچھُن تۅہہِ ہٕنزِ کتھہِ ہٕنز اطاعت کٔرمٕژ، تہٕ مے چُھس پنُن زُو پننِس اتھس مَنٛز تھوومُت، تہٕ چُھس تُہٕنز کتھ بوزمٕژ یُس ژے میانہِ کُن کتھ کٔرِ۔\n22.\\tتێلہِ چُھس بہٕ ژے دُعا کران زِ ژے تہِ بوز پننہِ نوکری ہٕنز آواز تہٕ بہٕ تھاوُن ژے برونہہ کُن اکھ ٹُکر۔ تہٕ کھیٛو، یُتھ تہٕ ژٕ گژھہٕ طاقت حٲصل، ییلہٕ تہٕ تہٕ پننہٕ وتہٕ پیٹھ نیرِو۔\n23.\\tمگر تٔمۍ کوٚر اِنکار تہٕ ووٚنُن بہٕ کھٮ۪نہٕ نہٕ۔ مگر أمۍ سٕنٛدٮ۪و خادمَو کٔر زنانہِ سۭتۍ رٔلِتھ أمِس مجبور۔ تہٕ تٔمۍ بوز تہنز آواز۔ تہ ووٚتھ زمینہِ پیٹھ، تہ بیوٹھ بسترس پیٹھ۔\n24.\\tتہٕ زنانہِ ہٕندِس گَرَس مَنٛز اوس اکھ موٚٹ بَچھرٕ ۔ تہٕ تٔمۍ کٔر جلدی تہٕ مٲرِتھ تہٕ رٔٹِتھ تہٕ کٔرٕن اَمہ سٍتۍ خمیر روٚس روٹی بٔنِتھ:\n25.\\tتہٕ سُہ اوٚن ساؤلس برونہہ کُن تہٕ تٔمۍ سٕندِس خدمتگارن برونہہ کُن۔ تہٕ تِمو کٔر کھٮ۪وان۔ تمہ پتہ ووٚتھ تہ تمہ رٲژ ژٔلۍ۔","1. وۅنۍ کٔر فلسطینیو پنٕنۍ تمام فوج افیکس کُن جمع تہٕ اسرائیلیو کٔر أکِس چشمہٕ سٍتـ̡ یُس یزریلس مَنٛز {چُھ}۔\n2. تہٕ فلسطینی ہٕندِس مٲلکَس گٔیہِ ہتہٕ بٔدۍ تہٕ ساسہٕ بٔدۍ، مگر داؤد تہٕ تٔمۍ سٕندِس نفرس گٔیہِ اَچِش سٍتـ̡ انعامس سٍتـ̡ ۔\n3.\\tاَمہِ پَتہٕ ووٚن فلسطینن ہٕندِس شہزادو زِ یِم عبرانیو کیا چُھہ یِمن عبرانیو {یتہِ} کٔرِتھ؟ تہٕ آچِشَن ووٚن فلسطینن ہٕندِس شہزادن سٍتـ̡ {کیا یہِ داؤدُن، یُس اسرٲیلُک بادشاہ ساؤل سُند خادم چُھ، یُس از تام میہ سٍتـ̡ اوس، تہٕ مے چُھہ نہٕ تس مَنٛز کانہہ عیب لبنہٕ آمُت؟\n4.\\tتہٕ فلسطینن ہٕندِ شہزادن ہٕندِس شہزادس گٔیہِ أمِس سٍتـ̡ شرارت۔ تہٕ فلسطینی شہزادو ووٚن أمِس زِ یہِ نفر واپس، یُتھ سُہ گژھِ دُبارٕ پننہِ جایہِ یُس ژے أمِس مقرر کورمُت چھُ، تہٕ سُہ گژھہِ نہٕ اسہِ سٍتۍ جنگس منز گژھُن، نتہٕ جنگس منز بنہِ سُہ اسہِ ہُند مُخٲلف: کیازِ سُہ کرِ پننِس مٲلکَس سٍتۍ صلح کرنہٕ۔ {یِمَن نفرَن ہٕندِس کَلَس سٍتۍ گژھِ نہٕ یہِ {آسُن}؟\n5.\\tکیا یہِ چھُنہٕ داؤد، یٔمِس مُتلق تِمو رقصَس مَنٛز اَکھ أکِس سٍتـ̡ گیوُن، یہِ ونُن زِ ساؤلن مٲرِتھ پَنٕنـ̡ ساسہٕ بٔدۍ تہٕ داوُد سٕندِ دَہ ساس؟\n6.\\tاَمہ پَتہٕ بُلوو داؤدُس تہٕ وونُن، یێلہِ چُھہ خداوند زندٕ چُھ، تہٕ تێہُند نیرُن تہٕ میٲنۍ سٍتـ̡ یِنہٕ سٍتـ̡ چُھہ میانہِ نظرِ سٍتـ̡ خیر ، کیازِ ژے یِنہٕ کہِ دۅہہٕ پیٹھٕ چُھہ نہٕ ژے سٍتـ̡ بُرٕ وُچھمُت، توتہِ چُھہ نہٕ خداوند تۅہہِ سٍتـ̡ احسان کٔرِتھ۔﴿  ہیب۔ تُہۍ چھِو نہٕ لارڈن ہٕنزِ نظرِ منز اصل}\n7. اَمہِ مۄکھٕ گژھ وُنہِ واپس، تہٕ امن سان گژھِو، یُتھ نہٕ ژے فلسطینن ہٕندِس آقا سٍتـ̡ ناراض گٔژھِو۔ {ناپسندید...: ہیب۔ مالہٕ سٕندِس نظرس منز گژھ نہٕ بُرٕ کرُن}\n8.\\tتہٕ داؤدن ووٚن اچیشس مگر میہ کیا کورمُت؟ تہٕ ژے کیا لوٚب پننِس خادمس منز یوت تام بہٕ از تام ژے سٍتۍ روزمُت، یُتھ بہٕ ہیوٚک نہٕ پننِس آقا بادشاہ سٕندِس دُشمنن خلاف لڑنہٕ یِتھ؟ {with...: Heb. ژے برٛونٛہہ}\n9.\\tتہٕ اَچِشَن دِیُت جواب تہٕ ووٚنُن داؤد، بہٕ چُھس پتاہ زِ ژٕ چُھکھ میانہِ نظرِ منز خدا سُند فرشتہٕ سٕندِ پٲٹھۍ، باوجوٗد تہِ چُھہ فلسطینن ہٕندِس شہزادن ووٚنمُت زِ سُہ گژھِ نہٕ اسہِ سٍتـ̡ جنگس منز واتہِ۔\n10. لہذا وۅنۍ وُتھٕ صبحٲے پنہٕ نِس آقا سٕندٮ۪ن خدمتگارن سٍتـ̡ یِم پانس سٍتـ̡ یِنہٕ وٲلۍ، تہٕ یێلہِ سُلہٕ سُلہٕ وُتھِتھ تہٕ گاش گژھِو، نیرُن۔\n11. تہٕ داؤد تہٕ تٔمۍ سٕندِ نفر ووٚتھ صبحٲے نیرنہٕ خٲطرٕ، فلسطینن ہٕندِس ملکس منز واپس گژھنہٕ خٲطرٕ۔ تہٕ فلسطینی گٔیہِ یزریلس تام۔","1.\\tتہٕ ییلہ داؤد تہٕ تٔمۍ سٕندۍ نفر تریمہِ دۅہہ زِکلاگ آیہ، زِ امالیکیو اوس جنوبس تہٕ زِکلاگ کِس جنوبس پیٹھ حملہٕ کورمُت تہٕ زِکلاگ کٔرِکھ نارٕ سٍتـ̡ زالنہٕ۔\n2.\\tتہٕ ٲسٕکھ زنانہٕ قٲد کٔرمٕژ، یِم {آسہٕ} اَتھ منٛز: تِمو مٲرِکھ نہٕ کانٛہہ تہِ، بٔڑ یا لۄکٕٹ، مگر تِم نِتھ گٔیہِ پننہِ وتہِ پٮ۪ٹھ۔\n3. تہٕ داؤد تہٕ تٔمۍ سٕندِ نفر آیہِ شہرس مَنٛز، تہٕ وُچھِتھ آو یہِ نارٕ سٍتـ̡ زالنہٕ۔ تہٕ تِہٕنٛزٕ خانٛدارِنہٕ، تہٕ تِہٕنٛدۍ نیٚچوۍ، تہٕ تِہٕنٛزِ کورِ آیہ قٲد کرنہٕ۔\n4. پَتہٕ داؤد تہٕ أمِس سٍتـ̡ لُکھ تُل آواز تہٕ رووُن، یوتام نہٕ تِمن روونُک طاقت ہیوٚت۔\n5.\\tتہٕ داؤد سٕنزِ زٕ زنانہٕ آیہ قٲد کرنہٕ، احینوم یزریلیٹس تہٕ ابیگیل یُس نابل کارمیلیٹ سٕنز زنانہٕ ٲس۔\n6. تہٕ داؤد گوٚو واریاہ پریشان۔ تکیازِ لوکو کٔر أمس سنگسار کرنٕچ کتھ، تکیازِ سارنٕے لوکن ہُند روح اوس غمگسار گومُت، پرٮ۪تھ کانہہ انسان اوس پننین نیچوین تہٕ کورِ خٲطرٕ، مگر داؤدن کٔر پانس خداوند پننس خداہس منز حوصلہٕ افزٲیی۔ {غمگین: ہیب۔ تلخ}\n7.\\tتہٕ داؤدَن ووٚن پادٕرۍ ابیتھر، اہیمیلک سٕندِس نیچوِس بہٕ چھُس ژے دُعا کٔرِتھ، اَنُن میہ یور ایفود۔ تہٕ ابیاتھر اوٚن تتہِ ایفوڈ داوڈس نِش۔\n8. تہٕ داؤد پرژھ خداوند سٕندِس پَتہٕ؟ بہٕ کیا تمن پتھ کُن نیرُن؟ تہٕ تٔمۍ دیُت أمِس جواب، تعاقب کرُن: تکیازِ تۅہہ گژھہِ یقینا تمن پیٹھ قبضہ کرُن، تہٕ بغٲر ناکام سپدِو {سارِنٕے}۔\n9.\\tتہٕ داؤد گۆو سُہ تہٕ شیہ ہتھ نفر یِم أمِس سٍتـ̡ ٲسۍ، تہٕ وٲتِتھ بیسورس کُن، یتہِ یِم پتھ کُن روزان ٲسۍ۔\n10.\\tمگر داؤد لوٚگ سُہ تہٕ ژور ہتھ نفر: زٕ ہتھ نفرن پَتہٕ روزنہٕ خٲطرٕ، یِم تیوٗت بے ہوش ٲسۍ زِ تِم ہیوٚک نہٕ نالہٕ بیسورس اپارِ گٔژِھتھ۔\n11.\\tتہٕ تِمو لوٚب کھاہس مَنٛز اکھ مصری، تہٕ أنِن سُہ داؤدَس نِش، تہٕ دِتُن تٔمِس روٹی تہٕ تٔمِس کھیوٚن۔ تہٕ تمو دیت تس آب چیوان۔\n12.\\tتہٕ تِمو دِژ أمِس انجیر ہُند اکھ ٹُکرٕ تہٕ کشمشٕکۍ زٕ گٔرۍ، تہٕ ییلہ تٔمۍ کھیوٚو، تٔمۍ سُند روح آو أمِس نِش، تکیازِ تٔمۍ اوس نہٕ کانہہ روٹی کھیوٚمُت، تہٕ نہ اوس تریہ دۅہ تہٕ تریہ رٲژ آب چیوٚمُت۔\n13. تہٕ داؤدن ووٚن أمِس زِ تُہۍ کٔمِس سٍتـ̡ چُھہ؟ تہٕ ژے کتہِ چھُ؟ تہٕ تٔمۍ ووٚن، بہٕ چُھس مصرُک اکھ نوجوان، أکِس امالیقی سُند خادم۔ تہٕ میون آقا تروو میہ تکیازِ تریہ دۅہہ برونہہ گوس بہٕ بیمار۔\n14.\\tاسہِ کٔر چیریتھیس کِس جنوبس پیٹھ تہٕ {ساحل} یُس یہوداہ سٍتـ̡ تہٕ کالبس کِس جنوبس کُن چُھہ حملہٕ۔ تہٕ اسہِ زٲلۍ زِکلاگ نارٕ سٍتۍ۔\n15.\\tتہٕ داؤد ووٚن أمِس زِ کیا ژٕ ہیککھا مے یَتھ صحبتس مَنٛز أنِتھ؟ تہٕ تٔمۍ ووٚن، خدایہِ سٕندِ قسم، زِ ژٕ کٔرٕ نہٕ مے مٲرِتھ تہٕ نہ کٔرٕ مے میٲنِس آقا سٕندِس اتھس منٛز، تہٕ بہٕ اَننہٕ ژے یَتھ صحبتس منٛز۔\n16.\\tتہٕ ییلہ أمِس بۄن دِنہٕ آمُت، وُچھ تِم ٲسۍ سٲرۍسٕے زمینس پیٹھ پھٔہلِتھ، کھٮ۪وان چیوان تہٕ نژان، تِکیازِ تِمو ٲس فلسطینن ہٕنزِ سرزمینہٕ منزٕ تہٕ یہوداہ کِس سرزمینہٕ منزٕ نِنہٕ آمٕژ۔\n17.\\tتہٕ داؤدَن دِژ تِمن شفقہٕ پیٹھٕ دویمِس دۅہہٕ شامَس تام تہٕ ژٔلِتھ ژٔلِتھ۔ {بیاکھ ...: ہیب۔ تہند پہر}\n18.\\tتہٕ داؤد کٔر سُہ سورُے یُس عمالیقیو نِمُت اوس، تہٕ داؤدَن بچٲوۍ پنٕنۍ دون زنانہٕ۔\n19.\\tتہٕ تِمن ٲس نہٕ کانہہ کٔمی، نہ لۄکٕٹ تہٕ بٔڈ، نہ نیچوۍ تہٕ کورِ، نہ غنیمت، تہٕ نہ کانہہ چیز یُس تِمو تِمن نِش نِمُت اوس۔\n20.\\tتہٕ داؤد نِش نِش سارِنٕے ریوٕے تہٕ کھیٚلہٕ، {یُس} تِمو یِمن {باقی} چارواین برونہہ کُن لٔگِتھ تہٕ وونُن، یہِ چُھ داؤد سُند غنیمت۔\n21.\\tتہٕ داؤد آو تِمن دون ہتن نفرن نِش، یِم تیوٗت کمزور ٲسۍ زِ تِم ہیوٚک نہٕ داؤدٕچ پیروی کٔرِتھ، یُس تِمو تہِ بیسورس کِس نالہِ منز روزنہٕ خٲطرٕ بنٲومُت اوس، تہٕ تِم گٔیہِ داؤدس سمکھنہٕ خٲطرٕ، تہٕ یِمن لُکن سٍتـ̡ أمِس سٍتـ̡ مِلنہٕ خٲطرٕ، تہٕ ییلہ داؤد لُکن نِش ووت، تٔمۍ کٔر تِمن سلام۔ {سلام...: یا، تمن پرژھکھ تمن کتھہ پاٹھۍ کر}\n22.\\tاَمہِ پتہٕ دِژ داؤدَس سٍتـ̡ یِمن سارِنٕے بدکار نفرن تہٕ بِلیال سٕندِس مردس سٍتـ̡ جواب تہٕ وونُن، کیازِ تِم ٲسۍ نہٕ اسہِ سٍتـ̡ گٔمٕتۍ، أسـ̡ یُس غنیمت حٲصل کٔرِتھ أسـ̡ دِنہٕ آمُت، سوائے پرٮ۪تھ أکِس مردس سٕنزِ زنانہِ تہٕ تٔمۍ سٕندِس شُرِس یُس تِمن نِش نیرِتھ نیرِ۔ {تِم: ہیب۔ مرد}\n23. اَمہِ پَتہٕ ووٚن داؤد، یُس خداوند اسہِ دِیُتمُت چُھ، یُس اسہِ رژھرٲوِتھ چُھ، تہٕ یُس اسہِ خلاف سٲنس اتھس منز آو۔\n24.\\tتکیازِ اتھ معاملس منز کُس کرِ تۅہہِ سٍتـ̡ بوزنہٕ؟ مگر یُتھ زن تمۍ سُند حصہ {چُھ} یُس جنگس تام واتان چُھ، تِتھے پٲٹھۍ چُھ تٔمۍ سُند حصہٕ {be} یُس چیزن سٍتۍ رٔٹِتھ روزِ: تِم گژھن ہِوٕے پٲٹھۍ۔\n25.\\tتہٕ تمہِ دۅہہ پیٹھٕ بنوو یہ از تام اسرائیلہٕ خٲطرٕ اکھ قانون تہٕ آرڈیننس۔ {فارورڈ: ہیب۔ تہٕ فارورڈ}\n26. تہٕ ییلہ داؤد زِکلاگ آو تٔمۍ سوٗز غنیمت یہوداہ کین بزرگن نِش، حتیٰ کہ پننین یارن نِش تہِ وونُن، وُچھِو تۅہہِ خٲطرٕ خداوند سٕندِ دُشمنن ہٕندِ غنیمتُک تحفہٕ۔ {موجود: ہیب۔ برکت}\n27.\\tتِمن {تِم} یِم {ٲس} بِتھلس مَنٛز، تہٕ {تِم} یِم {ٲس} جنوبی راموتس مَنٛز، تہٕ {تِم} کُن یِم {ٲس} جتیرس مَنٛز،\n28.\\tتہٕ {تِم} یِم {ٲس} آروورَس مَنٛز، تہٕ {تِم} یِم {ٲس} سِفموتھس مَنٛز، تہٕ {تِم} یِم {ٲس} اِشتِمواہس مَنٛز،\n29.\\tتہٕ تِمن {تِم} یِم راچلس مَنٛز ٲسۍ، تہٕ {تِم} یِم {ٲس} یِم {ٲس} یِمن ہٕندِس شہرس مَنٛز، تہٕ {تِم} یِم {ٲس} کِنیتن ہٕندِس شہرس مَنٛز،\n30.\\tتہٕ یِمن {تِم} یِم ہورمہِ مَنٛز {ٲس}، تہٕ {تِم} یِم چوراشنس مَنٛز {ٲس}، تہٕ {تِم} یِمن ہُند {ٲس} اتھاچس مَنٛز،\n31.\\tتہٕ تِمن {تِم} یِم حبرونس مَنٛز ٲسۍ، تہٕ تِمن سارِنٕے جاین ییتہِ داؤد پانہٕ تہٕ تٔمۍ سٕندِس نفرس روزان ٲسۍ۔","1. وۅنۍ لوٚگ فلسطینیو اسرائیلس سٍتـ̡ جنگ۔ تہٕ اسرٲیلٕکۍ مرد ژٔل فلسطینن برونہہ کُن تہٕ گٔیہِ گلبوا پہاڑس مَنٛز مارنہٕ۔ {قتل: یا، زخمی}\n2.\\tتہٕ فلسطینی لٔج ساؤل تہٕ تٔمۍ سٕندِس نیچوِس پٲٹھۍ۔ تہٕ فلسطینیو مور جوناتھن تہٕ ابیناداب تہٕ ملکیشوا ساؤل سٕندِ نیچوۍ۔\n3.\\tتہٕ جنگ گۆو ساؤلس سٍتـ̡ تہٕ تیر اندازو لوٚگ أمِس لٔگۍ۔ تہٕ سُہ اوس تیر اندازن ہٕندِ دٔسۍ زخم۔ {تہٕ تیر انداز: ہیب۔ تہٕ شوٹر، کمان وٲل مرد} {ہٹ...: ہیب۔ لٔبِتھ سُہ لٔب}\n4. اَمہِ پتہٕ ووٚن ساؤلَن پننِس ہتھیار بردارس سٍتـ̡ پَنٕنـ̡ تلوار تُلِتھ تہٕ دِیُن مےٚ اَتھ سٍتـ̡ دِنہٕ۔ یِم ختنہٕ نہٕ یِنہٕ یِن تہٕ مےٚ دِنہٕ تہٕ دِنہٕ تہٕ مےٚ بدسلوکی کرنہٕ۔ مگر تٔمۍ سُنٛد ہتھیار بردار اوس نہٕ۔ تکیازِ تس اوس کھوژان۔ تێمہِ کِنۍ تُل ساؤلن تلوار تہٕ پیوٚو اتھ پیٹھ۔ {بدسلوکی...: یا، مَضموٗن کٔرِو}\n5. تہٕ ییلہ تٔمۍ سٕندِس ہتھیار بردارس وُچھ زِ ساؤل چُھ موٗدمُت، سُہ پیوٚو تِتھۍ تلوارس پیٹھ، تہٕ موٗد أمِس سٍتـ̡ ۔\n6. یێمہِ دۅہہ موٗد ساؤل تہٕ تٔمۍ سٕندِ تریہ نیچوۍ تہٕ تٔمۍ سٕندِ ہتھیار بردار تہٕ تٔمۍ سٕندِس سٲری نفر اَمہ دۅہہ اِکہٕ وٹہٕ۔\n7. تہٕ ییلہ اسرٲیلٕکۍ لُکھ یُس وادی ہٕندِس دوٚیمہِ طرفہٕ اوس، تہٕ یِمو یِم اردن کِس دوٚیمہِ طرفہٕ ٲسۍ، وُچھ زِ اسرٲیلٕکۍ نفر ژٔلِتھ تہٕ ساؤل تہٕ تٔمۍ سٕندِ نیچوۍ گٔیہِ مٔرۍمٕتۍ، تِمو ژٔلِتھ شہر تہٕ ژٔلِتھ ژٔلِتھ۔ تہٕ فلسطینی آیہِ تہٕ تِمن منز روزُن۔\n8.\\tتہٕ پگہہ سپدِتھ ییلہ فلسطینی مقتولن کُن کڈنہِ آیہ، تِمو وُچھ ساؤل تہٕ تٔمۍ سٕندِ تریہ نیچوۍ گِلبوع کِس پہاڑس مَنٛز پیوٚو۔\n9.\\tتہٕ تِمو ژٔٹِتھ تٔمۍ سُند کلہٕ ژٔٹِتھ تہٕ تٔمۍ سُند ہتھیار ژٔٹِتھ تہٕ سوزُکھ فلسطینن ہٕندِس ملکس منز، یُس تِمن ہٕندِس بُتن ہٕندِس گرس مَنٛز تہٕ لُکن مَنٛز شایع کرنہٕ خٲطرٕ۔\n10.\\tتہٕ تِمو تھوو تٔمۍ سُند ہتھیار آشتروت کِس گرس مَنٛز، تہٕ تِمو تھووُن تٔمۍ سُند لاش بیت شان کِس دیوارس سٍتـ̡ بند۔\n11.\\tتہٕ یێلہِ یێلہِ یێلہِ یێلہِ فلسطینیو ساؤلس سٍتـ̡ کٔرمٕژ ٲس یہِ خبر بوزمٕژ۔ {تتھ منز: یا، تس متعلق یہ}\n12.\\tسارِوٕے بہادر لٔگِتھ وٲتِتھ سارِوٕے رٲژ تہٕ ساؤل سٕنز لاش تہٕ تٔمۍ سٕندٮ۪ن نیچوین ہٕنزِ لاشہٕ نِش نِتھ کٔرِکھ یِم تتہِ زٲلِتھ۔\n13.\\tتہٕ تِمو کٔرِکھ پنٕنۍ أڈجہِ تہٕ جابشس مَنٛز أکِس کُلِس تَل دفن، تہٕ سَتن دۅہن روزُن۔"];
